-- The schema, as one migration.
--
-- GENERATED from supabase/schema/*.sql by scripts/codebase/build-baseline.mjs. Do not edit this file: edit
-- the numbered file the change belongs to and run the script again.
--
-- Everything a new client's database needs, in order, with no history. The 248 migrations of the
-- Hub this template came from are not carried: they never described their own result, and the
-- questions only they answered are answered by this repository's own history.
--
-- The catalogue of pages and roles is NOT here. It is project data, in supabase/catalogue.sql,
-- applied after this file and replaced wholesale by each client.

-- ===================================================================== 0000_common.sql

-- Small helpers every other file may use. No tables, no policies, no client anything.

begin;

create extension if not exists pgcrypto;
create extension if not exists pg_trgm;
-- Semantic search over documents. A client who never asks a question in words still pays nothing
-- for having it available.
create extension if not exists vector;

-- A folder path as a client writes one: absolute, trimmed, no trailing slash, no doubled slash and
-- no control characters. Null means nothing is set, which is always allowed.
create or replace function public.is_folder_path(p_path text) returns boolean
language sql immutable
as $$
  select p_path is null
      or (btrim(p_path) = p_path
          and left(p_path, 1) = '/'
          and length(p_path) > 1
          and right(p_path, 1) <> '/'
          and p_path !~ '[[:cntrl:]]'
          and p_path not like '%//%');
$$;

-- Name matching that survives how a name is actually typed on a document.
create or replace function public.normalized_name(p_name text) returns text
language sql immutable
as $$
  select nullif(btrim(regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', ' ', 'g')), '');
$$;

-- Attach where a table should stamp itself rather than trust the caller.
create or replace function public.set_updated_at() returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

commit;

-- ===================================================================== 0001_identity.sql

-- Who a person is, and which role they hold.
--
-- The role is a label, not a decision. What a role may do lives in 0002_permissions, so an
-- intermediate level is a row somebody adds rather than a migration somebody writes.
--
-- Written for any client. No business, no area names, no seeded people.

begin;

create table if not exists public.roles (
    id uuid primary key default gen_random_uuid(),
    name text not null unique,
    label text not null default '',
    -- Whether this role may be handed out in the team screen.
    assignable boolean not null default true,
    -- Whether this role administers: manages people, rights and settings. A flag rather than a name,
    -- so a client can call its roles anything and add levels without a migration.
    administers boolean not null default false,
    -- A protected role cannot be assigned, deactivated, renamed or deleted. The break-glass account.
    protected boolean not null default false,
    sort_order integer not null default 100,
    created_at timestamptz not null default now()
);

comment on table public.roles is 'A preset over the permission catalogue. Roles decide nothing by themselves.';

create table if not exists public.app_users (
    id uuid primary key default gen_random_uuid(),
    auth_user_id uuid,
    email text not null,
    name text,
    role_id uuid references public.roles(id),
    is_active boolean not null default false,
    must_change_password boolean not null default false,
    picture_url text,
    -- Who stands in while this person is away, and after how many days it escalates to them.
    deputy_user_id uuid references public.app_users(id),
    escalation_days integer,
    -- A client may split its business into areas. The names are that client's data, never a list here.
    area text,
    covers_all_areas boolean not null default false,
    slack_user_id text,
    -- Who this person is in the CRM, so they see only what the CRM says is theirs.
    crm_external_id text,
    notifications_seen_at timestamptz,
    -- Set by set_practice_mode(), cleared by passing false. While in the future, this person sees
    -- only their own practice rows on the demo-flagged tables, never real ones. See 0010_access.sql.
    practice_mode_until timestamptz,
    created_by uuid,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint app_users_area_shape check ((area is null) or (not covers_all_areas)),
    constraint app_users_deputy_not_self check ((deputy_user_id is null) or (deputy_user_id <> id)),
    constraint app_users_escalation_days_positive check ((escalation_days is null) or (escalation_days > 0))
);

create unique index if not exists app_users_email_lower_idx on public.app_users (lower(email));
create index if not exists app_users_role_id_idx on public.app_users (role_id);
create unique index if not exists app_users_crm_external_id_idx on public.app_users (crm_external_id)
    where crm_external_id is not null;
create unique index if not exists app_users_one_active_per_area on public.app_users (area)
    where area is not null and is_active;

-- Which companies a person may see. No live rows for a person means no restriction, which is what
-- lets a single-company client ignore this table entirely.
--
-- A grant is withdrawn by setting deleted_at, never by deleting the row: who could see what, and
-- until when, is exactly the question an access review asks. The row also stays so the same grant
-- can be given back by clearing the field rather than by inserting a second one.
create table if not exists public.user_company_access (
    user_id uuid not null references public.app_users(id) on delete cascade,
    -- No foreign key: companies are created in 0003, and identity must stand on its own.
    company_id uuid not null,
    -- Room for a grant that is recorded but not active, without deleting it.
    can_view boolean not null default true,
    granted_at timestamptz not null default now(),
    granted_by uuid,
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    primary key (user_id, company_id)
);

create index if not exists user_company_access_company_idx on public.user_company_access (company_id);

-- The person behind the current request, resolved from the token's email rather than trusted from
-- the client. Security definer because the caller cannot read other people's rows.
create or replace function public.current_app_user_id() returns uuid
language sql stable security definer set search_path to 'public'
as $$
  select id
    from public.app_users
   where lower(email) = lower(coalesce(auth.jwt() ->> 'email', ''))
     and is_active
   limit 1;
$$;

-- Whether the signed-in person is currently trying the app out in practice mode. Read by the
-- restrictive RLS policies in 0010_access.sql, so it must exist before that file runs.
create or replace function public.practice_mode_active() returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select coalesce(
    (select u.practice_mode_until > now() from public.app_users u where u.id = public.current_app_user_id()),
    false
  );
$$;

create or replace function public.current_role_name() returns text
language sql stable security definer set search_path to 'public'
as $$
  select r.name
    from public.app_users u
    join public.roles r on r.id = u.role_id
   where lower(u.email) = lower(coalesce(auth.jwt() ->> 'email', ''))
     and u.is_active
   limit 1;
$$;

-- Reads the flag on the role, never a role name, so the role set stays the client's own.
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select coalesce((
    select r.administers
      from public.app_users u
      join public.roles r on r.id = u.role_id
     where lower(u.email) = lower(coalesce(auth.jwt() ->> 'email', ''))
       and u.is_active
     limit 1
  ), false);
$$;

-- The break-glass account is guarded in the database, not by a disabled button: any admin can reach
-- these tables directly through the API, so the rule has to live where the write lands. Which role
-- is protected is data, in roles.protected.
create or replace function public.guard_protected_role_row() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_old_protected boolean;
  v_new_protected boolean;
begin
  if tg_op = 'DELETE' then
    select protected into v_old_protected from public.roles where id = old.role_id;
    if coalesce(v_old_protected, false) then
      raise exception 'This account cannot be deleted.' using errcode = 'insufficient_privilege';
    end if;
    return old;
  end if;

  select protected into v_old_protected from public.roles where id = old.role_id;
  select protected into v_new_protected from public.roles where id = new.role_id;

  if coalesce(v_new_protected, false) and not coalesce(v_old_protected, false) then
    raise exception 'This role cannot be assigned.' using errcode = 'insufficient_privilege';
  end if;

  if not coalesce(v_old_protected, false) then
    return new;
  end if;

  if new.is_active is distinct from old.is_active and new.is_active = false then
    raise exception 'This account cannot be deactivated.' using errcode = 'insufficient_privilege';
  end if;

  if new.role_id is distinct from old.role_id then
    raise exception 'This account cannot change role.' using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;

create or replace function public.guard_protected_role_insert() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  if exists (select 1 from public.roles where id = new.role_id and protected) then
    raise exception 'This role cannot be assigned.' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

drop trigger if exists app_users_protected_role_no_insert on public.app_users;
create trigger app_users_protected_role_no_insert before insert on public.app_users
    for each row execute function public.guard_protected_role_insert();

drop trigger if exists app_users_protected_role_stays_active on public.app_users;
create trigger app_users_protected_role_stays_active before update on public.app_users
    for each row execute function public.guard_protected_role_row();

drop trigger if exists app_users_protected_role_no_delete on public.app_users;
create trigger app_users_protected_role_no_delete before delete on public.app_users
    for each row execute function public.guard_protected_role_row();

alter table public.roles enable row level security;
alter table public.app_users enable row level security;
alter table public.user_company_access enable row level security;

-- Every policy is dropped before it is created. Postgres ORs permissive policies of the same
-- command together, so one stale `using (true)` left behind makes every scoped policy meaningless.
drop policy if exists roles_read on public.roles;
create policy roles_read on public.roles for select to authenticated using (true);

drop policy if exists roles_write on public.roles;
create policy roles_write on public.roles for all to authenticated
    using (public.is_admin()) with check (public.is_admin());

drop policy if exists app_users_self_read on public.app_users;
create policy app_users_self_read on public.app_users for select to authenticated
    using (lower(email) = lower(coalesce(auth.jwt() ->> 'email', '')));

-- Widened in 0002 to include has_permission('page.team'), once that function exists.
drop policy if exists app_users_admin_read on public.app_users;
create policy app_users_admin_read on public.app_users for select to authenticated
    using (public.is_admin());

drop policy if exists app_users_admin_insert on public.app_users;
create policy app_users_admin_insert on public.app_users for insert to authenticated
    with check (public.is_admin());

drop policy if exists app_users_admin_update on public.app_users;
create policy app_users_admin_update on public.app_users for update to authenticated
    using (public.is_admin()) with check (public.is_admin());

-- Also widened in 0002, same reason.
drop policy if exists user_company_access_read on public.user_company_access;
create policy user_company_access_read on public.user_company_access for select to authenticated
    using (public.is_admin() or user_id = public.current_app_user_id());

drop policy if exists user_company_access_write on public.user_company_access;
create policy user_company_access_write on public.user_company_access for all to authenticated
    using (public.is_admin()) with check (public.is_admin());

commit;

-- ===================================================================== 0002_permissions.sql

-- What may be done here, who may do it, and what this client uses at all.
--
-- Two questions, kept apart and answered in one place:
--   entitlement  does this client use this feature. `default_enabled`, overridden per client in
--                feature_settings. It can only ever remove.
--   permission   may this person use it. role_permissions, deviated per person in user_permissions.
--
-- Everything reads the answer through current_permissions(), including RLS, so the menu, a typed
-- URL and the database can never disagree.
--
-- This file holds the MECHANISM and no keys. The catalogue is project data and lives in
-- supabase/catalogue.sql, which a client's own set replaces wholesale.

begin;

create table if not exists public.permissions (
    key text primary key,
    -- module, page, section or action. A module owns pages, a page owns sections and actions.
    kind text not null default 'action',
    parent_key text references public.permissions(key) on delete cascade,
    category text not null default '',
    label_de text not null default '',
    label_en text not null default '',
    description_de text,
    description_en text,
    -- What the product ships with. The client's own answer, if any, is in feature_settings.
    default_enabled boolean not null default true,
    -- Some things may never be switched off: the overview, a person's own profile, and the screen
    -- where rights are administered, because a client who hides it cannot put it back.
    locked boolean not null default false,
    sort_order integer not null default 100,
    constraint permissions_kind_known check (kind in ('module', 'page', 'section', 'action')),
    constraint permissions_not_its_own_parent check (parent_key is distinct from key)
);

create index if not exists permissions_parent_idx on public.permissions (parent_key);

create table if not exists public.role_permissions (
    role_id uuid not null references public.roles(id) on delete cascade,
    permission_key text not null references public.permissions(key) on delete cascade,
    primary key (role_id, permission_key)
);

create table if not exists public.user_permissions (
    user_id uuid not null references public.app_users(id) on delete cascade,
    permission_key text not null references public.permissions(key) on delete cascade,
    -- false is a REVOKE, not an absent row. An absent row means inherit the role.
    granted boolean not null,
    updated_at timestamptz not null default now(),
    primary key (user_id, permission_key)
);

-- What a feature cannot work without.
--
-- Containment is already expressed by parent_key: switching a module off takes its pages with it.
-- This is the other kind of dependency, the one that crosses the tree. Open items are a list of
-- documents the bank has not covered, so they need banking; a payment needs documents to pay.
-- Without this a client switches banking off and keeps a screen that can only ever be empty.
--
-- Declared in the catalogue, because which features a client's product needs is project data.
create table if not exists public.feature_requirements (
    feature_key text not null references public.permissions(key) on delete cascade,
    requires_key text not null references public.permissions(key) on delete cascade,
    primary key (feature_key, requires_key),
    constraint feature_requirements_not_itself check (feature_key <> requires_key)
);

-- Only what somebody switched. No row means default_enabled decides, so a feature added later
-- arrives on without touching anyone's data.
create table if not exists public.feature_settings (
    feature_key text primary key references public.permissions(key) on delete cascade,
    enabled boolean not null,
    updated_by uuid references public.app_users(id),
    updated_at timestamptz not null default now()
);

-- Which features are live for this client.
--
-- Two kinds of dependency, both resolved here:
--   containment  a page belongs to a module, so switching the module off takes the page with it.
--   requirement  a feature cannot work without another one that is not its parent. Open items are
--                documents the bank has not covered, so they need banking.
--
-- Requirements chain, and a chain cannot be expressed in one recursive query because it needs
-- negation, so the set is narrowed until a pass removes nothing.
create or replace function public.live_features() returns table (key text)
language plpgsql stable set search_path to 'public'
as $$
declare
  v_live text[];
  v_before integer;
begin
  select coalesce(array_agg(c.key), '{}')
    into v_live
    from (
      with recursive resolved as (
        select p.key, p.parent_key, coalesce(f.enabled, p.default_enabled) as on_here
          from public.permissions p
          left join public.feature_settings f on f.feature_key = p.key
      ),
      contained as (
        select r.key from resolved r where r.parent_key is null and r.on_here
        union all
        select r.key
          from resolved r
          join contained parent on parent.key = r.parent_key
         where r.on_here
      )
      select contained.key from contained
    ) c;

  loop
    v_before := coalesce(array_length(v_live, 1), 0);
    select coalesce(array_agg(k), '{}')
      into v_live
      from unnest(v_live) as k
     where not exists (
       select 1
         from public.feature_requirements fr
        where fr.feature_key = k
          and not fr.requires_key = any (v_live)
     );
    exit when coalesce(array_length(v_live, 1), 0) = v_before;
  end loop;

  return query select unnest(v_live);
end;
$$;

-- The effective set for the caller: role defaults, deviated per person, then narrowed to what this
-- client actually uses.
create or replace function public.current_permissions() returns setof text
language sql stable security definer set search_path to 'public'
as $$
  with me as (
    select u.id, u.role_id
      from public.app_users u
     where lower(u.email) = lower(coalesce(auth.jwt() ->> 'email', ''))
       and u.is_active
     limit 1
  )
  select p.key
    from public.permissions p
    cross join me
    left join public.user_permissions up on up.user_id = me.id and up.permission_key = p.key
    left join public.role_permissions rp on rp.role_id = me.role_id and rp.permission_key = p.key
   where coalesce(up.granted, rp.permission_key is not null)
     and p.key in (select key from public.live_features());
$$;

create or replace function public.has_permission(p_key text) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select exists (select 1 from public.current_permissions() k where k = p_key);
$$;

-- The catalogue as the two editors need it: the panel during onboarding, and a client's own screen
-- if they are ever given one.
--
-- `effective` is worked out here so nobody re-derives it in TypeScript, and `off_because` says WHY
-- a feature is off, so a screen can tell a client "this is off because banking is off" instead of
-- showing a switch that appears to be theirs to flip and is not.
drop function if exists public.feature_tree();
create or replace function public.feature_tree()
returns table (
    key text, parent_key text, kind text, category text,
    label_de text, label_en text, sort_order integer,
    locked boolean, default_enabled boolean, chosen boolean,
    effective boolean, requires text[], off_because text
)
language sql stable set search_path to 'public'
as $$
  with live as (select key from public.live_features())
  select p.key, p.parent_key, p.kind, p.category,
         p.label_de, p.label_en, p.sort_order,
         p.locked, p.default_enabled, f.enabled,
         p.key in (select key from live),
         coalesce((select array_agg(fr.requires_key order by fr.requires_key)
                     from public.feature_requirements fr
                    where fr.feature_key = p.key), '{}'),
         case
           when p.key in (select key from live) then null
           when not coalesce(f.enabled, p.default_enabled) then 'switched off here'
           when p.parent_key is not null and p.parent_key not in (select key from live)
             then p.parent_key
           else (select fr.requires_key
                   from public.feature_requirements fr
                  where fr.feature_key = p.key
                    and fr.requires_key not in (select key from live)
                  order by fr.requires_key
                  limit 1)
         end
    from public.permissions p
    left join public.feature_settings f on f.feature_key = p.key
   order by p.sort_order, p.key;
$$;

revoke execute on function public.current_permissions() from public, anon;
revoke execute on function public.has_permission(text) from public, anon;
revoke execute on function public.live_features() from public, anon;
revoke execute on function public.feature_tree() from public, anon;
grant execute on function public.current_permissions() to authenticated;
grant execute on function public.has_permission(text) to authenticated;
grant execute on function public.live_features() to authenticated;
grant execute on function public.feature_tree() to authenticated;

-- A locked feature stays on whatever arrives over the API, because a disabled switch in a screen is
-- not a boundary.
create or replace function public.guard_locked_feature() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  if new.enabled = false
     and exists (select 1 from public.permissions p where p.key = new.feature_key and p.locked) then
    raise exception 'This feature cannot be switched off.' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

drop trigger if exists feature_settings_locked on public.feature_settings;
create trigger feature_settings_locked before insert or update on public.feature_settings
    for each row execute function public.guard_locked_feature();

-- A protected role keeps everything, enforced here rather than by a screen. Which role that is
-- comes from roles.protected, never from a name.
create or replace function public.guard_protected_role_permissions() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  if exists (
    select 1 from public.app_users u join public.roles r on r.id = u.role_id
     where u.id = coalesce(new.user_id, old.user_id) and r.protected
  ) then
    if tg_op = 'DELETE' then return null; end if;
    new.granted := true;
  end if;
  return new;
end;
$$;

drop trigger if exists user_permissions_protected_role on public.user_permissions;
create trigger user_permissions_protected_role before insert or update or delete on public.user_permissions
    for each row execute function public.guard_protected_role_permissions();

alter table public.permissions enable row level security;
alter table public.role_permissions enable row level security;
alter table public.user_permissions enable row level security;
alter table public.feature_requirements enable row level security;
alter table public.feature_settings enable row level security;

-- The catalogue is readable by anyone signed in, because a screen has to render the labels and has
-- to tell "this client does not use it" apart from "you have no access".
drop policy if exists permissions_read on public.permissions;
create policy permissions_read on public.permissions for select to authenticated using (true);

drop policy if exists role_permissions_read on public.role_permissions;
create policy role_permissions_read on public.role_permissions for select to authenticated using (true);

drop policy if exists role_permissions_write on public.role_permissions;
create policy role_permissions_write on public.role_permissions for all to authenticated
    using (public.is_admin()) with check (public.is_admin());

drop policy if exists user_permissions_read on public.user_permissions;
create policy user_permissions_read on public.user_permissions for select to authenticated
    using (public.is_admin() or user_id = public.current_app_user_id());

drop policy if exists user_permissions_write on public.user_permissions;
create policy user_permissions_write on public.user_permissions for all to authenticated
    using (public.is_admin()) with check (public.is_admin());

drop policy if exists feature_requirements_read on public.feature_requirements;
create policy feature_requirements_read on public.feature_requirements for select to authenticated using (true);

drop policy if exists feature_settings_read on public.feature_settings;
create policy feature_settings_read on public.feature_settings for select to authenticated using (true);

drop policy if exists feature_settings_write on public.feature_settings;
create policy feature_settings_write on public.feature_settings for all to authenticated
    using (public.is_admin()) with check (public.is_admin());

-- Now that has_permission exists, the two identity policies from 0001 can widen.
--
-- `users.read` is the one key this mechanism names, and it is a contract rather than a screen: a
-- catalogue that declares it lets somebody read the team without administering it, and a catalogue
-- that does not simply leaves reading to administering roles. No project's page name appears here.
drop policy if exists app_users_admin_read on public.app_users;
create policy app_users_admin_read on public.app_users for select to authenticated
    using (public.is_admin() or public.has_permission('users.read'));

drop policy if exists user_company_access_read on public.user_company_access;
create policy user_company_access_read on public.user_company_access for select to authenticated
    using (public.is_admin() or public.has_permission('users.read') or user_id = public.current_app_user_id());

commit;

-- ===================================================================== 0003_master_data.sql

-- The things a document is booked against: companies, properties, suppliers, customers, categories
-- and VAT rates.
--
-- English throughout, including the values. The screen shows whatever the locale file says; the
-- database stores a word a developer in any country can read.
--
-- Nothing here is seeded. A client's companies and categories are their data, loaded through the
-- panel or the app, never written into a schema file.
--
-- Soft delete everywhere: deleted_at, deleted_by and delete_reason. A booked document must keep
-- pointing at something, so a row is retired rather than removed.

begin;

create table if not exists public.companies (
    id uuid primary key default gen_random_uuid(),
    code text not null unique,
    name text not null,
    -- Whether this company books on the invoice date or on the payment date.
    booking_basis text not null default 'invoice_date',
    -- Where a filed copy of this company's documents lands: the path, the provider's own id for
    -- that folder, and how the two were bound together.
    filing_folder text,
    filing_binding text,
    -- What a client calls its parts of the business, if it has any. The names are that client's data.
    area text,
    overhead_cost_centre integer,
    -- A row a person is trying out in practice mode, never a real company. See 0010_access.sql.
    is_demo boolean not null default false,
    demo_owner_user_id uuid references public.app_users(id),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint companies_booking_basis_known check (booking_basis in ('invoice_date', 'payment_date')),
    constraint companies_overhead_cost_centre_positive
        check (overhead_cost_centre is null or overhead_cost_centre > 0),
    constraint companies_filing_folder_shape check (public.is_folder_path(filing_folder))
);

create index if not exists companies_is_demo_idx on public.companies (demo_owner_user_id) where is_demo;

create table if not exists public.properties (
    id uuid primary key default gen_random_uuid(),
    code text not null unique,
    name text not null,
    address text,
    -- How VAT is handled for this property, which the rules read when they decide deductibility.
    vat_status text,
    -- Where a filed copy lands: the path, the provider's own id for that folder, and the binding.
    filing_folder text,
    filing_binding text,
    -- A row a person is trying out in practice mode, never a real property. See 0010_access.sql.
    is_demo boolean not null default false,
    demo_owner_user_id uuid references public.app_users(id),
    -- Where the row came from, and its id there, for a property kept in step with a CRM.
    source text not null default 'app',
    external_id text,
    -- What the CRM says about the property, for a client whose property list is the CRM's. Left empty
    -- everywhere else. The crm_ names keep it apart from the Hub's own status and archive.
    crm_status text,
    crm_status_id text,
    marketing_type text,
    property_type text,
    usage_type text,
    asking_price numeric(14, 2),
    sold_price numeric(14, 2),
    sold_on date,
    living_space numeric(10, 2),
    plot_area numeric(12, 2),
    room_count numeric(5, 1),
    commission_note text,
    broker_external_id text,
    broker_name text,
    broker_email text,
    parties jsonb not null default '[]'::jsonb,
    archived_in_crm boolean not null default false,
    crm_updated_at timestamptz,
    crm_synced_at timestamptz,
    -- The CRM's own record, exactly as it sent it. The columns above are copies taken from it.
    crm_data jsonb,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint properties_filing_folder_shape check (public.is_folder_path(filing_folder)),
    constraint properties_source_external_id unique (source, external_id)
);

create index if not exists properties_is_demo_idx on public.properties (demo_owner_user_id) where is_demo;
create index if not exists properties_crm_status on public.properties (crm_status)
    where crm_status is not null;

-- A property can belong to more than one company, and carries its own cost centre in each.
create table if not exists public.property_companies (
    id uuid primary key default gen_random_uuid(),
    property_id uuid not null references public.properties(id) on delete cascade,
    company_id uuid not null references public.companies(id) on delete cascade,
    cost_centre_number integer,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint property_companies_cost_centre_positive
        check (cost_centre_number is null or cost_centre_number > 0)
);

create unique index if not exists property_companies_pair
    on public.property_companies (property_id, company_id) where deleted_at is null;

create table if not exists public.suppliers (
    id uuid primary key default gen_random_uuid(),
    name text not null,
    normalized_name text,
    vat_id text,
    normalized_vat_ids text[],
    address text,
    contact_person text,
    email text,
    phone text,
    -- The account shown on the supplier itself. The full set, with its evidence, is below.
    iban text,
    bic text,
    bank_name text,
    fax text,
    website text,
    trade text,
    -- A row a person is trying out in practice mode, never a real supplier. See 0010_access.sql.
    is_demo boolean not null default false,
    demo_owner_user_id uuid references public.app_users(id),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text
);

create index if not exists suppliers_normalized_name_idx on public.suppliers (normalized_name);
create index if not exists suppliers_is_demo_idx on public.suppliers (demo_owner_user_id) where is_demo;

-- Every account this supplier has ever been seen with, and who vouched for it. A payment may only
-- use one a person confirmed, which is what stops an invoice with a swapped IBAN being paid.
create table if not exists public.supplier_bank_accounts (
    id uuid primary key default gen_random_uuid(),
    supplier_id uuid not null references public.suppliers(id) on delete cascade,
    iban text not null,
    bic text,
    bank_name text,
    -- Where this account came from. 'pipeline' means it was read off a document.
    source text not null default 'pipeline',
    is_active boolean not null default true,
    is_default boolean not null default false,
    is_payable boolean not null default false,
    first_seen_at timestamptz not null default now(),
    last_seen_at timestamptz,
    confirmed_at timestamptz,
    confirmed_by text,
    created_by text,
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    created_at timestamptz not null default now(),
    constraint supplier_bank_accounts_source_known check (source in ('pipeline', 'human', 'import')),
    -- Masked digits are allowed, since a document often shows only the last four.
    constraint supplier_bank_accounts_iban_shape check (iban ~ '^[A-Z]{2}[0-9*]{2}[A-Z0-9*]{11,30}$'),
    constraint supplier_bank_accounts_default_is_active check (not is_default or is_active),
    constraint supplier_bank_accounts_default_is_payable check (not is_default or is_payable)
);

create index if not exists supplier_bank_accounts_supplier_idx on public.supplier_bank_accounts (supplier_id);

-- One row per account the pipeline has ever seen for a supplier: the pipeline's own upsert
-- (adapters/db/receipt_store.py's _record_bank_account, book-keeping repo) targets exactly this
-- pair with no other predicate, so the constraint has to be a plain one, not partial on deleted_at.
create unique index if not exists supplier_bank_accounts_supplier_iban
    on public.supplier_bank_accounts (supplier_id, iban);

-- Every time a supplier's account changed, and who was looking. A changed IBAN is the single most
-- common invoice fraud, so the trail is kept whether or not anybody asked for it.
create table if not exists public.supplier_iban_history (
    id uuid primary key default gen_random_uuid(),
    supplier_id uuid not null references public.suppliers(id) on delete cascade,
    old_iban text,
    new_iban text,
    changed_by text,
    source text,
    note text,
    changed_at timestamptz not null default now()
);

create index if not exists supplier_iban_history_supplier
    on public.supplier_iban_history (supplier_id, changed_at desc);

create table if not exists public.customers (
    id uuid primary key default gen_random_uuid(),
    company_id uuid references public.companies(id),
    is_company boolean not null default true,
    name text not null,
    normalized_name text,
    contact_person text,
    email text,
    phone text,
    address_street text,
    address_zip text,
    address_city text,
    address_country_code text,
    vat_id text,
    customer_number text,
    source text not null default 'app',
    -- The same person in the CRM and in the accounting tool, so neither is created twice.
    crm_external_id text,
    accounting_external_id text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint customers_source_known check (source in ('app', 'upload', 'crm'))
);

create unique index if not exists customers_crm_external_id
    on public.customers (crm_external_id) where crm_external_id is not null and deleted_at is null;
create unique index if not exists customers_accounting_external_id
    on public.customers (accounting_external_id)
    where accounting_external_id is not null and deleted_at is null;

-- What a cost is booked as. A tree, so a client can group its own way.
create table if not exists public.categories (
    id uuid primary key default gen_random_uuid(),
    code text not null unique,
    name text not null,
    name_en text,
    parent_id uuid references public.categories(id),
    -- Which side of the business this category belongs to.
    direction text not null default 'incoming',
    -- Where this category appears in the client's own report, as names that client chose.
    report_block text,
    report_line text,
    -- A category that never reaches the profit and loss account, for example a loan repayment.
    excluded_from_profit_and_loss boolean not null default false,
    -- The one category everything unmatched falls into. At most one may be marked.
    is_catchall boolean not null default false,
    is_active boolean not null default true,
    sort_order integer not null default 100,
    note text,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint categories_direction_known check (direction in ('incoming', 'outgoing'))
);

create unique index if not exists categories_one_catchall on public.categories (is_catchall)
    where is_catchall and deleted_at is null;

-- The words a client's own people use for a category, so a rule can match what a document says.
create table if not exists public.category_aliases (
    id uuid primary key default gen_random_uuid(),
    category_id uuid not null references public.categories(id) on delete cascade,
    alias text not null,
    is_active boolean not null default true,
    note text,
    created_by text,
    created_at timestamptz not null default now(),
    constraint category_aliases_alias_not_blank check (btrim(alias) <> '')
);

create unique index if not exists category_aliases_unique on public.category_aliases (lower(alias))
    where is_active;

-- The same idea for a company or a property: what it is called on paper, which is rarely its code.
create table if not exists public.entity_aliases (
    id uuid primary key default gen_random_uuid(),
    entity_type text not null,
    entity_code text not null,
    alias text not null,
    is_active boolean not null default true,
    note text,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint entity_aliases_type_known check (entity_type in ('company', 'property', 'category')),
    constraint entity_aliases_alias_not_blank check (btrim(alias) <> '')
);

create unique index if not exists entity_aliases_unique
    on public.entity_aliases (entity_type, lower(alias)) where is_active and deleted_at is null;

-- The rates that may appear on a document, per country. Not seeded: a client's set is their data.
create table if not exists public.vat_rates (
    id uuid primary key default gen_random_uuid(),
    country text not null,
    rate numeric(5, 2) not null,
    is_active boolean not null default true,
    note text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint vat_rates_rate_sane check (rate >= 0 and rate <= 100)
);

create unique index if not exists vat_rates_country_rate on public.vat_rates (country, rate)
    where deleted_at is null;


-- Columns the ingestion pipeline writes. Declared here so a Hub database is one the pipeline can
-- run against: a column it writes and this schema lacks fails the whole run.
-- scripts/db/check-pipeline-columns.mjs holds this file and the pipeline's registry to each other.




commit;

-- ===================================================================== 0004_documents.sql

-- The documents themselves, their files, and everything read off them.
--
-- VOCABULARY. Every stored value is English. The screen says whatever the locale file says, so a
-- German Hub reads German while the database reads the same in any country. The words a client's
-- existing data uses map like this, for whoever writes that migration one day:
--   eingegangen received · in_pruefung in_review · rueckfrage query · freigegeben_assistenz
--   approved_first · freigegeben_vorgesetzter approved_final · bezahlt paid · uebergeben_datev
--   handed_over · abgeschlossen closed · abgelehnt rejected · nicht_relevant not_relevant
--   gruen green · gelb yellow · rot red
--   herstellungsaufwand capital_expense · erhaltungsaufwand maintenance_expense
--
-- The text search configuration is a client setting, not a constant: a German client indexes German.
-- It is applied by 0009_search.sql so this file stays language free.

begin;

create table if not exists public.documents (
    id uuid primary key default gen_random_uuid(),

    -- What it is and where it came from
    document_type text,
    is_invoice boolean,
    source text,
    intake_channel text,
    source_item_id text,
    source_document_id uuid references public.documents(id),
    page_range text,
    content_hash text,

    -- Who issued it and to whom
    issuer text,
    issuer_address text,
    recipient_name text,
    recipient_address text,
    supplier_id uuid references public.suppliers(id),
    customer_number text,

    -- The figures
    invoice_number text,
    order_number text,
    document_date date,
    service_date date,
    service_period_from date,
    service_period_to date,
    due_date date,
    amount_net numeric(14, 2),
    vat_rate numeric(5, 2),
    vat_amount numeric(14, 2),
    amount_gross numeric(14, 2),
    currency text,
    is_small_amount boolean,
    service_description text,
    payment_reference text,
    payment_method text,
    tax_note text,

    -- Written on a receipt by hand, which the printed figures do not say. The tip is on top of the
    -- printed total, so what left the account is amount_gross + tip_amount.
    tip_amount numeric(14, 2),
    occasion text,
    participants text,

    -- What it is booked against
    company_id uuid references public.companies(id),
    company_code text,
    property_id uuid references public.properties(id),
    property_code text,
    business_line_id uuid,
    business_line_code text,
    category_id uuid references public.categories(id),
    cost_category text,
    is_overhead boolean not null default false,

    -- How each of those was decided, so a wrong answer can be traced to what produced it
    assignment_source text,
    company_assignment_source text,
    property_assignment_source text,
    document_type_source text,
    is_invoice_source text,
    assignment_decided_by text,
    cost_category_source text,
    vat_source text,
    paid_source text,

    -- VAT treatment
    vat_treatment text,
    vat_deductible_pct numeric(5, 2),
    vat_deductible_amount numeric(14, 2),
    vat_nondeductible_amount numeric(14, 2),
    vat_deductibility_source text,
    vat_special_case text,
    vat_conflict_at timestamptz,
    vat_conflict_note text,
    income_tax_treatment text,

    -- What the reader made of it
    status text,
    traffic_light text,
    confidence_score numeric(5, 2),
    extracted jsonb,
    validation jsonb,
    validation_detail jsonb,
    ocr_fulltext text,
    line_items jsonb,
    tax jsonb,
    already_paid boolean,

    -- Where the work stands
    workflow_status text not null default 'received',
    assigned_to text,
    assigned_user_id uuid references public.app_users(id),
    approved_by uuid references public.app_users(id),
    urgency text,
    days_until_due integer,
    early_payment_deadline date,
    early_payment_discount_percent numeric(5, 2),
    early_payment_discount_amount numeric(14, 2),
    paid_at timestamptz,
    filed_at timestamptz,
    published_at timestamptz,
    storage_path text,
    uploaded_for_transaction_id uuid,

    -- Handover to the accountant
    handed_over_at timestamptz,
    handover_batch_id uuid,

    -- What the pipeline spent reading it, and under which rules
    llm_model text,
    llm_calls integer,
    llm_input_tokens integer,
    llm_output_tokens integer,
    ai_cost numeric(12, 6),
    rules_version text,
    document_types text[],
    drive_named_at timestamptz,
    note text,
    private_hold boolean not null default false,
    -- Who a private-held document belongs to. Null until an administering role assigns it; see
    -- 0010_access.sql for how this widens read access past administering roles alone.
    private_owner_user_id uuid references public.app_users(id) on delete set null,

    -- Set aside rather than deleted
    not_relevant_at timestamptz,
    not_relevant_by text,
    not_relevant_note text,
    archived_at timestamptz,
    archived_by text,
    archive_note text,
    mailbox_reset_at timestamptz,

    -- A row a person is trying out in practice mode, never a real document. See 0010_access.sql.
    is_demo boolean not null default false,
    demo_owner_user_id uuid references public.app_users(id),

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,

    constraint documents_workflow_status_known check (workflow_status in (
        'received', 'in_review', 'query', 'approved_first', 'approved_final',
        'paid', 'handed_over', 'closed', 'rejected', 'not_relevant')),
    constraint documents_traffic_light_known
        check (traffic_light is null or traffic_light in ('green', 'yellow', 'red')),
    constraint documents_vat_deductible_pct_sane
        check (vat_deductible_pct is null or (vat_deductible_pct >= 0 and vat_deductible_pct <= 100)),
    constraint documents_vat_source_known
        check (vat_source is null or vat_source in ('ai', 'rule', 'human')),
    constraint documents_cost_category_source_known
        check (cost_category_source is null or cost_category_source in ('ai', 'rule', 'human')),
    constraint documents_vat_deductibility_source_known
        check (vat_deductibility_source is null or vat_deductibility_source in ('ai', 'rule', 'human')),
    constraint documents_assignment_decided_by_known
        check (assignment_decided_by is null or assignment_decided_by in ('ai', 'rule', 'human')),
    constraint documents_income_tax_treatment_known
        check (income_tax_treatment is null or income_tax_treatment in ('capital_expense', 'maintenance_expense')),
    -- Overhead belongs to the company as a whole, so it cannot also sit on one property.
    constraint documents_overhead_has_no_property check (not (is_overhead and property_id is not null)),
    constraint documents_tip_not_negative check (tip_amount is null or tip_amount >= 0)
);

create index if not exists documents_status on public.documents (status) where deleted_at is null;
create index if not exists documents_workflow_status on public.documents (workflow_status) where deleted_at is null;
create index if not exists documents_company on public.documents (company_id) where deleted_at is null;
create index if not exists documents_property on public.documents (property_id) where deleted_at is null;
create index if not exists documents_supplier on public.documents (supplier_id) where deleted_at is null;
create index if not exists documents_document_date on public.documents (document_date desc) where deleted_at is null;
create index if not exists documents_content_hash on public.documents (content_hash) where deleted_at is null;
create index if not exists documents_is_demo_idx on public.documents (demo_owner_user_id) where is_demo;
create index if not exists documents_private_owner_idx on public.documents (private_owner_user_id) where private_hold;

-- One file per role, so a second scan replaces the first instead of piling up beside it.
create table if not exists public.document_files (
    id uuid primary key default gen_random_uuid(),
    document_id uuid not null references public.documents(id) on delete cascade,
    role text not null default 'original',
    filename text,
    mime text,
    size_bytes bigint,
    storage_bucket text,
    storage_path text,
    checksum_sha256 text,
    external_id text,
    source text,
    -- Where the provider keeps it, and the bytes themselves when there is nowhere else to keep them.
    web_url text,
    content bytea,
    transaction_id uuid,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text
);

create unique index if not exists document_files_one_per_role
    on public.document_files (document_id, role) where deleted_at is null;

-- One document pointing at another it is about. A reminder letter names the bill it chases, so the
-- two are never paid separately; a credit note names the bill it reduces; a corrected bill names the
-- one it replaces.
create table if not exists public.document_links (
    id uuid primary key default gen_random_uuid(),
    document_id uuid not null references public.documents(id) on delete cascade,
    related_document_id uuid not null references public.documents(id) on delete cascade,
    kind text not null,
    created_by text,
    created_at timestamptz not null default now(),
    constraint document_links_kind_known check (kind in ('reminder_of', 'credit_for', 'replaces')),
    constraint document_links_not_itself check (document_id <> related_document_id),
    constraint document_links_unique unique (document_id, related_document_id, kind)
);

create index if not exists document_links_related on public.document_links (related_document_id);

-- What happened to this document, in order. The trail a person reads on the detail screen.
create table if not exists public.document_history (
    id uuid primary key default gen_random_uuid(),
    document_id uuid not null references public.documents(id) on delete cascade,
    type text not null,
    text text,
    data jsonb,
    actor text,
    created_at timestamptz not null default now()
);

create index if not exists document_history_document on public.document_history (document_id, created_at desc);

create table if not exists public.document_line_items (
    id uuid primary key default gen_random_uuid(),
    document_id uuid not null references public.documents(id) on delete cascade,
    position integer,
    description text,
    quantity numeric(14, 3),
    unit_price numeric(14, 4),
    amount numeric(14, 2),
    vat_rate numeric(5, 2),
    created_at timestamptz not null default now()
);

create index if not exists document_line_items_document on public.document_line_items (document_id);

-- One row per rate on the document, because a single invoice can carry several.
create table if not exists public.document_taxes (
    id uuid primary key default gen_random_uuid(),
    document_id uuid not null references public.documents(id) on delete cascade,
    rate numeric(5, 2),
    net numeric(14, 2),
    vat_amount numeric(14, 2),
    -- Which tax this row is, for regimes where two rows can share a rate (GST + PST, a
    -- federal/provincial split). Null for a plain VAT line, where the rate alone is unique.
    component text,
    created_at timestamptz not null default now()
);

create index if not exists document_taxes_document on public.document_taxes (document_id);

-- One row per plain VAT rate on a document: the pipeline's own upsert (adapters/db/receipt_store.py's
-- _write_line_items_tax, book-keeping repo) targets exactly this pair with the same predicate, so a
-- future federal/provincial split (a non-null component) stays free to add a second row for the
-- same rate without this constraint blocking it.
create unique index if not exists document_taxes_one_rate
    on public.document_taxes (document_id, rate) where component is null;

-- Every account seen on this document, in the order they appeared. Two accounts on one invoice is
-- the case a person has to look at.
create table if not exists public.document_bank_accounts (
    document_id uuid not null references public.documents(id) on delete cascade,
    supplier_bank_account_id uuid not null references public.supplier_bank_accounts(id) on delete cascade,
    position integer not null default 1,
    origin text,
    first_seen_at timestamptz not null default now(),
    created_at timestamptz not null default now(),
    primary key (document_id, supplier_bank_account_id)
);


commit;

-- ===================================================================== 0005_sources.sql

-- Where documents come in from, what has already been read, and what each run cost.
--
-- A source is a row, never a column: two mailboxes and a drive are three rows of the same shape.
-- The provider is a name the edge resolves, so nothing here knows one provider from another.
--
-- The legacy single-row mail_settings table is deliberately absent. Its folder configuration is a
-- channel with folders, which is what every new client uses.

begin;

create table if not exists public.channels (
    key text primary key,
    -- What sort of source: a mailbox, a folder, a portal. A name, resolved outside the database.
    kind text not null,
    -- Which service serves it. Also a name.
    provider text not null,
    enabled boolean not null default true,
    connection_id text,
    provider_ref text,
    settings jsonb not null default '{}'::jsonb,
    position integer not null default 100,
    updated_at timestamptz not null default now(),
    updated_by text,
    constraint channels_kind_not_blank check (length(btrim(kind)) > 0),
    constraint channels_provider_not_blank check (length(btrim(provider)) > 0),
    constraint channels_settings_is_object check (jsonb_typeof(settings) = 'object')
);

-- Which folders this source reads, and which it moves a handled item into. Role says which is which.
create table if not exists public.channel_folders (
    id uuid primary key default gen_random_uuid(),
    channel_key text not null references public.channels(key) on delete cascade,
    -- Whose folders these are, for a source that can read more than one account.
    identity text not null default '',
    role text not null,
    external_id text not null,
    display_name text,
    -- A folder the provider names itself, such as an inbox, as opposed to one somebody picked.
    well_known_name text,
    -- Whether a run also reads the folders inside this one, such as a folder per month.
    include_children boolean not null default false,
    position integer not null default 100,
    added_at timestamptz not null default now(),
    added_by text,
    constraint channel_folders_role_not_blank check (length(btrim(role)) > 0),
    constraint channel_folders_external_id_not_blank check (length(btrim(external_id)) > 0)
);

create unique index if not exists channel_folders_unique
    on public.channel_folders (channel_key, identity, role, external_id);

create table if not exists public.channel_state (
    channel_key text primary key references public.channels(key) on delete cascade,
    last_check timestamptz,
    checked_at timestamptz
);

-- A source's own keys, sealed before they arrive here. The database never sees a plain value, and
-- nothing in the app reads one back: a value goes out only through an audited reveal.
-- `channel_key` is '' for a credential the whole client uses rather than one source: the model key,
-- the file store. That is the pipeline's own convention, so there is no foreign key here; a key
-- belonging to nothing would have nothing to point at. The trigger below does the cascade instead.
create table if not exists public.credentials (
    channel_key text not null default '',
    name text not null check (length(btrim(name)) > 0),
    value text not null,
    updated_at timestamptz not null default now(),
    updated_by text,
    primary key (channel_key, name)
);

create or replace function public.forget_credentials_of_removed_channel() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
    delete from public.credentials where channel_key = old.key;
    return old;
end;
$$;

drop trigger if exists channels_forget_credentials on public.channels;
create trigger channels_forget_credentials
    after delete on public.channels
    for each row execute function public.forget_credentials_of_removed_channel();

create table if not exists public.credential_reads (
    id bigserial primary key,
    channel_key text,
    credential text not null,
    read_at timestamptz not null default now(),
    read_by text
);

-- How far each folder has been read. Keeping this per folder is what lets one folder fail without
-- holding up the rest.
create table if not exists public.read_cursors (
    channel_key text not null references public.channels(key) on delete cascade,
    identity text not null default '',
    folder_id text not null,
    scope text not null default '',
    bookmark text,
    synced_at timestamptz not null default now(),
    primary key (channel_key, identity, folder_id, scope)
);

-- Everything seen, whether or not it became a document. This is what stops the same item being read
-- twice, and what lets a permanently broken one retire instead of returning every run.
-- `id` is carried for the pipeline, which names a row by it. The key stays the pair, because that
-- pair is what makes reading the same item twice harmless.
create table if not exists public.imported_items (
    id uuid not null default gen_random_uuid(),
    source_item_id text not null,
    attachment_id text not null default '',
    document_id uuid references public.documents(id) on delete set null,
    status text,
    content_hash text,
    content_anchor text,
    imported_at timestamptz not null default now(),
    created_at timestamptz not null default now(),
    primary key (source_item_id, attachment_id)
);

create index if not exists imported_items_document on public.imported_items (document_id);
create index if not exists imported_items_content_hash on public.imported_items (content_hash);

create table if not exists public.pipeline_runs (
    id uuid primary key default gen_random_uuid(),
    source text,
    status text,
    started_at timestamptz not null default now(),
    finished_at timestamptz,
    trigger text,
    request_id uuid,
    processed_count integer not null default 0,
    error_count integer not null default 0,
    filed_count integer,
    skipped_count integer,
    duplicate_count integer,
    discarded_count integer,
    relinked_count integer,

    -- Which folders a run got through, and which it did not, so a partial run says where it stopped.
    folders_read text[],
    folders_skipped jsonb,
    folders_left_unfinished text[],

    ai_calls integer not null default 0,
    llm_model text,
    input_tokens integer,
    cached_input_tokens integer,
    output_tokens integer,
    ai_cost numeric(12, 6),
    note text,
    notes text[]
);

-- One line per item a run touched, including the ones it decided not to keep, with the reason.
create table if not exists public.processing_log (
    id uuid primary key default gen_random_uuid(),
    run_id uuid references public.pipeline_runs(id) on delete set null,
    document_id uuid references public.documents(id) on delete set null,
    source_item_id text,
    subject text,
    sender text,
    body text,
    attachment_name text,
    source text,
    folder text,
    status text,
    reason text,
    sent_at timestamptz,
    processed_at timestamptz not null default now(),
    input_tokens integer,
    output_tokens integer,
    ai_cost numeric(12, 6)
);

create index if not exists processing_log_run on public.processing_log (run_id);
create index if not exists processing_log_document on public.processing_log (document_id);

-- What every model call was for, and what it cost. Priced from a rate somebody entered, never
-- guessed, so a total can be explained.
create table if not exists public.ai_usage (
    id uuid primary key default gen_random_uuid(),
    document_id uuid references public.documents(id) on delete set null,
    run_id uuid references public.pipeline_runs(id) on delete set null,
    kind text not null,
    model text,
    input_tokens integer not null default 0,
    cached_input_tokens integer not null default 0,
    output_tokens integer not null default 0,
    cost numeric(12, 6),
    created_at timestamptz not null default now()
);

create index if not exists ai_usage_document on public.ai_usage (document_id);
create index if not exists ai_usage_run on public.ai_usage (run_id);

-- What should never become a document: a newsletter sender, a subject line, a party.
create table if not exists public.ingest_exclusions (
    id uuid primary key default gen_random_uuid(),
    term text not null,
    -- Which part of an item the term is matched against.
    scope text not null default 'sender',
    is_active boolean not null default true,
    note text,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint ingest_exclusions_scope_known check (scope in (
        'party', 'sender', 'subject', 'filename', 'envelope', 'body',
        'company', 'property', 'supplier'))
);

-- Where a filed copy lands once a document reaches a given state.
create table if not exists public.filing_placements (
    id uuid primary key default gen_random_uuid(),
    channel text not null,
    workflow_status text not null,
    folder_id text not null,
    folder_label text,
    -- A copy may be filed into a folder per month, but only where the target is a fixed folder.
    month_partition boolean not null default false,
    -- A nested layout instead, from the document date: {yyyy}/{mm}_{yyyy} files into 2026/09_2026.
    -- Takes the place of month_partition where it is set.
    partition_pattern text,
    -- Whether the folder is chosen by the document's company, its property, or neither.
    routing text not null default 'fixed',
    is_active boolean not null default true,
    note text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    updated_by text,
    constraint filing_placements_routing_known check (routing in ('fixed', 'company', 'property')),
    constraint filing_placements_month_needs_fixed
        check (routing = 'fixed' or (not month_partition and partition_pattern is null)),
    constraint filing_placements_partition_pattern_shape check (
        partition_pattern is null
        or (partition_pattern ~ '\{(yyyy|mm)\}' and partition_pattern !~ '(^/|/$|//|\.\.)')),
    constraint filing_placements_status_known check (workflow_status in (
        'received', 'in_review', 'query', 'approved_first', 'approved_final',
        'paid', 'handed_over', 'closed', 'rejected', 'not_relevant'))
);

create table if not exists public.filing_attempts (
    document_id uuid not null references public.documents(id) on delete cascade,
    purpose text not null,
    attempts integer not null default 0,
    last_error text,
    last_tried_at timestamptz not null default now(),
    primary key (document_id, purpose)
);

-- How a filed copy is named. Every part is a choice, because every client names differently.
create table if not exists public.filename_settings (
    id boolean primary key default true,
    separator text not null default ' ',
    include_amount boolean not null default true,
    include_property boolean not null default false,
    include_vat_suffix boolean not null default false,
    vat_suffix text not null default '',
    description_source text not null default 'service_description',
    -- Whether letters outside a-z are spelled out, for a drive that dislikes them.
    transliterate_accents boolean not null default true,
    updated_at timestamptz not null default now(),
    updated_by text,
    constraint filename_settings_one_row check (id),
    constraint filename_settings_description_source_known
        check (description_source in ('service_description', 'cost_category', 'none'))
);

-- What this client's pipeline is configured to do, and the keys it needs, as one row.
--
-- The panel writes it, the pipeline reads it, and the Hub shows parts of it. Secrets are sealed
-- before they arrive, so a plain value is never stored here and never returned to a screen.
create table if not exists public.tenant_settings (
    single_row boolean primary key default true,
    config jsonb not null default '{}'::jsonb,
    secrets jsonb not null default '{}'::jsonb,
    updated_at timestamptz not null default now(),
    updated_by text,
    constraint tenant_settings_one_row check (single_row),
    constraint tenant_settings_config_is_object check (jsonb_typeof(config) = 'object'),
    constraint tenant_settings_secrets_is_object check (jsonb_typeof(secrets) = 'object')
);

create table if not exists public.tenant_settings_history (
    id bigserial primary key,
    config jsonb not null,
    changed_at timestamptz not null default now(),
    changed_by text,
    operation text
);

create index if not exists tenant_settings_history_changed
    on public.tenant_settings_history (changed_at desc);

-- A save that changed nothing must not fill the trail; a reviewer needs the real edits.
create or replace function public.tenant_settings_audit() returns trigger
language plpgsql set search_path to 'public'
as $$
begin
    if tg_op = 'UPDATE' and new.config is not distinct from old.config then
        return new;
    end if;
    insert into public.tenant_settings_history (config, changed_by, operation)
    values (old.config, old.updated_by, lower(tg_op));
    return case when tg_op = 'DELETE' then old else new end;
end;
$$;

drop trigger if exists tenant_settings_audit on public.tenant_settings;
create trigger tenant_settings_audit before update or delete on public.tenant_settings
    for each row execute function public.tenant_settings_audit();

-- The one row each of these tables is meant to hold, with everything at its default. A screen that
-- asks for THE settings row must find one.
insert into public.filename_settings (id) values (true) on conflict (id) do nothing;
insert into public.tenant_settings (single_row) values (true) on conflict (single_row) do nothing;


create index if not exists credential_reads_read_idx on public.credential_reads (read_at desc);

-- The pipeline's own copy of this index is not partial. Here it has to be: a term withdrawn is
-- soft deleted rather than removed, and a plain unique index would refuse to add it back.
create unique index if not exists ingest_exclusions_term_scope_uniq
    on public.ingest_exclusions (lower(term), scope)
    where deleted_at is null;



commit;

-- ===================================================================== 0006_bank.sql

-- Bank accounts, what moved through them, and what was paid.
--
-- NO VENDOR NAMES. The aggregator that serves a connection is a row in bank_providers and a handful
-- of provider_* references, never a column called after one company. A client on a different
-- aggregator, or on a manual import alone, uses the same tables.
--
-- Vocabulary is English: a transaction is open, matched or ignored; a match is a candidate, auto,
-- confirmed or rejected.

begin;

-- The banks this deployment can connect to, as the aggregator lists them.
create table if not exists public.bank_providers (
    id uuid primary key default gen_random_uuid(),
    bank_name text not null,
    provider_ref text,
    provider_name text,
    supports_direct_transfer boolean not null default false,
    is_supported boolean not null default true,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

-- One consented connection to a bank. The access handle is a reference, never a credential: the
-- secret itself lives with the other credentials, sealed.
create table if not exists public.bank_connections (
    id uuid primary key default gen_random_uuid(),
    bank_provider_id uuid references public.bank_providers(id),
    provider_ref text,
    provider_access_ref text,
    provider_user text,
    credential_ref text,
    bank_name text,
    provider_name text,
    status text not null default 'pending',
    is_sandbox boolean not null default false,
    last_sync_at timestamptz,
    last_sync_status text,
    metadata jsonb not null default '{}'::jsonb,
    connected_by uuid references public.app_users(id),
    connected_by_email text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    constraint bank_connections_metadata_is_object check (jsonb_typeof(metadata) = 'object')
);

create table if not exists public.bank_accounts (
    id uuid primary key default gen_random_uuid(),
    connection_id uuid references public.bank_connections(id) on delete cascade,
    company_id uuid references public.companies(id),
    provider_account_ref text,
    provider_ref text,
    account_name text,
    -- Whether the name was set by a person, so a sync does not overwrite it.
    name_is_custom boolean not null default false,
    iban text,
    bic text,
    bank_name text,
    holder text,
    product_type text,
    currency text,
    balance numeric(14, 2),
    balance_date date,
    -- An account of this business, as opposed to a counterparty's.
    is_own_account boolean not null default true,
    is_active boolean not null default true,
    is_sandbox boolean not null default false,
    -- How it was connected: through the aggregator, or by hand.
    connect_route text,
    metadata jsonb not null default '{}'::jsonb,
    -- Left out of reconciliation on purpose, with the reason kept.
    excluded_at timestamptz,
    excluded_by text,
    exclusion_reason text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint bank_accounts_metadata_is_object check (jsonb_typeof(metadata) = 'object')
);

create index if not exists bank_accounts_connection on public.bank_accounts (connection_id);
create index if not exists bank_accounts_company on public.bank_accounts (company_id);

create table if not exists public.bank_transactions (
    id uuid primary key default gen_random_uuid(),
    account_id uuid references public.bank_accounts(id) on delete cascade,
    connection_id uuid references public.bank_connections(id) on delete set null,
    company_id uuid references public.companies(id),
    -- What the provider calls this line, used to recognise it again on the next sync.
    provider_hash text,
    external_id text,
    source text not null default 'sync',
    amount numeric(14, 2) not null,
    currency text,
    direction text,
    booking_date date,
    value_date date,
    payment_reference text,
    booking_text text,
    counterparty_holder text,
    counterparty_iban text,
    counterparty_bic text,
    -- Where this line stands against the documents.
    matching_status text not null default 'open',
    -- A card spender, where the money was spent by a person rather than the company account.
    spender_name text,
    spender_email text,
    transaction_type text,
    transaction_type_source text,
    -- What a direct debit carries, so a debit is tied to its creditor and never paid a second time.
    creditor_id text,
    mandate_reference text,
    category_id uuid references public.categories(id),
    category_source text,
    -- Deliberately expected to have no receipt, with the rule that said so.
    no_receipt_reason text,
    no_receipt_set_by text,
    no_receipt_set_at timestamptz,
    whitelist_rule_id uuid,
    -- Fully accounted for by the documents matched to it, even if none covers it alone.
    fully_used_at timestamptz,
    fully_used_by text,
    fully_used_note text,
    is_sandbox boolean not null default false,
    raw_data jsonb,
    -- A row a person is trying out in practice mode, never a real movement. See 0010_access.sql.
    is_demo boolean not null default false,
    demo_owner_user_id uuid references public.app_users(id),
    imported_at timestamptz not null default now(),
    created_at timestamptz not null default now(),
    deleted_at timestamptz,
    constraint bank_transactions_matching_status_known
        check (matching_status in ('open', 'matched', 'ignored')),
    constraint bank_transactions_direction_known
        check (direction is null or direction in ('incoming', 'outgoing'))
);

create index if not exists bank_transactions_account on public.bank_transactions (account_id);
create index if not exists bank_transactions_is_demo_idx on public.bank_transactions (demo_owner_user_id) where is_demo;
create index if not exists bank_transactions_company on public.bank_transactions (company_id);
create index if not exists bank_transactions_booking_date on public.bank_transactions (booking_date desc);
create index if not exists bank_transactions_matching_status on public.bank_transactions (matching_status)
    where deleted_at is null;
create unique index if not exists bank_transactions_provider_hash on public.bank_transactions (provider_hash);

-- What a run of the sync did, for a person asking why a line is missing.
create table if not exists public.bank_sync_logs (
    id uuid primary key default gen_random_uuid(),
    run_id uuid,
    connection_id uuid references public.bank_connections(id) on delete cascade,
    event text not null,
    level text not null default 'info',
    message text,
    counts jsonb,
    created_at timestamptz not null default now(),
    deleted_at timestamptz
);

create index if not exists bank_sync_logs_connection on public.bank_sync_logs (connection_id, created_at desc);

-- A document against a transaction. Several documents may share one line, and one document may be
-- split across lines, so this is a table rather than a column on either side.
create table if not exists public.document_transaction_matches (
    id uuid primary key default gen_random_uuid(),
    document_id uuid not null references public.documents(id) on delete cascade,
    transaction_id uuid not null references public.bank_transactions(id) on delete cascade,
    status text not null default 'candidate',
    score numeric(5, 2),
    match_reasons jsonb,
    amount_matched numeric(14, 2),
    difference_reason text,
    matched_by text,
    matched_at timestamptz,
    confirmed_by text,
    confirmed_at timestamptz,
    rejected_by text,
    rejected_at timestamptz,
    reject_reason text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint document_transaction_matches_status_known
        check (status in ('candidate', 'auto', 'confirmed', 'rejected'))
);

create unique index if not exists document_transaction_matches_pair
    on public.document_transaction_matches (document_id, transaction_id);

-- How close a transaction has to be to a document before it is offered, and before it is taken.
create table if not exists public.matching_settings (
    id boolean primary key default true,
    amount_tolerance numeric(14, 2) not null default 0.00,
    candidate_threshold numeric(5, 2) not null default 60.00,
    auto_match_threshold numeric(5, 2) not null default 95.00,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint matching_settings_one_row check (id),
    constraint matching_settings_thresholds_ordered check (auto_match_threshold >= candidate_threshold)
);

-- Lines that are expected to have no document, so they stop being chased.
create table if not exists public.open_item_whitelist_rules (
    id uuid primary key default gen_random_uuid(),
    term text not null,
    scope text not null default 'counterparty',
    category text,
    is_active boolean not null default true,
    note text,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint open_item_whitelist_rules_scope_known
        check (scope in ('counterparty', 'reference', 'booking_text'))
);

-- A figure somebody books without a document behind it, such as a monthly accrual.
create table if not exists public.manual_bookings (
    id uuid primary key default gen_random_uuid(),
    company_id uuid references public.companies(id),
    property_id uuid references public.properties(id),
    category_id uuid references public.categories(id),
    period date not null,
    amount numeric(14, 2) not null,
    note text,
    is_recurring boolean not null default false,
    recurrence_until date,
    created_by text,
    updated_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text
);

create index if not exists manual_bookings_company on public.manual_bookings (company_id);

-- A transfer this Hub asked the bank to make. Kept even when it fails, because a client needs to
-- see that it was tried.
create table if not exists public.payment_orders (
    id uuid primary key default gen_random_uuid(),
    document_id uuid references public.documents(id),
    company_id uuid references public.companies(id),
    recipient_name text,
    recipient_iban text,
    recipient_bic text,
    amount numeric(14, 2) not null,
    currency text not null default 'EUR',
    payment_reference text,
    status text not null default 'created',
    status_reason text,
    provider_access_ref text,
    provider_account_ref text,
    provider_payment_ref text,
    -- The same order must never be sent twice, whatever the network did.
    idempotency_key text unique,
    -- Set when the recipient's account changed shortly before this was raised.
    recipient_iban_changed_recently boolean not null default false,
    fraud_flags jsonb,
    is_sandbox boolean not null default false,
    initiated_by uuid references public.app_users(id),
    initiated_at timestamptz,
    authorized_at timestamptz,
    executed_at timestamptz,
    failed_at timestamptz,
    cancelled_at timestamptz,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create index if not exists payment_orders_document on public.payment_orders (document_id);
create index if not exists payment_orders_company on public.payment_orders (company_id);

insert into public.matching_settings (id) values (true) on conflict (id) do nothing;

commit;

-- ===================================================================== 0007_rules.sql

-- The rules a client sets for themselves: what a document is booked as, and who has to approve it.
--
-- A rule is data. Nothing here knows a client's categories, companies or people, and none of it is
-- seeded. Specificity decides which rule wins when several match, so adding one never reorders the
-- others by accident.
--
-- VAT treatments are English: taxable, exempt, reverse_charge, small_business.

begin;

-- What this document should be booked as, when it matches.
create table if not exists public.assignment_rules (
    id uuid primary key default gen_random_uuid(),
    -- Which field the rule sets.
    target text not null,
    -- Matched on any combination of these; the more that are set, the more specific it is.
    supplier_id uuid references public.suppliers(id) on delete cascade,
    company_id uuid references public.companies(id) on delete cascade,
    property_id uuid references public.properties(id) on delete cascade,
    reference_pattern text,
    -- What it sets.
    category_id uuid references public.categories(id),
    cost_category text,
    vat_rate numeric(5, 2),
    vat_treatment text,
    vat_deductible_pct numeric(5, 2),
    vat_special_case text,
    -- Worked out from how many conditions are set, so the winner is never a matter of row order.
    specificity integer not null default 0,
    is_active boolean not null default true,
    note text,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint assignment_rules_target_known check (target in ('cost_category', 'vat_rate')),
    constraint assignment_rules_target_is_set check (
        (target = 'cost_category' and (category_id is not null or cost_category is not null))
        or (target = 'vat_rate' and vat_rate is not null)),
    constraint assignment_rules_vat_treatment_known check (
        vat_treatment is null
        or vat_treatment in ('taxable', 'exempt', 'reverse_charge', 'small_business')),
    constraint assignment_rules_vat_deductible_pct_sane check (
        vat_deductible_pct is null or (vat_deductible_pct >= 0 and vat_deductible_pct <= 100)),
    constraint assignment_rules_vat_extras_need_vat_target check (
        (vat_deductible_pct is null and vat_special_case is null) or target = 'vat_rate')
);

create index if not exists assignment_rules_supplier on public.assignment_rules (supplier_id) where is_active;

-- Who has to approve, and from what amount. Two steps at most, the second skippable.
create table if not exists public.approval_rules (
    id uuid primary key default gen_random_uuid(),
    supplier_id uuid references public.suppliers(id) on delete cascade,
    company_id uuid references public.companies(id) on delete cascade,
    property_id uuid references public.properties(id) on delete cascade,
    min_amount numeric(14, 2) not null default 0,
    step_1_user_id uuid references public.app_users(id),
    step_2_user_id uuid references public.app_users(id),
    skip_step_2 boolean not null default false,
    specificity integer not null default 0,
    is_active boolean not null default true,
    note text,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint approval_rules_min_amount_positive check (min_amount >= 0),
    constraint approval_rules_two_steps_differ check (
        step_2_user_id is null or step_1_user_id is null or step_2_user_id <> step_1_user_id)
);

-- Who stands in an approval chain. A person here is an app user; the extra columns are about the
-- chain, not about the account.
create table if not exists public.approvers (
    id uuid primary key default gen_random_uuid(),
    app_user_id uuid references public.app_users(id) on delete cascade,
    name text not null,
    -- Which step of the chain this person serves. Named by the step, not by a job title.
    step text not null default 'first',
    deputy_name text,
    escalation_days integer,
    -- Whether this person is the one who actually moves the money.
    pays boolean not null default false,
    area text,
    covers_all_areas boolean not null default false,
    is_active boolean not null default true,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint approvers_step_known check (step in ('first', 'final')),
    constraint approvers_escalation_days_positive check (escalation_days is null or escalation_days > 0)
);

-- Where a handover is sent, per company and direction. One address per pairing, so a client who
-- sends incoming and outgoing to different people at the accountant can say so.
create table if not exists public.handover_routes (
    id uuid primary key default gen_random_uuid(),
    company_id uuid not null references public.companies(id) on delete cascade,
    direction text not null,
    address text not null,
    is_enabled boolean not null default false,
    note text,
    updated_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint handover_routes_direction_known check (direction in ('incoming', 'outgoing', 'other'))
);

create unique index if not exists handover_routes_company_direction
    on public.handover_routes (company_id, direction);

create table if not exists public.handover_batches (
    id uuid primary key default gen_random_uuid(),
    company_id uuid not null references public.companies(id) on delete cascade,
    direction text not null,
    invoice_count integer not null default 0,
    total_bytes bigint not null default 0,
    -- What became of the send itself, not of the documents in it.
    status text not null,
    error_message text,
    sent_by text,
    created_at timestamptz not null default now(),
    -- A bounce is the case that matters: the accountant never got it, and nobody notices unless the
    -- Hub says so.
    bounced_at timestamptz,
    bounce_reason text,
    acknowledged_at timestamptz,
    acknowledged_by text,
    constraint handover_batches_direction_known check (direction in ('incoming', 'outgoing', 'other')),
    constraint handover_batches_status_known check (status in ('success', 'error', 'bounced'))
);

create index if not exists handover_batches_company on public.handover_batches (company_id, created_at desc);

-- How a client's own categories map onto the accounts their accountant uses.
create table if not exists public.category_account_mapping (
    id uuid primary key default gen_random_uuid(),
    category_id uuid references public.categories(id) on delete cascade,
    company_id uuid references public.companies(id) on delete cascade,
    account_number text not null,
    account_name text,
    direction text not null default 'incoming',
    is_active boolean not null default true,
    note text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint category_account_mapping_direction_known check (direction in ('incoming', 'outgoing'))
);

create unique index if not exists category_account_mapping_unique
    on public.category_account_mapping (coalesce(company_id, '00000000-0000-0000-0000-000000000000'::uuid), category_id, direction)
    where is_active;

-- How a document earns its place at the top of the review list.
--
-- The checks a reader writes into documents.validation are named by the rule pack, not by this
-- schema, so they are rows rather than a list inside a view. A client who cares more about a missing
-- invoice number than a failed sum says so by changing a weight, and nothing is deployed.
create table if not exists public.review_score_rules (
    check_key text primary key,
    weight integer not null default 10,
    -- Some checks are pointless below the small-amount threshold, where the law asks for less.
    applies_to_small_amounts boolean not null default true,
    is_active boolean not null default true,
    note text,
    updated_at timestamptz not null default now(),
    constraint review_score_rules_weight_sane check (weight >= 0 and weight <= 100)
);

-- What low confidence adds on top, as two bands rather than a curve nobody can reason about.
create table if not exists public.review_confidence_bands (
    id boolean primary key default true,
    low_below numeric(4, 2) not null default 0.80,
    low_weight integer not null default 3,
    medium_below numeric(4, 2) not null default 0.95,
    medium_weight integer not null default 1,
    -- Which key inside documents.extracted holds the per-field confidences.
    confidence_key text not null default 'confidence',
    updated_at timestamptz not null default now(),
    constraint review_confidence_bands_one_row check (id),
    constraint review_confidence_bands_ordered check (medium_below >= low_below)
);

insert into public.review_confidence_bands (id) values (true) on conflict (id) do nothing;

commit;

-- ===================================================================== 0008_workspace.sql

-- The rest of what a Hub keeps: outgoing invoices, notifications, the audit trail, guided tours and
-- what the assistant cost.
--
-- Nothing here is client specific, and no channel, tour or event type is seeded: what a client is
-- notified about, and by which channel, is a row somebody sets.

begin;

-- A brokered sale, from which one commission invoice per paying party is drafted.
create table if not exists public.deals (
    id uuid primary key default gen_random_uuid(),
    company_id uuid references public.companies(id),
    property_id uuid references public.properties(id),
    property_label text,
    source text not null default 'app',
    external_id text,
    status text not null default 'incomplete',
    notarised_on date,
    purchase_price numeric(14, 2),
    vat_rate numeric(5, 2) not null default 19.00,
    acquired_by uuid references public.app_users(id),
    handled_by uuid references public.app_users(id),
    -- What a broker's bonus depends on, ticked by the broker or read from the CRM.
    own_lead boolean not null default false,
    from_viewing boolean not null default false,
    costs_closed_at timestamptz,
    ready_for_bookkeeping_at timestamptz,
    referrer_customer_id uuid references public.customers(id),
    note text,
    approved_by uuid references public.app_users(id),
    approved_at timestamptz,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint deals_status_known
        check (status in ('incomplete', 'ready', 'approved', 'invoiced', 'cancelled')),
    constraint deals_purchase_price_positive check (purchase_price is null or purchase_price > 0),
    constraint deals_approval_complete check ((approved_by is null) = (approved_at is null))
);

create unique index if not exists deals_source_external_id on public.deals (source, external_id)
    where external_id is not null;
create index if not exists deals_company on public.deals (company_id) where deleted_at is null;

drop trigger if exists deals_touch on public.deals;
create trigger deals_touch before update on public.deals
    for each row execute function public.set_updated_at();

-- What one side of a deal pays: a net percentage of the price, or a fixed net amount.
create table if not exists public.deal_sides (
    id uuid primary key default gen_random_uuid(),
    deal_id uuid not null references public.deals(id) on delete cascade,
    side text not null,
    fee_kind text not null,
    fee_net_rate numeric(6, 3),
    fee_net_amount numeric(14, 2),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique (deal_id, side),
    constraint deal_sides_side_known check (side in ('buyer', 'seller')),
    -- The fee may still be missing on an incomplete deal, but never belong to the other kind.
    constraint deal_sides_fee_shape check (
        (fee_kind = 'percent' and fee_net_amount is null and (fee_net_rate is null or fee_net_rate > 0))
        or (fee_kind = 'fixed' and fee_net_rate is null and (fee_net_amount is null or fee_net_amount > 0)))
);

drop trigger if exists deal_sides_touch on public.deal_sides;
create trigger deal_sides_touch before update on public.deal_sides
    for each row execute function public.set_updated_at();

-- Who pays on a side, and the discount that person was granted. No share on any party of a side means they split it equally.
create table if not exists public.deal_parties (
    id uuid primary key default gen_random_uuid(),
    deal_side_id uuid not null references public.deal_sides(id) on delete cascade,
    customer_id uuid not null references public.customers(id),
    share_percent numeric(6, 3),
    discount_gross numeric(14, 2) not null default 0,
    discount_reason text,
    position integer not null default 0,
    created_at timestamptz not null default now(),
    unique (deal_side_id, customer_id),
    constraint deal_parties_share_in_range
        check (share_percent is null or (share_percent > 0 and share_percent <= 100)),
    constraint deal_parties_discount_not_negative check (discount_gross >= 0)
);

-- What this business billed, as opposed to what it was billed.
create table if not exists public.outgoing_invoices (
    id uuid primary key default gen_random_uuid(),
    company_id uuid references public.companies(id),
    customer_id uuid references public.customers(id),
    deal_party_id uuid references public.deal_parties(id),
    -- Null is an ordinary invoice. A referral credit is paid out to whoever recommended the customer,
    -- so it names the deal that earned it rather than another invoice.
    kind text,
    deal_id uuid references public.deals(id),
    invoice_number text,
    status text not null default 'draft',
    status_source text,
    invoice_date date,
    due_date date,
    amount_net numeric(14, 2),
    amount_gross numeric(14, 2),
    currency text not null default 'EUR',
    line_items jsonb,
    source text not null default 'app',
    -- How far the chasing has gone, and when the next step is due.
    reminder_level integer not null default 0,
    reminder_due_date date,
    -- When the money is expected, where there is no due date: a seller pays once the purchase price
    -- has reached them, weeks after the invoice.
    expected_payment_on date,
    sent_at timestamptz,
    accounting_external_id text,
    handed_over_at timestamptz,
    handover_batch_id uuid references public.handover_batches(id),
    last_sync_at timestamptz,
    created_by text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    deleted_by text,
    delete_reason text,
    constraint outgoing_invoices_status_known
        check (status in ('draft', 'sent', 'paid', 'overdue', 'cancelled')),
    constraint outgoing_invoices_kind_known
        check (kind is null or kind in ('commission', 'coaching', 'referral_credit')),
    constraint outgoing_invoices_reminder_level_sane check (reminder_level >= 0)
);

create index if not exists outgoing_invoices_company on public.outgoing_invoices (company_id)
    where deleted_at is null;
create unique index if not exists outgoing_invoices_accounting_external_id
    on public.outgoing_invoices (accounting_external_id)
    where accounting_external_id is not null and deleted_at is null;

create table if not exists public.outgoing_invoice_files (
    id uuid primary key default gen_random_uuid(),
    outgoing_invoice_id uuid not null references public.outgoing_invoices(id) on delete cascade,
    filename text,
    mime text,
    size_bytes bigint,
    storage_bucket text,
    storage_path text,
    checksum_sha256 text,
    -- Where the filed copy sits, when it was filed to a drive as well.
    external_id text,
    web_url text,
    created_by text,
    created_at timestamptz not null default now()
);

create table if not exists public.outgoing_invoice_transaction_matches (
    id uuid primary key default gen_random_uuid(),
    outgoing_invoice_id uuid not null references public.outgoing_invoices(id) on delete cascade,
    transaction_id uuid not null references public.bank_transactions(id) on delete cascade,
    status text not null default 'candidate',
    score numeric(5, 2),
    amount_matched numeric(14, 2),
    matched_by text,
    matched_at timestamptz,
    confirmed_by text,
    confirmed_at timestamptz,
    created_at timestamptz not null default now(),
    constraint outgoing_invoice_matches_status_known
        check (status in ('candidate', 'auto', 'confirmed', 'rejected'))
);

create unique index if not exists outgoing_invoice_matches_pair
    on public.outgoing_invoice_transaction_matches (outgoing_invoice_id, transaction_id);

-- Which ways a client can be told something. A channel is a row, so adding one is configuration.
create table if not exists public.notification_channels (
    key text primary key,
    enabled boolean not null default false,
    config jsonb not null default '{}'::jsonb,
    updated_at timestamptz not null default now(),
    constraint notification_channels_config_is_object check (jsonb_typeof(config) = 'object')
);

-- What a notification can point at, so a message can link back to the thing it is about without
-- the notifier knowing every table.
-- What a notification can point at. `send_notification` refuses a kind that is not here, so this
-- is reference data rather than a client's own: an empty table means no notification can name a
-- record at all.
--
-- `source_table` is null for a kind with no record behind it, which is what lets a notification
-- point at a screen. The existence check in `send_notification` skips those on purpose.
create table if not exists public.notification_target_kinds (
    kind text primary key,
    source_table text,
    id_column text not null default 'id',
    is_active boolean not null default true
);

insert into public.notification_target_kinds (kind, source_table, id_column) values
  ('invoice',     'documents',         'id'),
  ('transaction', 'bank_transactions', 'id'),
  ('supplier',    'suppliers',         'id'),
  ('customer',    'customers',         'id'),
  -- A property is addressed by its code, here and in its URL.
  ('property',    'properties',        'code'),
  -- A page is a path, not a row, so there is nothing to look up.
  ('page',        null,                'id')
on conflict (kind) do update
   set source_table = excluded.source_table, id_column = excluded.id_column;

create table if not exists public.notification_events (
    id uuid primary key default gen_random_uuid(),
    type text not null,
    payload jsonb not null default '{}'::jsonb,
    recipient_user_id uuid references public.app_users(id) on delete cascade,
    delivered boolean not null default false,
    acknowledged_at timestamptz,
    created_by text,
    created_at timestamptz not null default now(),
    constraint notification_events_payload_is_object check (jsonb_typeof(payload) = 'object')
);

create index if not exists notification_events_recipient
    on public.notification_events (recipient_user_id, created_at desc);

create table if not exists public.notification_settings (
    user_id uuid primary key references public.app_users(id) on delete cascade,
    -- Which events reach the bell, and which reach a digest.
    bell_events text[] not null default '{}',
    bell_ack boolean not null default false,
    digest_enabled boolean not null default false,
    digest_events text[] not null default '{}',
    digest_channel text,
    digest_time time,
    timezone text not null default 'UTC',
    last_digest_sent_at timestamptz,
    updated_at timestamptz not null default now()
);

create table if not exists public.notification_dispatch_log (
    id uuid primary key default gen_random_uuid(),
    started_at timestamptz not null default now(),
    finished_at timestamptz,
    ok boolean,
    events integer not null default 0,
    digests integer not null default 0,
    errors jsonb
);

-- Who changed what, for every table that wants a trail. Generic on purpose: one table, named by
-- table_name and record_id, so a new feature gets an audit trail without a migration.
create table if not exists public.change_history (
    id uuid primary key default gen_random_uuid(),
    table_name text not null,
    record_id uuid not null,
    type text not null,
    text text,
    data jsonb,
    actor text,
    at timestamptz not null default now()
);

create index if not exists change_history_record on public.change_history (table_name, record_id, at desc);

-- How far each person has got through each guided tour.
create table if not exists public.tour_progress (
    user_id uuid not null references public.app_users(id) on delete cascade,
    tour_id text not null,
    version integer not null default 1,
    status text not null default 'open',
    last_step integer not null default 0,
    first_seen_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    primary key (user_id, tour_id),
    constraint tour_progress_status_known check (status in ('open', 'seen', 'done', 'skipped'))
);

drop trigger if exists tour_progress_touch on public.tour_progress;
create trigger tour_progress_touch before update on public.tour_progress
    for each row execute function public.set_updated_at();

-- What each assistant question cost, per attempt, so a bill can be explained per question.
create table if not exists public.assistant_usage (
    id uuid primary key default gen_random_uuid(),
    search_id uuid,
    question text,
    language text,
    intent text,
    stage text,
    attempt integer not null default 1,
    provider text,
    model text,
    input_tokens integer not null default 0,
    output_tokens integer not null default 0,
    created_at timestamptz not null default now()
);

create index if not exists assistant_usage_search on public.assistant_usage (search_id);

commit;

-- ===================================================================== 0009_search.sql

-- Full text search, in whatever language this client reads.
--
-- THE REASON THIS IS ITS OWN FILE. A search column is the one place a schema cannot stay language
-- free: `to_tsvector('german', ...)` names a language in the column definition, and a generated
-- column cannot read a setting at run time. So the language is applied here, once, from one place a
-- client sets, rather than baked into 0004 where every other client would inherit it.
--
-- Change TEXT_SEARCH_LANGUAGE below for a client that does not read German, then re-run this file.
-- It is the only line in the schema that has an opinion about language.

begin;

do $$
declare
    -- Any configuration Postgres ships: simple, english, german, french, dutch, and so on.
    text_search_language text := 'german';
begin
    if not exists (select 1 from pg_ts_config where cfgname = text_search_language) then
        raise exception 'unknown text search configuration %; pick one from pg_ts_config', text_search_language;
    end if;

    execute format($fmt$
        alter table public.documents
            add column if not exists fts tsvector generated always as (
                setweight(to_tsvector(%L::regconfig,
                    coalesce(invoice_number, '') || ' ' || coalesce(issuer, '')), 'A')
                ||
                setweight(to_tsvector(%L::regconfig,
                    coalesce(service_description, '') || ' ' || coalesce(ocr_fulltext, '')), 'B')
            ) stored
    $fmt$, text_search_language, text_search_language);

    execute format($fmt$
        alter table public.bank_transactions
            add column if not exists fts tsvector generated always as (
                to_tsvector(%L::regconfig,
                    coalesce(payment_reference, '') || ' ' ||
                    coalesce(booking_text, '') || ' ' ||
                    coalesce(counterparty_holder, ''))
            ) stored
    $fmt$, text_search_language);
end
$$;

-- The embedding a question is compared against. Nullable: nothing breaks when it is never filled.
alter table public.documents add column if not exists embedding public.vector(1536);

create index if not exists documents_fts on public.documents using gin (fts);
create index if not exists bank_transactions_fts on public.bank_transactions using gin (fts);

-- Names are searched as people type them, which is rarely how they are spelled.
create index if not exists suppliers_name_trgm on public.suppliers using gin (name gin_trgm_ops);
create index if not exists customers_name_trgm on public.customers using gin (name gin_trgm_ops);
create index if not exists companies_name_trgm on public.companies using gin (name gin_trgm_ops);

commit;

-- ===================================================================== 0010_access.sql

-- Who may read and write each table, enforced by the database rather than by a screen.
--
-- THE CONTRACT. Policies ask for capabilities by name, and these are the names the schema itself
-- relies on. A catalogue declares them; a catalogue that does not simply leaves that area to
-- administering roles, because has_permission() answers false for a key nobody granted.
--
--   users.read           see the team without administering it
--   documents.read       see documents and everything hanging off one
--   documents.write      edit a document
--   master_data.read     see companies, properties, suppliers, customers, categories, VAT rates
--   master_data.write    maintain them
--   bank.read            see accounts and transactions
--   bank.write           reconcile, exclude, mark as needing no receipt
--   payments.write       raise a payment order
--   rules.write          change assignment, approval and handover rules
--   settings.manage      change how this Hub is set up: sources, filing, filenames, notifications
--
-- These are areas, not screens. No page name appears here, so a client can arrange their menu any
-- way without touching a policy.
--
-- Company scoping is separate and additive: where a row names a company, a person who has been
-- granted specific companies sees only those. A person with no grants at all is unrestricted, which
-- is what lets a single-company client ignore the whole idea.

begin;

create or replace function public.has_company_access(p_company_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select case
    when p_company_id is null then true
    when public.is_admin() then true
    when not exists (
      select 1 from public.user_company_access a
       where a.user_id = public.current_app_user_id() and a.can_view and a.deleted_at is null
    ) then true
    else exists (
      select 1 from public.user_company_access a
       where a.user_id = public.current_app_user_id()
         and a.company_id = p_company_id
         and a.can_view
         and a.deleted_at is null
    )
  end;
$$;

revoke execute on function public.has_company_access(uuid) from public, anon;
grant execute on function public.has_company_access(uuid) to authenticated;

create or replace function public.current_crm_external_id() returns text
language sql stable security definer set search_path to 'public'
as $$
  select crm_external_id from public.app_users where id = public.current_app_user_id();
$$;

create or replace function public.owns_deal(p_deal_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select exists (
    select 1
      from public.deals d
      left join public.properties p on p.id = d.property_id
     where d.id = p_deal_id
       and d.deleted_at is null
       and (d.acquired_by = public.current_app_user_id()
            or d.handled_by = public.current_app_user_id()
            or (p.broker_external_id is not null
                and p.broker_external_id = public.current_crm_external_id()))
  );
$$;

create or replace function public.owns_deal_side(p_side_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select exists (select 1 from public.deal_sides s
                  where s.id = p_side_id and public.owns_deal(s.deal_id));
$$;

create or replace function public.owns_customer_through_a_deal(p_customer_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select exists (select 1
                   from public.deal_parties dp
                   join public.deal_sides s on s.id = dp.deal_side_id
                  where dp.customer_id = p_customer_id and public.owns_deal(s.deal_id));
$$;

revoke execute on function public.current_crm_external_id() from public, anon;
revoke execute on function public.owns_deal(uuid) from public, anon;
revoke execute on function public.owns_deal_side(uuid) from public, anon;
revoke execute on function public.owns_customer_through_a_deal(uuid) from public, anon;
grant execute on function public.current_crm_external_id() to authenticated;
grant execute on function public.owns_deal(uuid) to authenticated;
grant execute on function public.owns_deal_side(uuid) to authenticated;
grant execute on function public.owns_customer_through_a_deal(uuid) to authenticated;

-- An administering role holds everything, so a client can never lock themselves out of their own
-- data by mis-editing a role. It does NOT hold what this client has switched off: a feature that is
-- off is off for everybody, which is the difference between a hidden screen and a feature a client
-- does not have. has_permission() already resolves both; this adds the admin path and keeps the
-- entitlement in front of it.
create or replace function public.may_use(p_capability text) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select public.has_permission(p_capability)
      or (public.is_admin()
          and p_capability in (select key from public.live_features()));
$$;

create or replace function public.may_read(p_capability text) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select public.may_use(p_capability);
$$;

create or replace function public.may_write(p_capability text) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select public.may_use(p_capability);
$$;

revoke execute on function public.may_use(text) from public, anon;
grant execute on function public.may_use(text) to authenticated;
revoke execute on function public.may_read(text) from public, anon;
revoke execute on function public.may_write(text) from public, anon;
grant execute on function public.may_read(text) to authenticated;
grant execute on function public.may_write(text) to authenticated;

-- Applied the same way to every table in an area, so a new table cannot be forgotten: the loop is
-- the policy, and a table missing from the lists below has RLS on and no policy, which denies
-- everyone rather than leaking.
do $$
declare
    t text;
    area record;
begin
    for area in
        select * from (values
            ('master_data.read', 'master_data.write', array[
                'companies', 'properties', 'property_companies', 'suppliers',
                'supplier_bank_accounts', 'supplier_iban_history', 'customers',
                'categories', 'category_aliases', 'entity_aliases', 'vat_rates']),
            ('documents.read', 'documents.write', array[
                'documents', 'document_files', 'document_history', 'document_line_items',
                'document_taxes', 'document_bank_accounts', 'document_links', 'outgoing_invoices',
                'outgoing_invoice_files', 'outgoing_invoice_transaction_matches',
                'manual_bookings', 'deals', 'deal_sides', 'deal_parties']),
            ('bank.read', 'bank.write', array[
                'bank_accounts', 'bank_connections', 'bank_transactions', 'bank_providers',
                'bank_sync_logs', 'document_transaction_matches', 'open_item_whitelist_rules']),
            ('payments.write', 'payments.write', array['payment_orders']),
            ('documents.read', 'rules.write', array[
                'assignment_rules', 'approval_rules', 'approvers',
                'handover_batches', 'category_account_mapping']),
            ('documents.read', 'settings.manage', array[
                'channels', 'channel_folders', 'channel_state', 'read_cursors',
                'imported_items', 'pipeline_runs', 'processing_log', 'ai_usage',
                'ingest_exclusions', 'filing_placements', 'filing_attempts', 'filename_settings',
                'matching_settings', 'tenant_settings', 'tenant_settings_history',
                'notification_channels', 'notification_target_kinds',
                'notification_dispatch_log', 'assistant_usage'])
        ) as v(read_capability, write_capability, tables)
    loop
        foreach t in array area.tables loop
            execute format('alter table public.%I enable row level security', t);

            execute format('drop policy if exists %I on public.%I', t || '_read', t);
            execute format(
                'create policy %I on public.%I for select to authenticated using (public.may_read(%L))',
                t || '_read', t, area.read_capability);

            execute format('drop policy if exists %I on public.%I', t || '_write', t);
            execute format(
                'create policy %I on public.%I for all to authenticated using (public.may_write(%L)) with check (public.may_write(%L))',
                t || '_write', t, area.write_capability, area.write_capability);
        end loop;
    end loop;
end
$$;

-- The table policies above cover the row the browser inserts once a file has reached storage, but
-- storage.objects itself carries no policy of its own, so the upload that writes the bytes there
-- is refused before any table is ever touched: "new row violates row-level security policy". Insert
-- only, same as the table policies allow nothing beyond writing a new document in -- overwriting an
-- existing object is a different operation this does not open.
insert into storage.buckets (id, name, public)
values ('documents', 'documents', false), ('outgoing-invoice-files', 'outgoing-invoice-files', false)
on conflict (id) do nothing;

drop policy if exists documents_bucket_write on storage.objects;
create policy documents_bucket_write on storage.objects
    for insert to authenticated
    with check (bucket_id = 'documents' and public.may_write('documents.write'));

drop policy if exists outgoing_invoice_files_bucket_write on storage.objects;
create policy outgoing_invoice_files_bucket_write on storage.objects
    for insert to authenticated
    with check (bucket_id = 'outgoing-invoice-files' and public.may_write('documents.write'));

-- Where a row names a company, the company grants narrow what the capability opened.
do $$
declare
    t text;
begin
    foreach t in array array['documents', 'bank_accounts', 'bank_transactions',
                             'outgoing_invoices', 'manual_bookings', 'payment_orders',
                             'deals'] loop
        execute format('drop policy if exists %I on public.%I', t || '_company_scope', t);
        execute format(
            'create policy %I on public.%I as restrictive for all to authenticated using (public.has_company_access(company_id)) with check (public.has_company_access(company_id))',
            t || '_company_scope', t);
    end loop;
end
$$;

-- What the CRM says is a person's own, whatever their role may read: the properties they are the
-- broker of, the sales those belong to, and the customers on them. Read only, and added to what a
-- role already grants, so it widens nothing for anyone who may read everything.
drop policy if exists properties_own_broker_read on public.properties;
create policy properties_own_broker_read on public.properties for select to authenticated
    using (deleted_at is null and broker_external_id is not null
           and broker_external_id = public.current_crm_external_id());

drop policy if exists deals_own_read on public.deals;
create policy deals_own_read on public.deals for select to authenticated
    using (public.owns_deal(id));

drop policy if exists deal_sides_own_read on public.deal_sides;
create policy deal_sides_own_read on public.deal_sides for select to authenticated
    using (public.owns_deal(deal_id));

drop policy if exists deal_parties_own_read on public.deal_parties;
create policy deal_parties_own_read on public.deal_parties for select to authenticated
    using (public.owns_deal_side(deal_side_id));

drop policy if exists customers_own_deals_read on public.customers;
create policy customers_own_deals_read on public.customers for select to authenticated
    using (public.owns_customer_through_a_deal(id));

-- handover_routes (the DATEV handover addresses) never gets the generic rules.write "for all"
-- policy above: with that policy plus Postgres's default table grants, anyone holding rules.write
-- could PATCH the row directly over the REST API, bypassing set_datev_route() and
-- update_datev_route_status() entirely, along with the auth.uid() and has_company_access() checks
-- written into those two functions and the address column this table exists to keep unreadable.
-- Read stays capability-gated; every write goes through the two SECURITY DEFINER functions, never
-- through a table grant, so there is no direct path left for RLS alone to have to stop.
alter table public.handover_routes enable row level security;

drop policy if exists handover_routes_read on public.handover_routes;
create policy handover_routes_read on public.handover_routes for select to authenticated
    using (public.may_read('documents.read'));

revoke insert, update, delete on public.handover_routes from authenticated;

revoke select on public.handover_routes from authenticated;
grant select (id, company_id, direction, is_enabled, note, updated_by, created_at, updated_at)
    on public.handover_routes to authenticated;

-- A person's own rows, regardless of capability: their notification settings, their tour progress,
-- and what was sent to them.
alter table public.notification_settings enable row level security;
alter table public.notification_events enable row level security;
alter table public.tour_progress enable row level security;

drop policy if exists notification_settings_own on public.notification_settings;
create policy notification_settings_own on public.notification_settings for all to authenticated
    using (user_id = public.current_app_user_id())
    with check (user_id = public.current_app_user_id());

drop policy if exists notification_events_own on public.notification_events;
create policy notification_events_own on public.notification_events for select to authenticated
    using (recipient_user_id = public.current_app_user_id() or public.is_admin());

drop policy if exists notification_events_ack on public.notification_events;
create policy notification_events_ack on public.notification_events for update to authenticated
    using (recipient_user_id = public.current_app_user_id())
    with check (recipient_user_id = public.current_app_user_id());

drop policy if exists tour_progress_own on public.tour_progress;
create policy tour_progress_own on public.tour_progress for all to authenticated
    using (user_id = public.current_app_user_id())
    with check (user_id = public.current_app_user_id());

-- The trail is readable by whoever may read the thing it is about, and written by nobody directly.
alter table public.change_history enable row level security;
drop policy if exists change_history_read on public.change_history;
create policy change_history_read on public.change_history for select to authenticated
    using (public.may_read('documents.read'));

-- Credentials are never selectable, in either table. A value leaves only through an audited reveal
-- that runs with the service role, outside these policies.
alter table public.credentials enable row level security;
alter table public.credential_reads enable row level security;

drop policy if exists credential_reads_read on public.credential_reads;
create policy credential_reads_read on public.credential_reads for select to authenticated
    using (public.may_read('settings.manage'));

-- Practice mode: a person trying the app out sees only their own is_demo rows while it is active,
-- and only real rows otherwise. Restrictive, so it narrows what the area policies above already
-- allow rather than granting anything on its own -- a person with no documents.read grant still
-- sees nothing here either way.
drop policy if exists documents_demo_owner_read on public.documents;
create policy documents_demo_owner_read on public.documents as restrictive for select to authenticated
    using (case when public.practice_mode_active()
                then is_demo and demo_owner_user_id = public.current_app_user_id()
                else not is_demo end);
drop policy if exists documents_demo_owner_write on public.documents;
create policy documents_demo_owner_write on public.documents as restrictive for insert to authenticated
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());
drop policy if exists documents_demo_owner_write_update on public.documents;
create policy documents_demo_owner_write_update on public.documents as restrictive for update to authenticated
    using (not is_demo or demo_owner_user_id = public.current_app_user_id())
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());

drop policy if exists suppliers_demo_owner_read on public.suppliers;
create policy suppliers_demo_owner_read on public.suppliers as restrictive for select to authenticated
    using (case when public.practice_mode_active()
                then is_demo and demo_owner_user_id = public.current_app_user_id()
                else not is_demo end);
drop policy if exists suppliers_demo_owner_write on public.suppliers;
create policy suppliers_demo_owner_write on public.suppliers as restrictive for insert to authenticated
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());
drop policy if exists suppliers_demo_owner_write_update on public.suppliers;
create policy suppliers_demo_owner_write_update on public.suppliers as restrictive for update to authenticated
    using (not is_demo or demo_owner_user_id = public.current_app_user_id())
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());

drop policy if exists companies_demo_owner_read on public.companies;
create policy companies_demo_owner_read on public.companies as restrictive for select to authenticated
    using (case when public.practice_mode_active()
                then is_demo and demo_owner_user_id = public.current_app_user_id()
                else not is_demo end);
drop policy if exists companies_demo_owner_write on public.companies;
create policy companies_demo_owner_write on public.companies as restrictive for insert to authenticated
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());
drop policy if exists companies_demo_owner_write_update on public.companies;
create policy companies_demo_owner_write_update on public.companies as restrictive for update to authenticated
    using (not is_demo or demo_owner_user_id = public.current_app_user_id())
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());

-- For a table with no is_demo column of its own (payment_settings and friends in
-- 0024_payment_files.sql). Security definer so this sees the company's real is_demo flag even
-- when companies_demo_owner_read itself would hide that row from the caller.
create or replace function public.company_demo_visible(p_company_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select case when public.practice_mode_active()
              then exists (
                  select 1 from public.companies c
                   where c.id = p_company_id and c.is_demo
                     and c.demo_owner_user_id = public.current_app_user_id()
              )
              else not exists (
                  select 1 from public.companies c where c.id = p_company_id and c.is_demo
              )
         end;
$$;

revoke execute on function public.company_demo_visible(uuid) from public, anon;
grant execute on function public.company_demo_visible(uuid) to authenticated;

drop policy if exists properties_demo_owner_read on public.properties;
create policy properties_demo_owner_read on public.properties as restrictive for select to authenticated
    using (case when public.practice_mode_active()
                then is_demo and demo_owner_user_id = public.current_app_user_id()
                else not is_demo end);
drop policy if exists properties_demo_owner_write on public.properties;
create policy properties_demo_owner_write on public.properties as restrictive for insert to authenticated
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());
drop policy if exists properties_demo_owner_write_update on public.properties;
create policy properties_demo_owner_write_update on public.properties as restrictive for update to authenticated
    using (not is_demo or demo_owner_user_id = public.current_app_user_id())
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());

drop policy if exists bank_transactions_demo_owner_read on public.bank_transactions;
create policy bank_transactions_demo_owner_read on public.bank_transactions as restrictive for select to authenticated
    using (case when public.practice_mode_active()
                then is_demo and demo_owner_user_id = public.current_app_user_id()
                else not is_demo end);
drop policy if exists bank_transactions_demo_owner_write on public.bank_transactions;
create policy bank_transactions_demo_owner_write on public.bank_transactions as restrictive for insert to authenticated
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());
drop policy if exists bank_transactions_demo_owner_write_update on public.bank_transactions;
create policy bank_transactions_demo_owner_write_update on public.bank_transactions as restrictive for update to authenticated
    using (not is_demo or demo_owner_user_id = public.current_app_user_id())
    with check (not is_demo or demo_owner_user_id = public.current_app_user_id());

-- Private post: mail the pipeline never files into a company folder because it belongs to a person,
-- not the business (briefing: this must not be readable by whoever happens to hold documents.read).
-- Restrictive, so it narrows what the area policies above already allow rather than granting
-- anything on its own -- a person with no documents.read grant still sees nothing here either way.
-- An administering role always sees it; the person it was assigned to (private_owner_user_id) sees
-- that one row once an admin has made the assignment. Nobody else, regardless of capability.
drop policy if exists documents_private_hold_read on public.documents;
create policy documents_private_hold_read on public.documents as restrictive for select to authenticated
    using (not private_hold or public.is_admin() or private_owner_user_id = public.current_app_user_id());
drop policy if exists documents_private_hold_write on public.documents;
create policy documents_private_hold_write on public.documents as restrictive for insert to authenticated
    with check (not private_hold or public.is_admin() or private_owner_user_id = public.current_app_user_id());
drop policy if exists documents_private_hold_write_update on public.documents;
create policy documents_private_hold_write_update on public.documents as restrictive for update to authenticated
    using (not private_hold or public.is_admin() or private_owner_user_id = public.current_app_user_id())
    with check (not private_hold or public.is_admin() or private_owner_user_id = public.current_app_user_id());

-- Everything that hangs off a document follows the document's own visibility. Without this, a
-- private row stayed hidden itself but its files, history, line items, taxes, bank accounts, bank
-- matches, import log and processing log were still readable sideways by document_id, through
-- their own capability-scoped policy alone.
do $$
declare
    t text;
begin
    foreach t in array array['document_files', 'document_history', 'document_line_items',
                              'document_taxes', 'document_bank_accounts',
                              'document_transaction_matches', 'imported_items', 'processing_log',
                              'ai_usage', 'payment_orders'] loop
        execute format('drop policy if exists %I on public.%I', t || '_private_hold_read', t);
        execute format(
            'create policy %I on public.%I as restrictive for select to authenticated using ('
            || '%I.document_id is null or not exists ('
            || 'select 1 from public.documents d where d.id = %I.document_id and d.private_hold '
            || 'and not (public.is_admin() or d.private_owner_user_id = public.current_app_user_id())))',
            t || '_private_hold_read', t, t, t);
    end loop;
end
$$;

-- document_history additionally has to refuse WRITING a row against a private document the caller
-- may not read, the same way documents_private_hold_write guards the document itself.
drop policy if exists document_history_private_hold_write on public.document_history;
create policy document_history_private_hold_write on public.document_history as restrictive for insert to authenticated
    with check (
        not exists (
            select 1 from public.documents d
             where d.id = document_history.document_id and d.private_hold
               and not (public.is_admin() or d.private_owner_user_id = public.current_app_user_id())
        )
    );

-- The trail is written once and never changed, so a client role cannot rewrite its own history
-- after the fact even through a capability it otherwise holds. See 0011_functions.sql and
-- 0014_triggers.sql for the trigger that blocks UPDATE/DELETE/TRUNCATE for every role, including
-- this one's own service role; the revoke below is the belt to that trigger's suspenders.
revoke update, delete, truncate on public.document_history from authenticated, anon;

commit;

-- ===================================================================== 0011_functions.sql

-- The functions the screens call, and the helpers those call in turn.
--
-- Ported from the Hub this template came from, with every renamed table, column and stored value
-- carried across (see RENAMES.md). They sit in one file because most read across several tables,
-- and because a function is easier to find when they are all in one place.
--
-- Anything a person reads still comes from the locale file: these return values, never sentences.

begin;

-- These functions call each other, and they are written here in alphabetical order rather than in
-- dependency order, so a body would fail to validate against a function defined further down. The
-- bodies are checked when they run instead, which is what the screen walk exercises.
--
-- They come BEFORE the views for the same reason in reverse: a view that calls a function cannot be
-- created without it, while a function that reads a view can, as long as its body is not validated
-- yet. The two reference each other, so this is the only order that works.
set local check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.acknowledge_datev_batch(p_batch_id uuid, p_actor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_company uuid;
begin
  if auth.uid() is null then
    raise exception 'acknowledge_datev_batch: authentication required'
      using errcode = 'insufficient_privilege';
  end if;

  select company_id into v_company
    from public.handover_batches
   where id = p_batch_id;

  if v_company is null then
    raise exception 'acknowledge_datev_batch: no batch %', p_batch_id;
  end if;

  if not public.has_company_access(v_company) then
    raise exception 'acknowledge_datev_batch: no access to this company'
      using errcode = 'insufficient_privilege';
  end if;

  update public.handover_batches
     set acknowledged_at = now(),
         acknowledged_by = nullif(btrim(coalesce(p_actor, '')), '')
   where id = p_batch_id
     and status = 'bounced'
     and acknowledged_at is null;
end;
$$;

CREATE OR REPLACE FUNCTION public.acknowledge_notification(p_event_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := public.current_app_user_id();
begin
  if v_user is null then
    raise exception 'acknowledge_notification: no active app_users row for this session'
      using errcode = 'insufficient_privilege';
  end if;

  -- Scoped to the recipient in the WHERE clause rather than checked first: a security definer
  -- function that reads the row and then decides would let somebody else's id through a race.
  -- Already-acknowledged rows keep their original timestamp, so a double click does not rewrite
  -- when it was read.
  update public.notification_events
     set acknowledged_at = now()
   where id = p_event_id
     and recipient_user_id = v_user
     and acknowledged_at is null;
end $$;

CREATE OR REPLACE FUNCTION public.advance_workflow_on_datev_handover() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.handed_over_at is not null and old.handed_over_at is null
     and new.workflow_status = 'paid'
  then
    update public.documents
       set workflow_status = 'handed_over', updated_at = now()
     where id = new.id;

    insert into public.document_history (document_id, type, text, actor)
    values (new.id, 'handed_over', 'Workflow: handed over to the accountant', 'system');
  end if;
  return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.advance_workflow_on_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_text text;
  v_actor text;
begin
  if new.paid_at is not null and old.paid_at is null
     and new.workflow_status in (
       'received', 'in_review', 'query',
       'approved_first', 'approved_final'
     )
  then
    v_text := case new.paid_source
      when 'bank_match' then 'Workflow: paid, confirmed by the bank'
      when 'manual' then 'Workflow: Bezahlt (manuell markiert)'
      when 'payment_file' then 'Workflow: paid, confirmed after a payment file'
      when 'lexware' then 'Workflow: paid, confirmed by Lexware'
      else 'Workflow: Bezahlt'
    end;

    -- nullif guards the empty-string case: a JWT with no email claim would otherwise be recorded
    -- as an actor of '', which reads as a blank line rather than as the system.
    v_actor := coalesce(nullif(auth.jwt() ->> 'email', ''), 'system');

    update public.documents
       set workflow_status = 'paid', updated_at = now()
     where id = new.id;

    insert into public.document_history (document_id, type, text, actor, data)
    values (
      new.id,
      'paid',
      v_text,
      v_actor,
      jsonb_build_object('nach', 'paid', 'paid_source', new.paid_source)
    );
  end if;
  return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.apply_assignment_rule_bulk(p_rule uuid, p_actor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r          public.assignment_rules;
  v_row      record;
  v_res      jsonb;
  v_total    int := 0;
  v_changed  int := 0;
  v_skipped  int := 0;
  v_blocked  int := 0;
  v_ids      uuid[] := array[]::uuid[];
  -- Read once, not per row: it cannot change inside one statement, and has_company_access() is
  -- STABLE but not free.
  v_scoped   boolean := auth.uid() is not null;
begin
  select * into r from public.assignment_rules where id = p_rule and deleted_at is null;
  if not found then
    raise exception 'rule % not found or deleted', p_rule;
  end if;
  if not r.is_active then
    raise exception 'rule % is inactive; activate it before applying it retroactively', p_rule;
  end if;

  for v_row in
    select i.id as id,
           (not v_scoped or public.has_company_access(i.company_id)) as allowed
      from public.documents i
     where i.deleted_at is null
       and i.archived_at is null
       and (r.supplier_id      is null or r.supplier_id      = i.supplier_id)
       and (r.property_id      is null or r.property_id      = i.property_id)
       and (r.company_id       is null or r.company_id       = i.company_id)
       and (
         r.reference_pattern is null
         or coalesce(i.payment_reference, '') ilike '%' || public.escape_ilike_pattern(r.reference_pattern) || '%'
       )
     order by i.created_at
  loop
    -- Counted, then passed over. `matches` stays the number of receipts this caller could have
    -- seen, so it keeps agreeing with what assignment_rule_preview() showed them.
    if not v_row.allowed then
      v_blocked := v_blocked + 1;
      continue;
    end if;

    v_total := v_total + 1;
    v_res := public.apply_assignment_rules(v_row.id, p_actor);
    if jsonb_array_length(v_res->'changed') > 0 then
      v_changed := v_changed + 1;
      v_ids := v_ids || v_row.id;
    elsif jsonb_array_length(v_res->'skipped') > 0 then
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'rule_id', p_rule, 'matches', v_total, 'changed', v_changed, 'skipped', v_skipped,
    'blocked_no_access', v_blocked,
    'changed_ids', to_jsonb(v_ids)
  );
end $$;

CREATE OR REPLACE FUNCTION public.apply_assignment_rules(p_invoice uuid, p_actor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_inv                 public.documents;
  v_rule                 public.assignment_rules;
  v_changed              jsonb := '[]'::jsonb;
  v_skipped               jsonb := '[]'::jsonb;
  v_log_lines             text[] := array[]::text[];
  v_new_amount            numeric;
  v_new_net               numeric;
  v_new_cat_name          text;
  v_cat_changed           boolean;
  v_new_deductible_pct    numeric;
  v_new_deductible_source text;
  v_new_special_case      text;
  v_had_prior_vat         boolean;
  v_old_no_vat            boolean;
  v_new_no_vat            boolean;
  v_conflict              boolean;
begin
  select * into v_inv from public.documents where id = p_invoice and deleted_at is null;
  if not found then
    raise exception 'invoice % not found or deleted', p_invoice;
  end if;

  -- Company scope. A caller with no session at all (the ingestion pipeline's service role, a
  -- trigger firing on insert) is not company restricted and must keep working, so the check is
  -- gated on there being a logged-in person to check.
  if auth.uid() is not null and not public.has_company_access(v_inv.company_id) then
    raise exception 'no access to the company of invoice %', p_invoice
      using errcode = '42501';
  end if;

  -- Cost category (+ structured category_id).
  select * into v_rule
    from public.assignment_rules
   where id = public.resolve_assignment_rule(p_invoice, 'cost_category');
  if found then
    if coalesce(v_inv.cost_category_source, 'ai') = 'human' then
      v_skipped := v_skipped || jsonb_build_object(
        'field', 'cost_category', 'reason', 'human', 'rule_id', v_rule.id);
    else
      if v_rule.category_id is not null then
        select name into v_new_cat_name from public.categories where id = v_rule.category_id;
        v_cat_changed := v_inv.category_id is distinct from v_rule.category_id;
      else
        v_new_cat_name := v_rule.cost_category;
        v_cat_changed := coalesce(v_inv.cost_category, '') <> coalesce(v_rule.cost_category, '');
      end if;

      if v_cat_changed then
        update public.documents
           set category_id = v_rule.category_id,
               cost_category = coalesce(v_new_cat_name, v_rule.cost_category),
               cost_category_source = 'rule',
               updated_at = now()
         where id = p_invoice;
        v_changed := v_changed || jsonb_build_object(
          'field', 'cost_category', 'from', v_inv.cost_category,
          'to', coalesce(v_new_cat_name, v_rule.cost_category), 'rule_id', v_rule.id);
        v_log_lines := v_log_lines || format('Cost category: %s -> %s (rule)',
          coalesce(v_inv.cost_category, 'ohne'), coalesce(v_new_cat_name, v_rule.cost_category));
      end if;
    end if;
  end if;

  -- VAT rate + treatment + deductibility. Deductibility default now comes from the invoice's
  -- PROPERTY (properties.vat_status via resolve_default_vat_deductible_pct), not business_line
  -- (migration 0083).
  select * into v_rule
    from public.assignment_rules
   where id = public.resolve_assignment_rule(p_invoice, 'vat_rate');
  if found then
    if coalesce(v_inv.vat_source, 'ai') = 'human' then
      v_skipped := v_skipped || jsonb_build_object(
        'field', 'vat_rate', 'reason', 'human', 'rule_id', v_rule.id);
    else
      v_new_deductible_pct := coalesce(
        v_rule.vat_deductible_pct, public.resolve_default_vat_deductible_pct(v_inv.property_id)
      );
      v_new_deductible_source := case
        when v_rule.vat_deductible_pct is not null then 'rule'
        when v_new_deductible_pct is not null then 'ai'
        else null
      end;
      v_new_special_case := v_rule.vat_special_case;

      if coalesce(v_inv.vat_rate, -1) <> coalesce(v_rule.vat_rate, -1)
         or coalesce(v_inv.vat_treatment, '') <> coalesce(v_rule.vat_treatment, '')
         or coalesce(v_inv.vat_deductible_pct, -1) <> coalesce(v_new_deductible_pct, -1)
         or coalesce(v_inv.vat_special_case, '') <> coalesce(v_new_special_case, '')
      then
        v_had_prior_vat := v_inv.vat_rate is not null or v_inv.vat_treatment is not null;
        v_old_no_vat := coalesce(v_inv.vat_rate, 0) = 0 or v_inv.vat_treatment = 'small_business';
        v_new_no_vat := coalesce(v_rule.vat_rate, 0) = 0 or v_rule.vat_treatment = 'small_business';
        v_conflict := v_had_prior_vat and (v_old_no_vat is distinct from v_new_no_vat);

        if v_inv.amount_gross is not null and v_rule.vat_rate is not null then
          v_new_amount := round(v_inv.amount_gross * v_rule.vat_rate / (100 + v_rule.vat_rate), 2);
          v_new_net    := v_inv.amount_gross - v_new_amount;
        else
          v_new_net    := v_inv.amount_net;
          v_new_amount := case when v_rule.vat_rate is null then null
                               else round(coalesce(v_inv.amount_net, 0) * v_rule.vat_rate / 100, 2) end;
        end if;

        update public.documents
           set vat_rate = v_rule.vat_rate,
               vat_amount = v_new_amount,
               amount_net = v_new_net,
               vat_treatment = v_rule.vat_treatment,
               vat_source = 'rule',
               vat_deductible_pct = v_new_deductible_pct,
               vat_deductibility_source = v_new_deductible_source,
               vat_special_case = v_new_special_case,
               vat_conflict_at = case when v_conflict then now() else v_inv.vat_conflict_at end,
               vat_conflict_note = case when v_conflict then format(
                 'VAT treatment changed: %s -> %s (rule %s)',
                 case when v_old_no_vat then 'keine USt' else 'USt-pflichtig' end,
                 case when v_new_no_vat then 'keine USt' else 'USt-pflichtig' end,
                 v_rule.id
               ) else v_inv.vat_conflict_note end,
               updated_at = now()
         where id = p_invoice;

        v_changed := v_changed || jsonb_build_object(
          'field', 'vat_rate', 'from', v_inv.vat_rate, 'to', v_rule.vat_rate, 'rule_id', v_rule.id)
          || jsonb_build_object(
          'field', 'vat_amount', 'from', v_inv.vat_amount, 'to', v_new_amount, 'rule_id', v_rule.id);
        if coalesce(v_inv.vat_treatment, '') <> coalesce(v_rule.vat_treatment, '') then
          v_changed := v_changed || jsonb_build_object(
            'field', 'vat_treatment', 'from', v_inv.vat_treatment, 'to', v_rule.vat_treatment,
            'rule_id', v_rule.id);
        end if;
        if coalesce(v_inv.vat_deductible_pct, -1) <> coalesce(v_new_deductible_pct, -1) then
          v_changed := v_changed || jsonb_build_object(
            'field', 'vat_deductible_pct', 'from', v_inv.vat_deductible_pct,
            'to', v_new_deductible_pct, 'rule_id', v_rule.id);
        end if;
        if coalesce(v_inv.vat_special_case, '') <> coalesce(v_new_special_case, '') then
          v_changed := v_changed || jsonb_build_object(
            'field', 'vat_special_case', 'from', v_inv.vat_special_case,
            'to', v_new_special_case, 'rule_id', v_rule.id);
        end if;
        if v_conflict then
          v_changed := v_changed || jsonb_build_object(
            'field', 'vat_conflict', 'from', v_old_no_vat, 'to', v_new_no_vat, 'rule_id', v_rule.id);
        end if;

        v_log_lines := v_log_lines || format(
          'VAT rate: %s -> %s (rule, VAT amount adjusted: %s -> %s%s)',
          coalesce(v_inv.vat_rate::text, 'ohne'), v_rule.vat_rate::text,
          coalesce(v_inv.vat_amount::text, 'ohne'), coalesce(v_new_amount::text, 'ohne'),
          case when v_rule.vat_treatment is not null
               then ', Behandlung: ' || v_rule.vat_treatment else '' end);
        if coalesce(v_inv.vat_deductible_pct, -1) <> coalesce(v_new_deductible_pct, -1) then
          v_log_lines := v_log_lines || format('Deductibility: %s%% -> %s%% (rule)',
            coalesce(v_inv.vat_deductible_pct::text, 'unbestimmt'),
            coalesce(v_new_deductible_pct::text, 'unbestimmt'));
        end if;
        if v_conflict then
          v_log_lines := v_log_lines || format(
            'Careful, the VAT treatment changed: %s -> %s',
            case when v_old_no_vat then 'keine USt' else 'USt-pflichtig' end,
            case when v_new_no_vat then 'keine USt' else 'USt-pflichtig' end);
        end if;
      end if;
    end if;
  end if;

  if array_length(v_log_lines, 1) > 0 then
    insert into public.document_history (document_id, type, text, data, actor)
    values (
      p_invoice,
      'rule',
      array_to_string(v_log_lines, ' · '),
      jsonb_build_object('changed', v_changed, 'skipped', v_skipped),
      p_actor
    );
  end if;

  return jsonb_build_object('changed', v_changed, 'skipped', v_skipped);
end $$;

CREATE OR REPLACE FUNCTION public.apply_opos_whitelist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rule_id  uuid;
  v_category text;
begin
  -- OUTGOING ONLY. The briefing's OPOS question is "what is debited in which company, but the receipt
  -- is missing?", the Hub's "Fehlende Belege" tab filters direction='ausgehend', and the matcher only
  -- looks at amount < 0. Incoming credits therefore never appear in the open-items list, so hiding them
  -- would achieve nothing and would touch rows the other OPOS side (receipts without a transaction)
  -- still needs — a credit is what PAYS one of our outgoing documents.
  --
  -- Tested on amount, NOT on direction: `direction` is GENERATED ALWAYS AS (case when amount < 0 then
  -- 'ausgehend' else 'eingehend' end), and a generated column is computed AFTER before-row triggers, so
  -- new.direction is still NULL here. Reading it would make this guard fire on every insert and the
  -- whitelist would silently never apply. `amount < 0` is the same test, one step earlier.
  if new.amount is null or new.amount >= 0 then
    return new;
  end if;

  -- Never re-decide a transaction that is reconciled with a receipt.
  if new.matching_status = 'matched' then
    return new;
  end if;

  -- Never overwrite or release a HUMAN decision (hidden with no rule behind it).
  if new.matching_status = 'ignored' and new.whitelist_rule_id is null then
    return new;
  end if;

  select m.rule_id, m.category
    into v_rule_id, v_category
    from public.match_opos_whitelist(new.payment_reference, new.counterparty_holder,
                                     new.counterparty_iban, new.booking_text) m;

  if v_rule_id is not null then
    new.matching_status   := 'ignored';
    new.no_receipt_reason := v_category;
    new.whitelist_rule_id := v_rule_id;
    new.no_receipt_set_by := coalesce(new.no_receipt_set_by, 'system');
    new.no_receipt_set_at := coalesce(new.no_receipt_set_at, now());
  elsif new.whitelist_rule_id is not null then
    -- It was hidden BY A RULE and no longer matches (rule deactivated, or the text changed) — release
    -- it back into the open-items list. A human's decision never lands here (guarded above).
    new.matching_status   := 'open';
    new.no_receipt_reason := null;
    new.whitelist_rule_id := null;
    new.no_receipt_set_by := null;
    new.no_receipt_set_at := null;
  end if;

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.approval_rule_specificity(p_supplier_id uuid, p_property_id uuid, p_company_id uuid) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select
    16 * (
        (case when p_supplier_id is not null then 1 else 0 end)
      + (case when p_property_id is not null then 1 else 0 end)
      + (case when p_company_id  is not null then 1 else 0 end)
    )
    + (case when p_supplier_id is not null then 8 else 0 end)
    + (case when p_property_id is not null then 2 else 0 end)
    + (case when p_company_id  is not null then 1 else 0 end);
$$;

-- Runs as the caller, so the deals policies decide who may approve. Only a complete deal can be.
CREATE OR REPLACE FUNCTION public.approve_deal(p_deal_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY INVOKER
    SET search_path TO 'public'
    AS $$
begin
  update public.deals
     set status = 'approved', approved_by = public.current_app_user_id(), approved_at = now()
   where id = p_deal_id and status = 'ready' and deleted_at is null;
  if not found then
    raise exception 'approve_deal: deal % is not ready to approve', p_deal_id
      using errcode = 'check_violation';
  end if;
end;
$$;

-- One outgoing invoice per paying deal_party, amounts computed client side the same way the
-- draft preview already was (src/kit/lib/commission). Trusted the same way save_deal already
-- trusts a submitted deal_sides/deal_parties shape, rather than recomputed here in a second
-- language the two could drift apart in.
CREATE OR REPLACE FUNCTION public.create_deal_invoices(p_deal_id uuid, p_invoices jsonb)
    RETURNS SETOF public.outgoing_invoices
    LANGUAGE plpgsql SECURITY INVOKER
    SET search_path TO 'public'
    AS $$
declare
  v_deal public.deals;
  v_due_date date;
  v_item jsonb;
begin
  select * into v_deal from public.deals where id = p_deal_id and deleted_at is null;
  if not found then
    raise exception 'create_deal_invoices: deal % not found', p_deal_id;
  end if;
  if v_deal.status <> 'approved' then
    raise exception 'create_deal_invoices: deal % is not approved', p_deal_id
      using errcode = 'check_violation';
  end if;

  select p.payment_due_date into v_due_date
    from public.properties p where p.id = v_deal.property_id;

  for v_item in select * from jsonb_array_elements(p_invoices) loop
    insert into public.outgoing_invoices (
      company_id, customer_id, deal_party_id, kind, deal_id,
      status, invoice_date, due_date, amount_net, amount_gross
    ) values (
      v_deal.company_id,
      (v_item ->> 'customer_id')::uuid,
      (v_item ->> 'deal_party_id')::uuid,
      'commission',
      p_deal_id,
      'draft',
      coalesce(v_deal.notarised_on, current_date),
      v_due_date,
      (v_item ->> 'amount_net')::numeric,
      (v_item ->> 'amount_gross')::numeric
    );
  end loop;

  update public.deals set status = 'invoiced' where id = p_deal_id;

  return query select * from public.outgoing_invoices
    where deal_id = p_deal_id and kind = 'commission';
end;
$$;

REVOKE ALL ON FUNCTION public.create_deal_invoices(uuid, jsonb) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.create_deal_invoices(uuid, jsonb) TO authenticated;


CREATE OR REPLACE FUNCTION public.assignment_rule_preview(p_rule uuid) RETURNS TABLE(matches bigint, would_change bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  r public.assignment_rules;
begin
  select * into r from public.assignment_rules where id = p_rule;
  if not found then
    return query select 0::bigint, 0::bigint;
    return;
  end if;

  return query
  with cand as (
    select i.id, i.category_id, i.cost_category, i.cost_category_source,
           i.vat_rate, i.vat_treatment, i.vat_source,
           i.vat_deductible_pct, i.vat_special_case, i.property_id
      from public.documents i
     where i.deleted_at is null
       and i.archived_at is null
       and (r.supplier_id      is null or r.supplier_id      = i.supplier_id)
       and (r.property_id      is null or r.property_id      = i.property_id)
       and (r.company_id       is null or r.company_id       = i.company_id)
       and (
         r.reference_pattern is null
         or coalesce(i.payment_reference, '') ilike '%' || public.escape_ilike_pattern(r.reference_pattern) || '%'
       )
  )
  select
    count(*)::bigint,
    count(*) filter (
      where public.resolve_assignment_rule(c.id, r.target) = r.id
        and case r.target
              when 'cost_category' then
                coalesce(c.cost_category_source, 'ai') <> 'human'
                and (
                  (r.category_id is not null and c.category_id is distinct from r.category_id)
                  or (r.category_id is null and coalesce(c.cost_category, '') <> coalesce(r.cost_category, ''))
                )
              when 'vat_rate' then
                coalesce(c.vat_source, 'ai') <> 'human'
                and (
                  coalesce(c.vat_rate, -1) <> coalesce(r.vat_rate, -1)
                  or coalesce(c.vat_treatment, '') <> coalesce(r.vat_treatment, '')
                  or coalesce(c.vat_deductible_pct, -1) <> coalesce(
                       coalesce(r.vat_deductible_pct, public.resolve_default_vat_deductible_pct(c.property_id)), -1
                     )
                  or coalesce(c.vat_special_case, '') <> coalesce(r.vat_special_case, '')
                )
              else false
            end
    )::bigint
    from cand c;
end $$;

CREATE OR REPLACE FUNCTION public.assignment_rule_preview_scope(p_target text, p_cost_category text DEFAULT NULL::text, p_vat_rate numeric DEFAULT NULL::numeric, p_supplier_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid, p_company_id uuid DEFAULT NULL::uuid, p_reference_pattern text DEFAULT NULL::text, p_exclude_rule uuid DEFAULT NULL::uuid, p_vat_treatment text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_vat_deductible_pct numeric DEFAULT NULL::numeric, p_vat_special_case text DEFAULT NULL::text) RETURNS TABLE(matches bigint, would_change bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_spec int := public.assignment_rule_specificity(
    p_reference_pattern, p_supplier_id, p_property_id, p_company_id
  );
begin
  return query
  with cand as (
    select
      i.category_id, i.cost_category, i.cost_category_source, i.vat_rate, i.vat_treatment,
      i.vat_source, i.vat_deductible_pct, i.vat_special_case, i.property_id,
      (
        select max(r.specificity)
          from public.assignment_rules r
         where r.is_active
           and r.deleted_at is null
           and r.target = p_target
           and (p_exclude_rule is null or r.id <> p_exclude_rule)
           and (r.supplier_id      is null or r.supplier_id      = i.supplier_id)
           and (r.property_id      is null or r.property_id      = i.property_id)
           and (r.company_id       is null or r.company_id       = i.company_id)
           and (
             r.reference_pattern is null
             or coalesce(i.payment_reference, '') ilike '%' || public.escape_ilike_pattern(r.reference_pattern) || '%'
           )
      ) as best
      from public.documents i
     where i.deleted_at is null
       and i.archived_at is null
       and (p_supplier_id      is null or p_supplier_id      = i.supplier_id)
       and (p_property_id      is null or p_property_id      = i.property_id)
       and (p_company_id       is null or p_company_id        = i.company_id)
       and (
         p_reference_pattern is null
         or coalesce(i.payment_reference, '') ilike '%' || public.escape_ilike_pattern(p_reference_pattern) || '%'
       )
  )
  select
    count(*)::bigint,
    count(*) filter (
      where (c.best is null or c.best <= v_spec)
        and case p_target
              when 'cost_category' then
                coalesce(c.cost_category_source, 'ai') <> 'human'
                and (
                  (p_category_id is not null and c.category_id is distinct from p_category_id)
                  or (p_category_id is null and coalesce(c.cost_category, '') <> coalesce(p_cost_category, ''))
                )
              when 'vat_rate' then
                coalesce(c.vat_source, 'ai') <> 'human'
                and (
                  coalesce(c.vat_rate, -1) <> coalesce(p_vat_rate, -1)
                  or coalesce(c.vat_treatment, '') <> coalesce(p_vat_treatment, '')
                  or coalesce(c.vat_deductible_pct, -1) <> coalesce(
                       coalesce(p_vat_deductible_pct, public.resolve_default_vat_deductible_pct(c.property_id)), -1
                     )
                  or coalesce(c.vat_special_case, '') <> coalesce(p_vat_special_case, '')
                )
              else false
            end
    )::bigint
    from cand c;
end $$;

CREATE OR REPLACE FUNCTION public.assignment_rule_specificity(p_reference_pattern text, p_supplier_id uuid, p_property_id uuid, p_company_id uuid) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select
    32 * (
        (case when p_reference_pattern is not null then 1 else 0 end)
      + (case when p_supplier_id       is not null then 1 else 0 end)
      + (case when p_property_id       is not null then 1 else 0 end)
      + (case when p_company_id        is not null then 1 else 0 end)
    )
    + (case when p_reference_pattern is not null then 16 else 0 end)
    + (case when p_supplier_id       is not null then  8 else 0 end)
    + (case when p_property_id       is not null then  2 else 0 end)
    + (case when p_company_id        is not null then  1 else 0 end);
$$;

CREATE OR REPLACE FUNCTION public.bank_sync_log_facets() RETURNS TABLE(events text[], levels text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    coalesce(array_agg(distinct event) filter (where event is not null), '{}'::text[]),
    coalesce(array_agg(distinct level) filter (where level is not null), '{}'::text[])
  from public.bank_sync_logs;
$$;

CREATE OR REPLACE FUNCTION public.capture_supplier_iban_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.iban is distinct from old.iban then
    insert into public.supplier_iban_history (supplier_id, old_iban, new_iban, changed_by, note)
    values (old.id, old.iban, new.iban, coalesce(auth.uid()::text, 'pipeline'), 'iban_changed');
  end if;
  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.cascade_company_code_rename() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Aliases are keyed by the code string, so they move with it. Scoped to 'company' so a
  -- property or supplier alias that happens to share the string is never touched.
  update public.entity_aliases
     set entity_code = new.code
   where entity_type = 'company'
     and entity_code = old.code;

  -- documents.company_code is a denormalised copy. Only rows that genuinely belong to THIS company
  -- are rewritten: those already linked by id, plus unassigned rows that referenced the old code
  -- (the code moved to this company, so the reference moves with it). A row whose company_id points
  -- at a different company is deliberately left alone -- that is pre-existing inconsistent data and
  -- guessing at it here would be the very cross-company mixing this migration exists to prevent.
  update public.documents
     set company_code = new.code
   where company_code = old.code
     and (company_id = new.id or company_id is null);

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.cascade_property_code_rename() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Scoped to 'property' so a company or supplier alias that happens to share the string is untouched.
  update public.entity_aliases
     set entity_code = new.code
   where entity_type = 'property'
     and entity_code = old.code;

  -- documents.property_code is a denormalised copy of the code, with no foreign key behind it. Unlike
  -- the company cascade there is no id column on documents to disambiguate with, so every row holding
  -- the old code follows the rename. That is the correct reading: the code moved to this property,
  -- so references to it move too, and leaving them behind would point at a property that no longer
  -- exists under that name.
  update public.documents
     set property_code = new.code
   where property_code = old.code;

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.chain_people() RETURNS TABLE(id uuid, name text, role_name text, is_active boolean, escalation_days integer, deputy_user_id uuid, area text, covers_all_areas boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select u.id,
         u.name,
         r.name as role_name,
         u.is_active,
         u.escalation_days,
         u.deputy_user_id,
         u.area,
         u.covers_all_areas
    from public.app_users u
    left join public.roles r on r.id = u.role_id
   order by u.name nulls last;
$$;

CREATE OR REPLACE FUNCTION public.team_login_status() RETURNS TABLE(user_id uuid, last_sign_in_at timestamptz, never_signed_in boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select a.id, u.last_sign_in_at, u.last_sign_in_at is null
    from public.app_users a
    left join auth.users u on u.id = a.auth_user_id
   where public.is_admin();
$$;

revoke execute on function public.team_login_status() from public;
revoke execute on function public.team_login_status() from anon;
grant execute on function public.team_login_status() to authenticated;

CREATE OR REPLACE FUNCTION public.channel_secret_name(p_channel text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select 'channel_secret:' || p_channel;
$$;

CREATE OR REPLACE FUNCTION public.channel_secret_present(p_channel text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin() then
    return false;
  end if;
  return exists (
    select 1 from vault.secrets where name = public.channel_secret_name(p_channel)
  );
end;
$$;

CREATE OR REPLACE FUNCTION public.check_match_allocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tx_total  numeric;
  v_tx_other  numeric;
  v_inv_gross numeric;
  v_inv_other numeric;
begin
  if new.status is distinct from 'confirmed' then
    return new;
  end if;

  select abs(amount) into v_tx_total
    from public.bank_transactions where id = new.transaction_id;
  select coalesce(sum(amount_matched), 0) into v_tx_other
    from public.document_transaction_matches
   where transaction_id = new.transaction_id and status = 'confirmed' and id <> new.id;

  if v_tx_total is not null and v_tx_other + new.amount_matched > v_tx_total + 0.01 then
    -- Message text is English like the other raises in this schema (persisted audit text stays
    -- German). RAISE uses % as its placeholder, not %s -- that is format()'s syntax.
    raise exception
      'match allocation: transaction total %, already allocated %, requested % -- would over-allocate',
      v_tx_total, v_tx_other, new.amount_matched
      using errcode = 'check_violation';
  end if;

  select abs(public.amount_paid_out(amount_gross, tip_amount)) into v_inv_gross
    from public.documents where id = new.document_id;
  select coalesce(sum(amount_matched), 0) into v_inv_other
    from public.document_transaction_matches
   where document_id = new.document_id and status = 'confirmed' and id <> new.id;

  if v_inv_gross is not null and v_inv_gross > 0
     and v_inv_other + new.amount_matched > v_inv_gross + 0.01 then
    raise exception
      'match allocation: invoice gross %, already allocated %, requested % -- would over-allocate',
      v_inv_gross, v_inv_other, new.amount_matched
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.check_outgoing_match_allocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tx_total  numeric;
  v_tx_other  numeric;
  v_inv_gross numeric;
  v_inv_other numeric;
begin
  if new.status is distinct from 'confirmed' then
    return new;
  end if;

  select abs(amount) into v_tx_total
    from public.bank_transactions where id = new.transaction_id;
  select coalesce(sum(amount_matched), 0) into v_tx_other
    from public.outgoing_invoice_transaction_matches
   where transaction_id = new.transaction_id and status = 'confirmed' and id <> new.id;

  if v_tx_total is not null and v_tx_other + new.amount_matched > v_tx_total + 0.01 then
    raise exception
      'outgoing match allocation: transaction total %, already allocated %, requested % -- would over-allocate',
      v_tx_total, v_tx_other, new.amount_matched
      using errcode = 'check_violation';
  end if;

  select abs(amount_gross) into v_inv_gross
    from public.outgoing_invoices where id = new.outgoing_invoice_id;
  select coalesce(sum(amount_matched), 0) into v_inv_other
    from public.outgoing_invoice_transaction_matches
   where outgoing_invoice_id = new.outgoing_invoice_id and status = 'confirmed' and id <> new.id;

  if v_inv_gross is not null and v_inv_gross > 0
     and v_inv_other + new.amount_matched > v_inv_gross + 0.01 then
    raise exception
      'outgoing match allocation: invoice gross %, already allocated %, requested % -- would over-allocate',
      v_inv_gross, v_inv_other, new.amount_matched
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.clear_must_change_password() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email text := coalesce(nullif(auth.jwt() ->> 'email', ''), '');
begin
  if v_email = '' then
    raise exception 'clear_must_change_password: no authenticated email' using errcode = 'insufficient_privilege';
  end if;

  update public.app_users
     set must_change_password = false,
         updated_at = now()
   where lower(email) = lower(v_email);

  if not found then
    raise exception 'clear_must_change_password: no app_users row for %', v_email;
  end if;
end;
$$;

CREATE OR REPLACE FUNCTION public.clear_transaction_fully_used(p_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total numeric;
  v_alloc numeric;
begin
  select abs(amount) into v_total from public.bank_transactions where id = p_transaction_id;
  v_alloc := public.transaction_allocated_sum(p_transaction_id)
           + public.outgoing_transaction_allocated_sum(p_transaction_id);

  update public.bank_transactions
     set fully_used_at   = null,
         fully_used_by   = null,
         fully_used_note = null,
         -- Back to what the amounts say, so undoing the stamp reopens the remainder.
         matching_status = case
           when matching_status = 'ignored' then matching_status
           when coalesce(v_alloc, 0) > 0 and v_alloc >= coalesce(v_total, 0) - 0.01 then 'matched'
           else 'open'
         end
   where id = p_transaction_id;
end $$;

CREATE OR REPLACE FUNCTION public.compact_supplier_iban() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    new.iban := upper(regexp_replace(coalesce(new.iban, ''), '[[:space:].-]', '', 'g'));
    return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.enforce_invoice_write_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
  -- Columns governed by another permission, or written by triggers on every update. Anything NOT
  -- in here counts as receipt content and requires documents.write -- so a column added later is
  -- protected by default, and a column that is governed elsewhere has to be named here.
  v_ignore constant text[] := array[
    'workflow_status', 'approved_by',
    'paid_at', 'paid_source',
    'assigned_to', 'assigned_user_id',
    'handed_over_at',
    -- Deletion has no permission of its own today, and inventing one here would narrow who may
    -- delete without that being asked for. Left exactly as it was; worth a key of its own later.
    'deleted_at', 'deleted_by', 'delete_reason',
    'updated_at', 'fts', 'embedding'
  ];
begin
  -- No caller identity: service role, a cron job or the pipeline. They authorize themselves.
  if v_email = '' then
    return new;
  end if;

  if new.paid_at is not null and old.paid_at is null
     and not public.has_permission('payments.write') then
    raise exception 'not permitted: marking an invoice paid requires the payment permission'
      using errcode = '42501';
  end if;

  -- Both columns, so a stray write to the frozen one cannot route around the permission.
  if (new.assigned_user_id is distinct from old.assigned_user_id
      or new.assigned_to is distinct from old.assigned_to)
     and not public.has_permission('documents.write') then
    raise exception 'not permitted: assigning an invoice requires the assign permission'
      using errcode = '42501';
  end if;

  if new.workflow_status is distinct from old.workflow_status then
    if not public.has_permission('invoices.override_workflow') then
      case new.workflow_status
        when 'approved_final', 'closed' then
          if not public.has_permission('invoices.approve_final') then
            raise exception 'not permitted: this status requires the final-approval permission'
              using errcode = '42501';
          end if;
        when 'in_review', 'query', 'approved_first', 'rejected', 'not_relevant' then
          if not public.has_permission('invoices.approve') then
            raise exception 'not permitted: this status requires the approval permission'
              using errcode = '42501';
          end if;
        when 'paid' then
          if new.paid_at is null then
            raise exception 'not permitted: bezahlt is derived from paid_at, set that instead'
              using errcode = '42501';
          end if;
        when 'handed_over' then
          if new.handed_over_at is null then
            raise exception 'not permitted: uebergeben_datev is derived from handed_over_at'
              using errcode = '42501';
          end if;
        else
          raise exception 'not permitted: setting this status requires the override permission'
            using errcode = '42501';
      end case;
    end if;
  end if;

  if (to_jsonb(new) - v_ignore) is distinct from (to_jsonb(old) - v_ignore)
     and not public.has_permission('documents.write') then
    raise exception 'not permitted: editing a receipt requires the booking permission'
      using errcode = '42501';
  end if;

  return new;
end
$$;

CREATE OR REPLACE FUNCTION public.enforce_match_payment_permission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email          text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_was_confirmed  boolean := tg_op <> 'INSERT' and old.status = 'confirmed';
  v_is_confirmed   boolean := tg_op <> 'DELETE' and new.status = 'confirmed';
  v_amount_changed boolean := tg_op = 'UPDATE'
                              and old.status = 'confirmed'
                              and new.amount_matched is distinct from old.amount_matched;
  v_touches_payment boolean;
begin
  -- No caller identity: pipeline, cron or an Edge Function. See the header.
  if v_email = '' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  v_touches_payment := (v_was_confirmed is distinct from v_is_confirmed) or v_amount_changed;

  if v_touches_payment and not public.has_permission('invoices.pay') then
    raise exception
      'not permitted: a confirmed bank match settles the invoice, which requires the payment permission'
      using errcode = '42501';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

CREATE OR REPLACE FUNCTION public.escape_ilike_pattern(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select replace(replace(replace(p_text, '\', '\\'), '%', '\%'), '_', '\_');
$$;

CREATE OR REPLACE FUNCTION public.get_channel_secret(p_channel text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secret text;
begin
  if not exists (select 1 from public.notification_channels where key = p_channel) then
    return null;
  end if;

  select decrypted_secret into v_secret
    from vault.decrypted_secrets
   where name = public.channel_secret_name(p_channel)
   limit 1;
  return v_secret;
end;
$$;

CREATE OR REPLACE FUNCTION public.guard_permission_grants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_actor_role text := public.current_role_name();
  v_target uuid := coalesce(new.user_id, old.user_id);
  v_key text := coalesce(new.permission_key, old.permission_key);
begin
  -- No JWT means a service-role or server-side caller: the seeds, the pipeline and
  -- src/lib/api/*.functions.ts, which do their own authorisation.
  if v_actor is null then
    return coalesce(new, old);
  end if;

  if v_actor = v_target and v_actor_role is distinct from 'super_admin' then
    raise exception 'You cannot change your own rights.'
      using errcode = 'check_violation';
  end if;

  if tg_op <> 'DELETE' and new.granted and v_actor_role is distinct from 'super_admin' then
    if not exists (select 1 from public.current_permissions() k where k = v_key) then
      raise exception 'You cannot grant a right you do not hold yourself: %', v_key
        using errcode = 'check_violation';
    end if;
  end if;

  return coalesce(new, old);
end
$$;

CREATE OR REPLACE FUNCTION public.guard_role_permission_grants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_actor_role text := public.current_role_name();
  v_key text := coalesce(new.permission_key, old.permission_key);
begin
  if v_actor is null or v_actor_role = 'super_admin' then
    return coalesce(new, old);
  end if;

  if tg_op <> 'DELETE' then
    if not exists (select 1 from public.current_permissions() k where k = v_key) then
      raise exception 'You cannot grant a right you do not hold yourself: %', v_key
        using errcode = 'check_violation';
    end if;
  end if;

  return coalesce(new, old);
end
$$;

-- document_history is the audit trail a person reads on the detail screen, so once a row is
-- written it has to stay exactly as written. INSERT is still open to anyone the area policy in
-- 0010_access.sql already lets write; UPDATE, DELETE and TRUNCATE are refused unconditionally, for
-- every role including the pipeline's own service role, which is why this is a trigger and not
-- only the grant revoked beside it. actor/created_at are stamped here rather than trusted from the
-- caller only for authenticated/anon: a client role could otherwise write history under somebody
-- else's name or backdate it; the pipeline's own service-role writes keep the timestamp it sends.
CREATE OR REPLACE FUNCTION public.guard_document_history_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if current_user in ('authenticated', 'anon') then
      new.actor := auth.jwt() ->> 'email';
      new.created_at := now();
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    raise exception 'document_history rows cannot be changed' using errcode = '42501';
  elsif tg_op = 'DELETE' then
    raise exception 'document_history rows cannot be deleted' using errcode = '42501';
  end if;
  raise exception 'document_history cannot be truncated' using errcode = '42501';
end;
$$;

CREATE OR REPLACE FUNCTION public.invoice_iban_checksum_ok(candidate text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  with cleaned as (
    select upper(regexp_replace(btrim(coalesce(candidate, '')), '\s', '', 'g')) as s
  ),
  rearranged as (
    select substr(s, 5) || substr(s, 1, 4) as r, s from cleaned
  ),
  expanded as (
    select string_agg(
      case when ch ~ '[0-9]' then ch else (ascii(ch) - 55)::text end, '' order by ord
    ) as digits
    from rearranged, regexp_split_to_table(r, '') with ordinality as t(ch, ord)
  )
  select case
    when (select s from cleaned) !~ '^[A-Z0-9]{15,34}$' then false
    when (select s from cleaned) !~ '^[A-Z]{2}[0-9]{2}' then false
    else (select digits from expanded)::numeric % 97 = 1
  end;
$_$;

CREATE OR REPLACE FUNCTION public.invoice_is_fully_covered(p_gross numeric, p_matched numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  -- isFullyCovered() in format.ts: no gross amount means never judged covered, and an OVERPAYMENT
  -- counts as covered because more money than owed arrived, so nothing is open. Compared in
  -- numeric, which is exact decimal; the front end rounds to whole cents to reach the same answer
  -- in IEEE754.
  select case
           when abs(coalesce(p_gross, 0)) <= 0 then false
           else round(coalesce(p_matched, 0), 2)
                  >= round(abs(p_gross) - public.payment_tolerance(p_gross), 2)
         end;
$$;

CREATE OR REPLACE FUNCTION public.is_a_reminder(p_document uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.document_links where document_id = p_document and kind = 'reminder_of');
$$;

CREATE OR REPLACE FUNCTION public.amount_paid_out(p_gross numeric, p_tip numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_gross > 0 then p_gross + coalesce(p_tip, 0) else p_gross end;
$$;

CREATE OR REPLACE FUNCTION public.document_is_countable(p_status text, p_private_hold boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select p_status is distinct from 'duplicate' and not coalesce(p_private_hold, false);
$$;

CREATE OR REPLACE FUNCTION public.invoice_matched_sum(p_invoice uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(amount_matched), 0)
    from public.document_transaction_matches
   where document_id = p_invoice and status = 'confirmed';
$$;

CREATE OR REPLACE FUNCTION public.invoice_queue_kpis(p_today date DEFAULT CURRENT_DATE) RETURNS TABLE(key text, count bigint, amount numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
      with base as (select * from public.documents where true and private_hold = false and deleted_at is null and archived_at is null and not_relevant_at is null)
      select 'all'::text, count(*), coalesce(sum(amount_gross), 0) from base
      union all
      select 'needs_action'::text, count(*), coalesce(sum(amount_gross), 0) from base where status = 'needs_review' and is_invoice = true
      union all
      select 'missing_assignment'::text, count(*), coalesce(sum(amount_gross), 0) from base where company_id is null
      union all
      select 'ready_for_payment'::text, count(*), coalesce(sum(amount_gross), 0) from base  where workflow_status in ('approved_first', 'approved_final')    and paid_at is null and not public.is_a_reminder(id)
      union all
      select 'pay_now'::text, count(*), coalesce(sum(amount_gross), 0) from base where due_date <= p_today and paid_at is null and not public.is_direct_debit(payment_method) and not public.is_a_reminder(id)
      union all
      select 'completed'::text, count(*), coalesce(sum(amount_gross), 0) from base where paid_at is not null or workflow_status = 'closed';
    $$;

CREATE OR REPLACE FUNCTION public.invoice_review_state(p_validation_detail jsonb, p_extracted jsonb, p_validation jsonb, p_issuer text, p_invoice_number text, p_document_date date, p_amount_gross numeric, p_amount_net numeric, p_vat_amount numeric, p_vat_rate numeric, p_recipient_name text, p_company_code text, p_supplier_iban text) RETURNS TABLE(problem_count integer, unchecked boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  with raw_detail as (
    select coalesce(
      case when jsonb_typeof(p_validation_detail) = 'object' and p_validation_detail <> '{}'::jsonb
        then p_validation_detail end,
      case when jsonb_typeof(p_extracted -> 'validation_detail') = 'object'
            and (p_extracted -> 'validation_detail') <> '{}'::jsonb
        then p_extracted -> 'validation_detail' end,
      '{}'::jsonb
    ) as d
  ),
  halves as (
    select
      case
        when d ? 'bookkeeping_edits' then
          case when jsonb_typeof(d -> 'bookkeeping_edits') = 'object'
                and (d -> 'bookkeeping_edits') <> '{}'::jsonb
            then d -> 'bookkeeping_edits' else '{}'::jsonb end
        else d
      end as basis,
      case
        when d ? 'bookkeeping_edits' and jsonb_typeof(d -> 'user_edits') = 'object'
          then coalesce(d -> 'user_edits', '{}'::jsonb)
        else '{}'::jsonb
      end as stored_user
    from raw_detail
  ),
  iban_input as (
    select coalesce(
      nullif(btrim(coalesce(p_supplier_iban, '')), ''),
      case when jsonb_typeof(p_extracted -> 'iban') = 'string' then p_extracted ->> 'iban' end
    ) as src
  ),
  iban_candidates as (
    select coalesce(array_agg(part) filter (where part <> ''), '{}'::text[]) as arr
    from iban_input,
      lateral (
        select btrim(piece) as part
        from regexp_split_to_table(coalesce(src, ''), '(?i)([;,/|]|\s{2,}|\y(?:und)\y)') as piece
      ) parts
    where src is not null
  ),
  numbers as (
    select
      coalesce(
        case
          when jsonb_typeof(p_extracted -> 'subtotal_gross') = 'number'
            then (p_extracted ->> 'subtotal_gross')::numeric
          when jsonb_typeof(p_extracted -> 'subtotal_gross') = 'string'
                and (p_extracted ->> 'subtotal_gross') ~ '^\s*[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]+)?\s*$'
            then btrim(p_extracted ->> 'subtotal_gross')::numeric
        end,
        p_amount_gross
      ) as subtotal
  ),
  active_rates as (
    select array_agg(rate) as rates
    from halves,
      lateral (
        select case
          when jsonb_typeof(elem) = 'number' then (elem #>> '{}')::numeric
          when jsonb_typeof(elem) = 'string' and (elem #>> '{}') ~ '^\s*[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]+)?\s*$'
            then btrim(elem #>> '{}')::numeric
        end as rate
        from jsonb_array_elements(
          case when jsonb_typeof(basis -> 'vat_rate_valid' -> 'values' -> 'active_rates') = 'array'
            then basis -> 'vat_rate_valid' -> 'values' -> 'active_rates'
            else '[]'::jsonb end
        ) as elem
      ) parsed
    where parsed.rate is not null
  ),
  recheck as (
    select jsonb_build_object(
      'iban_checksum_valid', case when cardinality(iban_candidates.arr) = 0 then 'not_applicable'
          when (select bool_and(public.invoice_iban_checksum_ok(c)) from unnest(iban_candidates.arr) c)
            then 'ok' else 'failed' end,
      'payable_iban_present', case when lower(btrim(coalesce(halves.basis -> 'payable_iban_present' ->> 'status', ''))) = 'not_applicable'
          then 'not_applicable'
          else case when cardinality(iban_candidates.arr) > 0 then 'ok' else 'failed' end end,
      'iban_unambiguous', case when lower(btrim(coalesce(halves.basis -> 'iban_unambiguous' ->> 'status', ''))) = 'not_applicable'
          then 'not_applicable'
          else case when cardinality(iban_candidates.arr) = 0 then 'not_applicable'
          when cardinality(iban_candidates.arr) <= 1 then 'ok' else 'failed' end end,
      'gross_present', case when p_amount_gross is not null then 'ok' else 'failed' end,
      'issuer_present', case when btrim(coalesce(p_issuer, '')) <> '' then 'ok' else 'failed' end,
      'date_present', case when p_document_date is not null then 'ok' else 'failed' end,
      'invoice_number_present', case when btrim(coalesce(p_invoice_number, '')) <> '' then 'ok' else 'failed' end,
      'sum_matches', case when numbers.subtotal is null or p_amount_net is null or p_vat_amount is null
          then 'not_applicable'
          when abs((p_amount_net::float8 + p_vat_amount::float8) - numbers.subtotal::float8) <= 0.02 then 'ok'
          else 'failed' end,
      'vat_rate_valid', case when p_vat_rate is null or active_rates.rates is null then 'not_applicable'
          when floor(p_vat_rate + 0.5) = any(active_rates.rates) then 'ok' else 'failed' end,
      'date_not_future', case when p_document_date is null then 'not_applicable'
          when p_document_date <= current_date then 'ok' else 'failed' end,
      'recipient_present', case when lower(btrim(coalesce(halves.basis -> 'recipient_present' ->> 'status', ''))) = 'not_applicable'
          then 'not_applicable'
          else case when btrim(coalesce(p_recipient_name, '')) <> '' then 'ok' else 'failed' end end,
      'assignment_resolved', case when btrim(coalesce(p_company_code, '')) <> '' then 'ok' else 'failed' end
    ) as m
    from halves, iban_candidates, numbers, active_rates
  ),
  final_detail as (
    select case
      when halves.basis <> '{}'::jsonb then coalesce(
        (
          select jsonb_object_agg(
            entry.check_key,
            case when recheck.m ? entry.check_key and jsonb_typeof(entry.check_value) = 'object'
              then jsonb_set(entry.check_value, '{status}', recheck.m -> entry.check_key)
              else entry.check_value end
          )
          from jsonb_each(halves.basis) as entry(check_key, check_value)
        ), '{}'::jsonb)
      else halves.stored_user
    end as detail
    from halves, recheck
  ),
  checks_tier as (
    select case
      when jsonb_typeof(p_extracted -> 'review_checks') = 'array'
            and jsonb_array_length(p_extracted -> 'review_checks') > 0
        then p_extracted -> 'review_checks' end as arr
  ),
  flat_tier as (
    select coalesce(
      case when jsonb_typeof(p_extracted -> 'validation') = 'object'
        then p_extracted -> 'validation' end,
      p_validation, '{}'::jsonb) as fv
  )
  select
    (case
      when final_detail.detail <> '{}'::jsonb then (
        select count(*)::int from jsonb_each(final_detail.detail) as entry(check_key, check_value)
        where entry.check_key in ('gross_present','issuer_present','sum_matches','vat_rate_valid','iban_checksum_valid','date_not_future','invoice_number_present','date_present','payable_iban_present','recipient_present','iban_unambiguous','relevance_ok','assignment_resolved')
          and btrim(lower(coalesce(entry.check_value ->> 'status', ''))) not in ('', 'ok', 'not_applicable', 'skipped')
      )
      when checks_tier.arr is not null then (
        select count(*)::int from jsonb_array_elements(checks_tier.arr) as review_check(value)
        where btrim(lower(coalesce(review_check.value ->> 'severity', ''))) <> 'informational'
          and coalesce(review_check.value ->> 'field', '') in ('extraction_confidence','relevance','document_readable','exclusion','assignment','safety_invariant_1','safety_invariant_2','safety_invariant_3','safety_invariant_4a','safety_invariant_4b','safety_invariant_5','forced_review')
          and btrim(lower(coalesce(review_check.value ->> 'status', ''))) not in ('', 'ok', 'not_applicable', 'skipped')
      )
      else (
        select count(*)::int from jsonb_each_text(flat_tier.fv) as gate(gate_name, gate_value)
        where gate.gate_name in ('datum_vorhanden')
          and gate.gate_value = 'false'
          and (gate.gate_name not in ('datum_vorhanden')
               or coalesce(flat_tier.fv ->> 'kleinbetrag', '') <> 'true')
      )
    end) as problem_count,
    (case
      when final_detail.detail <> '{}'::jsonb then
        not exists (
          select 1 from jsonb_each(final_detail.detail) as entry(check_key, check_value)
          where entry.check_key not in ('kleinbetrag','is_small_amount')
            and btrim(lower(coalesce(entry.check_value ->> 'status', ''))) not in ('', 'not_applicable', 'skipped')
        )
      when checks_tier.arr is not null then
        not exists (
          select 1 from jsonb_array_elements(checks_tier.arr) as review_check(value)
          where btrim(lower(coalesce(review_check.value ->> 'severity', ''))) <> 'informational'
            and btrim(lower(coalesce(review_check.value ->> 'status', ''))) not in ('', 'not_applicable', 'skipped')
        )
      else
        not exists (
          select 1 from jsonb_each_text(flat_tier.fv) as gate(gate_name, gate_value)
          where gate.gate_name in ('datum_vorhanden')
            and (gate.gate_value = 'true'
                 or (gate.gate_value = 'false'
                     and (gate.gate_name not in ('datum_vorhanden')
                          or coalesce(flat_tier.fv ->> 'kleinbetrag', '') <> 'true')))
        )
    end) as unchecked
  from final_detail, checks_tier, flat_tier;
$_$;

CREATE OR REPLACE FUNCTION public.invoices_facets() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'objekt_codes', coalesce(
      jsonb_agg(distinct property_code order by property_code)
        filter (where property_code is not null), '[]'::jsonb),
    'belegarten', coalesce(
      jsonb_agg(distinct document_type order by document_type)
        filter (where document_type is not null), '[]'::jsonb),
    'months', coalesce(
      jsonb_agg(distinct to_char(document_date, 'YYYY-MM')
                order by to_char(document_date, 'YYYY-MM') desc)
        filter (where document_date is not null), '[]'::jsonb),
    'years', coalesce(
      jsonb_agg(distinct to_char(document_date, 'YYYY')
                order by to_char(document_date, 'YYYY') desc)
        filter (where document_date is not null), '[]'::jsonb)
  )
  from public.documents
  where deleted_at is null;
$$;

CREATE OR REPLACE FUNCTION public.invoices_filtered_aggregate(p_company_code text DEFAULT NULL::text, p_property_code text DEFAULT NULL::text, p_cost_category text DEFAULT NULL::text, p_issuer_like text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_status text DEFAULT NULL::text, p_payment_state text DEFAULT NULL::text, p_amount_min numeric DEFAULT NULL::numeric, p_amount_max numeric DEFAULT NULL::numeric) RETURNS TABLE(total_count bigint, total_gross numeric, total_net numeric, total_vat numeric, all_paid_count bigint, all_paid_gross numeric, all_paid_net numeric, all_paid_vat numeric, all_open_count bigint, all_open_gross numeric, all_open_net numeric, all_open_vat numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with scope as (
    select amount_gross, amount_net, vat_amount, paid_at,
      (
        p_payment_state is null
        or (p_payment_state = 'paid'    and paid_at is not null)
        or (p_payment_state = 'open'    and paid_at is null)
        or (p_payment_state = 'overdue' and paid_at is null and due_date is not null and due_date < current_date)
        or p_payment_state not in ('paid', 'open', 'overdue')
      ) as matches_payment_filter
    from public.v_documents_review
    where archived_at is null
      and not_relevant_at is null
      and (
        p_company_code is null
        or company_code = p_company_code
        or (p_company_code = 'NZO' and company_code is null)
      )
      and (p_property_code is null or property_code = p_property_code)
      and (p_cost_category is null or lower(cost_category) = lower(p_cost_category))
      and (p_issuer_like   is null
           or issuer ilike '%' || replace(replace(p_issuer_like, '%', '\%'), '_', '\_') || '%' escape '\')
      and (p_date_from     is null or document_date >= p_date_from)
      and (p_date_to       is null or document_date <= p_date_to)
      and (p_status        is null or status = p_status)
      and (p_amount_min    is null or amount_gross >= p_amount_min)
      and (p_amount_max    is null or amount_gross <= p_amount_max)
  )
  select
    count(*)                   filter (where matches_payment_filter),
    coalesce(sum(amount_gross) filter (where matches_payment_filter), 0),
    coalesce(sum(amount_net)   filter (where matches_payment_filter), 0),
    coalesce(sum(vat_amount)   filter (where matches_payment_filter), 0),
    count(*)                   filter (where paid_at is not null),
    coalesce(sum(amount_gross) filter (where paid_at is not null), 0),
    coalesce(sum(amount_net)   filter (where paid_at is not null), 0),
    coalesce(sum(vat_amount)   filter (where paid_at is not null), 0),
    count(*)                   filter (where paid_at is null),
    coalesce(sum(amount_gross) filter (where paid_at is null), 0),
    coalesce(sum(amount_net)   filter (where paid_at is null), 0),
    coalesce(sum(vat_amount)   filter (where paid_at is null), 0)
  from scope;
$$;

CREATE OR REPLACE FUNCTION public.invoices_filtered_search(p_query_embedding public.vector DEFAULT NULL::public.vector, p_company_code text DEFAULT NULL::text, p_property_code text DEFAULT NULL::text, p_cost_category text DEFAULT NULL::text, p_issuer_like text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 15, p_payment_state text DEFAULT NULL::text, p_amount_min numeric DEFAULT NULL::numeric, p_amount_max numeric DEFAULT NULL::numeric) RETURNS TABLE(id uuid, invoice_number text, issuer text, document_date date, amount_gross numeric, company_code text, property_code text, cost_category text, service_description text, paid_at timestamp with time zone, similarity double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    id, invoice_number, issuer, document_date, amount_gross, company_code, property_code,
    cost_category, service_description, paid_at,
    case when p_query_embedding is not null then 1 - (embedding <=> p_query_embedding) end as similarity
  from public.v_documents_review
  where archived_at is null
    and not_relevant_at is null
    and (
      p_company_code is null
      or company_code = p_company_code
      or (p_company_code = 'NZO' and company_code is null)
    )
    and (p_property_code is null or property_code = p_property_code)
    and (p_cost_category is null or lower(cost_category) = lower(p_cost_category))
    and (p_issuer_like   is null
         or issuer ilike '%' || replace(replace(p_issuer_like, '%', '\%'), '_', '\_') || '%' escape '\')
    and (p_date_from     is null or document_date >= p_date_from)
    and (p_date_to       is null or document_date <= p_date_to)
    and (p_status        is null or status = p_status)
    and (p_amount_min    is null or amount_gross >= p_amount_min)
    and (p_amount_max    is null or amount_gross <= p_amount_max)
    and (p_query_embedding is null or embedding is not null)
    and (
      p_payment_state is null
      or (p_payment_state = 'paid'    and paid_at is not null)
      or (p_payment_state = 'open'    and paid_at is null)
      or (p_payment_state = 'overdue' and paid_at is null and due_date is not null and due_date < current_date)
      or p_payment_state not in ('paid', 'open', 'overdue')
    )
  order by
    (case when p_query_embedding is not null then embedding <=> p_query_embedding end) asc nulls last,
    document_date desc nulls last
  limit least(greatest(coalesce(p_limit, 15), 1), 50);
$$;

CREATE OR REPLACE FUNCTION public.invoices_kpis(p_q text DEFAULT NULL::text, p_gesellschaft text DEFAULT NULL::text, p_objekt text DEFAULT NULL::text, p_belegart text DEFAULT NULL::text, p_zahlung text DEFAULT NULL::text, p_von date DEFAULT NULL::date, p_bis date DEFAULT NULL::date, p_datev text DEFAULT NULL::text, p_workflow text DEFAULT NULL::text, p_bank_match text DEFAULT NULL::text, p_ampel text DEFAULT NULL::text, p_archiv text DEFAULT NULL::text, p_ids uuid[] DEFAULT NULL::uuid[], p_faellig_von date DEFAULT NULL::date, p_faellig_bis date DEFAULT NULL::date, p_faellig_unbekannt boolean DEFAULT false, p_direct_debit boolean DEFAULT NULL::boolean) RETURNS TABLE(total bigint, erkannt bigint, zu_pruefen bigint, volumen numeric, offen numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    count(*),
    count(*) filter (where status = 'recognised'),
    count(*) filter (where status = 'needs_review'),
    coalesce(sum(amount_gross), 0),
    coalesce(sum(amount_gross) filter (where paid_at is null), 0)
  from public.v_documents_review
  where (p_q is null or search_text like all (
      select '%' || replace(replace(replace(word, '\', '\\'), '%', '\%'), '_', '\_') || '%'
      from regexp_split_to_table(lower(p_q), '\s+') as word
      where word <> ''
    ))
    and (
      p_gesellschaft is null
      or company_code = p_gesellschaft
      -- NZO ("Nicht zugeordnet") is the catch-all for unassigned, and the pipeline
      -- expresses unassigned as NULL rather than by writing the code, so it has to
      -- match both. Same rule as migration 20260813190000 set for the search RPCs.
      or (p_gesellschaft = 'NZO' and company_code is null)
    )
    and (
      p_objekt is null
      or property_code = p_objekt
      -- The list sends this sentinel for "no property assigned". Properties have no
      -- catch-all code the way companies have NZO, so the filter is expressed as a
      -- value the column can never hold.
      or (p_objekt = '__ohne' and property_code is null)
    )
    and (p_belegart is null or document_type = p_belegart)
    and (
      p_zahlung is null
      or (p_zahlung = 'paid' and paid_at is not null)
      or (p_zahlung = 'open'   and paid_at is null)
    )
    and (
      p_datev is null
      or (p_datev = 'uebergeben' and handed_over_at is not null)
      or (p_datev = 'open'      and handed_over_at is null)
    )
    and (
      p_bank_match is null
      or (p_bank_match = 'vorschlag'  and has_suggested_bank_match and not has_confirmed_bank_match)
      or (p_bank_match = 'matched' and has_confirmed_bank_match)
      or (p_bank_match = 'open' and not has_suggested_bank_match and not has_confirmed_bank_match)
    )
    and (p_workflow is null or workflow_status = p_workflow)
    and (p_von is null or document_date >= p_von)
    and (p_bis is null or document_date <= p_bis)
    and (case when p_archiv = 'nur' then archived_at is not null else archived_at is null end)
    and (p_ids is null or id = any(p_ids))
    and (
      p_ampel is null
      or (p_ampel =  'auffaellig' and traffic_light in ('yellow', 'red'))
      or (p_ampel <> 'auffaellig' and traffic_light = p_ampel)
    )
    and (case when p_faellig_unbekannt then due_date is null else true end)
    and (p_faellig_von is null or due_date >= p_faellig_von)
    and (p_faellig_bis is null or due_date <= p_faellig_bis)
    and (p_direct_debit is null or public.is_direct_debit(payment_method) = p_direct_debit)
    and not_relevant_at is null;
$$;

CREATE OR REPLACE FUNCTION public.invoices_search_ids(p_where text DEFAULT NULL::text, p_archived boolean DEFAULT false) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '8s'
    AS $$
declare
  v_scope text := case when p_archived then 'is not null' else 'is null' end;
begin
  if p_where is not null and (p_where ~ ';' or p_where like '%--%' or p_where like '%/*%') then
    raise exception 'invalid where clause';
  end if;
  return query execute
    'select id from public.v_documents_review where archived_at ' || v_scope ||
    ' and not_relevant_at is null' ||
    case
      when p_where is not null and btrim(p_where) <> '' then ' and (' || p_where || ')'
      else ''
    end;
end;
$$;

CREATE OR REPLACE FUNCTION public.is_direct_debit(p_payment_method text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select p_payment_method is not null
     and (
       lower(p_payment_method) like '%lastschrift%'
       or lower(p_payment_method) like '%einzug%'
       or lower(p_payment_method) like '%abbuch%'
     );
$$;

CREATE OR REPLACE FUNCTION public.is_invoice_reconciled(p_invoice_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when v.soll <= 0 then false
    else v.matched >= v.soll - least(greatest(v.soll * 0.03, 0.01), 150)
  end
  from (
    select
      abs(coalesce(i.amount_gross, 0)) as soll,
      coalesce((
        select sum(abs(m.amount_matched))
          from public.document_transaction_matches m
         where m.document_id = i.id and m.status = 'confirmed'
      ), 0) as matched
    from public.documents i
    where i.id = p_invoice_id
  ) v;
$$;

CREATE OR REPLACE FUNCTION public.learn_assignment_rule_from_match(p_match uuid, p_actor text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_match   public.document_transaction_matches;
  v_inv     public.documents;
  v_txn     public.bank_transactions;
  v_pattern text;
  v_existing uuid;
  v_rule_id  uuid;
begin
  select * into v_match from public.document_transaction_matches where id = p_match;
  if not found then
    return null;
  end if;

  select * into v_inv from public.documents where id = v_match.document_id and deleted_at is null;
  if not found or v_inv.supplier_id is null then
    return null;
  end if;
  if v_inv.is_demo then
    return null;
  end if;

  if coalesce(v_inv.cost_category_source, 'ai') not in ('rule', 'human') then
    return null;
  end if;
  if v_inv.category_id is null and coalesce(v_inv.cost_category, '') = '' then
    return null;
  end if;

  select * into v_txn from public.bank_transactions where id = v_match.transaction_id;
  if found and v_txn.transaction_type = 'lastschrift' and coalesce(v_txn.payment_reference, '') <> '' then
    v_pattern := v_txn.payment_reference;
  else
    v_pattern := null;
  end if;

  select id into v_existing
    from public.assignment_rules
   where target = 'cost_category'
     and deleted_at is null
     and supplier_id = v_inv.supplier_id
     and business_line_id is null and property_id is null and company_id is null
     and coalesce(lower(btrim(reference_pattern)), '') = coalesce(lower(btrim(v_pattern)), '');

  if v_existing is not null then
    update public.assignment_rules
       set cost_category = v_inv.cost_category,
           category_id = v_inv.category_id,
           is_active = true,
           note = 'Learned from a confirmed bank match (last updated from document '
                  || v_inv.id || ').',
           updated_at = now()
     where id = v_existing
    returning id into v_rule_id;
    return v_rule_id;
  end if;

  insert into public.assignment_rules (
    target, cost_category, category_id, supplier_id, reference_pattern, created_by, note
  ) values (
    'cost_category', v_inv.cost_category, v_inv.category_id, v_inv.supplier_id, v_pattern, p_actor,
    'Learned from a confirmed bank match (document ' || v_inv.id || ').'
  )
  returning id into v_rule_id;
  return v_rule_id;
end $$;

-- Matches people to the CRM's brokers by email. Never overwrites a link somebody set, and skips an
-- email the CRM gives to two brokers or a broker who is already linked to somebody else.
CREATE OR REPLACE FUNCTION public.link_brokers_to_users() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_linked integer;
begin
  update public.app_users u
     set crm_external_id = b.broker_external_id
    from (select lower(broker_email) as email, min(broker_external_id) as broker_external_id
            from public.properties
           where broker_email is not null and broker_external_id is not null and deleted_at is null
           group by lower(broker_email)
          having count(distinct broker_external_id) = 1) b
   where lower(u.email) = b.email
     and u.crm_external_id is null
     and not exists (select 1 from public.app_users o where o.crm_external_id = b.broker_external_id);
  get diagnostics v_linked = row_count;
  return v_linked;
end;
$$;

revoke execute on function public.link_brokers_to_users() from public, anon, authenticated;
grant execute on function public.link_brokers_to_users() to service_role;

CREATE OR REPLACE FUNCTION public.link_invoice_transaction(p_invoice_id uuid, p_transaction_id uuid, p_score numeric DEFAULT NULL::numeric, p_reasons jsonb DEFAULT NULL::jsonb, p_amount numeric DEFAULT NULL::numeric, p_difference_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor      text := coalesce(nullif(auth.jwt() ->> 'email', ''), 'hub');
  v_now        timestamptz := now();
  v_match_id   uuid;
  v_withdrawn  int := 0;
  v_batch      int;
  v_released   boolean := false;
  v_tx_total   numeric;
  v_tx_other   numeric;
  v_tx_rest    numeric;
  v_inv_gross  numeric;
  v_inv_other  numeric;
  v_inv_rest   numeric;
  v_amount     numeric;
begin
  if p_invoice_id is null or p_transaction_id is null then
    raise exception 'link_invoice_transaction: invoice and transaction are both required';
  end if;

  if not exists (select 1 from public.documents where id = p_invoice_id and deleted_at is null) then
    raise exception 'link_invoice_transaction: invoice % not found', p_invoice_id;
  end if;
  if not exists (select 1 from public.bank_transactions where id = p_transaction_id) then
    raise exception 'link_invoice_transaction: transaction % not found', p_transaction_id;
  end if;

  select abs(amount) into v_tx_total
    from public.bank_transactions where id = p_transaction_id;
  select abs(amount_gross) into v_inv_gross
    from public.documents where id = p_invoice_id and deleted_at is null;
  if v_inv_gross is null or v_inv_gross = 0 then
    raise exception 'link_invoice_transaction: invoice % has no gross amount to allocate against',
      p_invoice_id;
  end if;

  select coalesce(sum(amount_matched), 0) into v_tx_other
    from public.document_transaction_matches
   where transaction_id = p_transaction_id and status = 'confirmed' and document_id <> p_invoice_id;
  select coalesce(sum(amount_matched), 0) into v_inv_other
    from public.document_transaction_matches
   where document_id = p_invoice_id and status = 'confirmed' and transaction_id <> p_invoice_id;

  v_tx_rest  := v_tx_total  - v_tx_other;
  v_inv_rest := v_inv_gross - v_inv_other;

  v_amount := coalesce(p_amount, least(v_tx_rest, v_inv_rest));

  if v_amount is null or v_amount <= 0 then
    raise exception
      'link_invoice_transaction: nothing left to allocate (transaction free %, invoice open %)',
      v_tx_rest, v_inv_rest using errcode = 'check_violation';
  end if;
  if v_amount > v_tx_rest + 0.01 then
    raise exception 'link_invoice_transaction: amount % exceeds the transaction remainder %',
      v_amount, v_tx_rest using errcode = 'check_violation';
  end if;
  if v_amount > v_inv_rest + 0.01 then
    raise exception 'link_invoice_transaction: amount % exceeds the invoice remainder %',
      v_amount, v_inv_rest using errcode = 'check_violation';
  end if;

  update public.bank_transactions
     set matching_status   = 'open',
         no_receipt_reason = null,
         whitelist_rule_id = null,
         no_receipt_set_by = null,
         no_receipt_set_at = null
   where id = p_transaction_id
     and matching_status = 'ignored';
  v_released := found;

  insert into public.document_transaction_matches
         (document_id, transaction_id, status, score, match_reasons, amount_matched,
          difference_reason, matched_by, confirmed_by, confirmed_at, updated_at)
  values (p_invoice_id, p_transaction_id, 'confirmed', p_score,
          coalesce(p_reasons, jsonb_build_object('manual', true)), v_amount,
          p_difference_reason, v_actor, v_actor, v_now, v_now)
  on conflict (document_id, transaction_id) do update
     set status            = 'confirmed',
         amount_matched    = excluded.amount_matched,
         score             = coalesce(excluded.score, public.document_transaction_matches.score),
         match_reasons     = coalesce(excluded.match_reasons, public.document_transaction_matches.match_reasons),
         difference_reason = coalesce(excluded.difference_reason, public.document_transaction_matches.difference_reason),
         confirmed_by      = excluded.confirmed_by,
         confirmed_at      = excluded.confirmed_at,
         rejected_by       = null,
         rejected_at       = null,
         reject_reason     = null,
         updated_at        = v_now
  returning id into v_match_id;

  if public.transaction_allocated_sum(p_transaction_id) >= v_tx_total - 0.01 then
    update public.document_transaction_matches
       set status        = 'rejected',
           rejected_by   = v_actor,
           rejected_at   = v_now,
           reject_reason = 'superseded: transaction fully allocated',
           updated_at    = v_now
     where transaction_id = p_transaction_id and status in ('candidate', 'auto');
    get diagnostics v_batch = row_count;
    v_withdrawn := v_withdrawn + v_batch;
  end if;

  if public.invoice_matched_sum(p_invoice_id)
     >= v_inv_gross - public.payment_tolerance(v_inv_gross) then
    update public.document_transaction_matches
       set status        = 'rejected',
           rejected_by   = v_actor,
           rejected_at   = v_now,
           reject_reason = 'superseded: invoice fully allocated',
           updated_at    = v_now
     where document_id = p_invoice_id and status in ('candidate', 'auto');
    get diagnostics v_batch = row_count;
    v_withdrawn := v_withdrawn + v_batch;
  end if;

  insert into public.document_history (document_id, type, text, actor, data)
  values (p_invoice_id, 'zuordnung',
          'Banktransaktion manuell zugeordnet'
            || case when v_amount < v_tx_total - 0.01
                    then format(' (%s EUR von %s EUR)',
                                to_char(v_amount, 'FM999G999G990D00'),
                                to_char(v_tx_total, 'FM999G999G990D00'))
                    else format(' (%s EUR)', to_char(v_amount, 'FM999G999G990D00')) end
            || case when p_difference_reason is not null then format(', Differenzgrund: %s', p_difference_reason) else '' end
            || case when p_score is not null then format(', Konfidenz %s', p_score) else '' end
            || case when v_withdrawn > 0 then format(', %s suggestion(s) withdrawn', v_withdrawn) else '' end
            || case when v_released then ', the "no document expected" exception was lifted' else '' end,
          v_actor,
          jsonb_build_object('transaction_id', p_transaction_id, 'score', p_score,
                             'amount_matched', v_amount, 'transaction_amount', v_tx_total,
                             'difference_reason', p_difference_reason,
                             'withdrawn', v_withdrawn, 'whitelist_released', v_released));

  return v_match_id;
end $$;

CREATE OR REPLACE FUNCTION public.link_outgoing_invoice_transaction(p_outgoing_invoice_id uuid, p_transaction_id uuid, p_score numeric DEFAULT NULL::numeric, p_reasons jsonb DEFAULT NULL::jsonb, p_amount numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor      text := coalesce(nullif(auth.jwt() ->> 'email', ''), 'hub');
  v_now        timestamptz := now();
  v_match_id   uuid;
  v_withdrawn  int := 0;
  v_batch      int;
  v_released   boolean := false;
  v_tx_total   numeric;
  v_tx_other   numeric;
  v_tx_rest    numeric;
  v_inv_gross  numeric;
  v_inv_other  numeric;
  v_inv_rest   numeric;
  v_amount     numeric;
begin
  if p_outgoing_invoice_id is null or p_transaction_id is null then
    raise exception 'link_outgoing_invoice_transaction: invoice and transaction are both required';
  end if;

  if not exists (select 1 from public.outgoing_invoices where id = p_outgoing_invoice_id) then
    raise exception 'link_outgoing_invoice_transaction: outgoing invoice % not found', p_outgoing_invoice_id;
  end if;
  if not exists (select 1 from public.bank_transactions where id = p_transaction_id) then
    raise exception 'link_outgoing_invoice_transaction: transaction % not found', p_transaction_id;
  end if;

  select abs(amount) into v_tx_total
    from public.bank_transactions where id = p_transaction_id;
  select abs(amount_gross) into v_inv_gross
    from public.outgoing_invoices where id = p_outgoing_invoice_id;
  if v_inv_gross is null or v_inv_gross = 0 then
    raise exception 'link_outgoing_invoice_transaction: invoice % has no gross amount to allocate against',
      p_outgoing_invoice_id;
  end if;

  select coalesce(sum(amount_matched), 0) into v_tx_other
    from public.outgoing_invoice_transaction_matches
   where transaction_id = p_transaction_id and status = 'confirmed'
     and outgoing_invoice_id <> p_outgoing_invoice_id;
  select coalesce(sum(amount_matched), 0) into v_inv_other
    from public.outgoing_invoice_transaction_matches
   where outgoing_invoice_id = p_outgoing_invoice_id and status = 'confirmed'
     and transaction_id <> p_transaction_id;

  v_tx_rest  := v_tx_total  - v_tx_other;
  v_inv_rest := v_inv_gross - v_inv_other;

  v_amount := coalesce(p_amount, least(v_tx_rest, v_inv_rest));

  if v_amount is null or v_amount <= 0 then
    raise exception
      'link_outgoing_invoice_transaction: nothing left to allocate (transaction free %, invoice open %)',
      v_tx_rest, v_inv_rest using errcode = 'check_violation';
  end if;
  if v_amount > v_tx_rest + 0.01 then
    raise exception 'link_outgoing_invoice_transaction: amount % exceeds the transaction remainder %',
      v_amount, v_tx_rest using errcode = 'check_violation';
  end if;
  if v_amount > v_inv_rest + 0.01 then
    raise exception 'link_outgoing_invoice_transaction: amount % exceeds the invoice remainder %',
      v_amount, v_inv_rest using errcode = 'check_violation';
  end if;

  -- A credit is being linked, so "no receipt expected" was wrong -- release the hide first, same
  -- as the incoming side.
  update public.bank_transactions
     set matching_status   = 'open',
         no_receipt_reason = null,
         whitelist_rule_id = null,
         no_receipt_set_by = null,
         no_receipt_set_at = null
   where id = p_transaction_id
     and matching_status = 'ignored';
  v_released := found;

  insert into public.outgoing_invoice_transaction_matches
         (outgoing_invoice_id, transaction_id, status, score, match_reasons, amount_matched,
          matched_by, confirmed_by, confirmed_at, updated_at)
  values (p_outgoing_invoice_id, p_transaction_id, 'confirmed', p_score,
          coalesce(p_reasons, jsonb_build_object('manual', true)), v_amount,
          v_actor, v_actor, v_now, v_now)
  on conflict (outgoing_invoice_id, transaction_id) do update
     set status         = 'confirmed',
         amount_matched = excluded.amount_matched,
         score          = coalesce(excluded.score, public.outgoing_invoice_transaction_matches.score),
         match_reasons  = coalesce(excluded.match_reasons, public.outgoing_invoice_transaction_matches.match_reasons),
         confirmed_by   = excluded.confirmed_by,
         confirmed_at   = excluded.confirmed_at,
         rejected_by    = null,
         rejected_at    = null,
         reject_reason  = null,
         updated_at     = v_now
  returning id into v_match_id;

  if public.outgoing_transaction_allocated_sum(p_transaction_id) >= v_tx_total - 0.01 then
    update public.outgoing_invoice_transaction_matches
       set status        = 'rejected',
           rejected_by   = v_actor,
           rejected_at   = v_now,
           reject_reason = 'superseded: transaction fully allocated',
           updated_at    = v_now
     where transaction_id = p_transaction_id and status in ('candidate', 'auto');
    get diagnostics v_batch = row_count;
    v_withdrawn := v_withdrawn + v_batch;
  end if;

  if public.outgoing_invoice_matched_sum(p_outgoing_invoice_id) >= v_inv_gross - 0.01 then
    update public.outgoing_invoice_transaction_matches
       set status        = 'rejected',
           rejected_by   = v_actor,
           rejected_at   = v_now,
           reject_reason = 'superseded: invoice fully allocated',
           updated_at    = v_now
     where outgoing_invoice_id = p_outgoing_invoice_id and status in ('candidate', 'auto');
    get diagnostics v_batch = row_count;
    v_withdrawn := v_withdrawn + v_batch;
  end if;

  insert into public.change_history (table_name, record_id, type, text, actor, data, at)
  values ('outgoing_invoices', p_outgoing_invoice_id, 'zuordnung',
          'Banktransaktion manuell zugeordnet'
            || case when v_amount < v_tx_total - 0.01
                    then format(' (%s EUR von %s EUR)',
                                to_char(v_amount, 'FM999G999G990D00'),
                                to_char(v_tx_total, 'FM999G999G990D00'))
                    else format(' (%s EUR)', to_char(v_amount, 'FM999G999G990D00')) end
            || case when p_score is not null then format(', Konfidenz %s', p_score) else '' end
            || case when v_withdrawn > 0 then format(', %s suggestion(s) withdrawn', v_withdrawn) else '' end
            || case when v_released then ', the "no document expected" exception was lifted' else '' end,
          v_actor,
          jsonb_build_object('transaction_id', p_transaction_id, 'score', p_score,
                             'amount_matched', v_amount, 'transaction_amount', v_tx_total,
                             'withdrawn', v_withdrawn, 'whitelist_released', v_released),
          v_now);

  return v_match_id;
end;
$$;

CREATE OR REPLACE FUNCTION public.link_uploaded_invoice_when_extracted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_amount numeric;
begin
  if new.uploaded_for_transaction_id is null then
    return null;
  end if;
  -- Nothing to allocate against yet. Extraction has not run, or it ran and found no total.
  if new.amount_gross is null or new.amount_gross = 0 then
    return null;
  end if;
  -- `after update of amount_gross` also fires when the column is merely present in the SET list,
  -- so the transition itself has to be checked rather than assumed.
  if old.amount_gross is not distinct from new.amount_gross then
    return null;
  end if;
  -- Already linked. link_invoice_transaction would re-stamp it happily, but re-running it can also
  -- raise once the remainders have moved on, and there is nothing to gain by trying.
  if exists (
    select 1 from public.document_transaction_matches
     where document_id = new.id
       and transaction_id = new.uploaded_for_transaction_id
       and status = 'confirmed'
  ) then
    return null;
  end if;

  -- WRAPPED, because this runs inside the pipeline's own UPDATE. A raise here would roll that back
  -- and the extraction result would be lost, which is a far worse outcome than an unlinked invoice.
  -- The reason is written where somebody will see it rather than swallowed.
  begin
    perform public.link_invoice_transaction(
      p_invoice_id        => new.id,
      p_transaction_id    => new.uploaded_for_transaction_id,
      p_score             => null,
      p_reasons           => jsonb_build_object('uploaded_for_transaction', true),
      p_amount            => null,
      p_difference_reason => null
    );

    select amount_matched into v_amount
      from public.document_transaction_matches
     where document_id = new.id and transaction_id = new.uploaded_for_transaction_id;

    insert into public.document_history (document_id, type, text, actor)
    values (
      new.id, 'aenderung',
      -- Persisted audit text stays German.
      'Matched to the transaction the invoice was uploaded from ('
        || to_char(coalesce(v_amount, 0), 'FM999G999G990D00') || ' EUR).',
      'hub'
    );
  exception when others then
    insert into public.document_history (document_id, type, text, actor)
    values (
      new.id, 'aenderung',
      'Could not match it to the transaction automatically: ' || sqlerrm,
      'hub'
    );
  end;

  return null;
end $$;

CREATE OR REPLACE FUNCTION public.log_supplier_bank_account_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
    akteur text := coalesce(auth.uid()::text, 'pipeline');
begin
    if tg_op = 'INSERT' then
        insert into public.supplier_iban_history
            (supplier_id, old_iban, new_iban, changed_by, source, note)
        values (new.supplier_id, null, new.iban, akteur, new.source, 'account_added');
        -- A supplier's first account arrives as the default, so both events are true of it and
        -- both are recorded. The list then reads the same whether the default was set on the way
        -- in or picked later.
        if new.is_default then
            insert into public.supplier_iban_history
                (supplier_id, old_iban, new_iban, changed_by, source, note)
            values (new.supplier_id, null, new.iban, akteur, new.source, 'default_set');
        end if;
    elsif new.is_default and not coalesce(old.is_default, false) then
        insert into public.supplier_iban_history
            (supplier_id, old_iban, new_iban, changed_by, source, note)
        values (new.supplier_id, null, new.iban, akteur, new.source, 'default_set');
    end if;
    return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.manual_bookings_expanded(p_company uuid DEFAULT NULL::uuid, p_von date DEFAULT NULL::date, p_bis date DEFAULT NULL::date) RETURNS TABLE(source_id uuid, company_id uuid, property_id uuid, category_id uuid, period date, amount numeric, note text, is_recurring boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- Non-recurring: pass through unchanged when its period falls in range.
  select b.id as source_id, b.company_id, b.property_id, b.category_id, b.period, b.amount,
         b.note, b.is_recurring
    from public.manual_bookings b
   where b.deleted_at is null
     and (p_company is null or b.company_id = p_company)
     and not b.is_recurring
     and b.period between date_trunc('month', p_von)::date and date_trunc('month', p_bis)::date

  union all

  -- Recurring: one row per calendar month between its own start/end and the requested range.
  -- generate_series(start, stop, step) with start > stop returns zero rows (no separate guard
  -- needed for a template outside the requested range, or one whose recurrence_until precedes it).
  select b.id as source_id, b.company_id, b.property_id, b.category_id, m.month::date as period,
         b.amount, b.note, b.is_recurring
    from public.manual_bookings b
    cross join lateral generate_series(
      greatest(b.period, date_trunc('month', p_von)::date),
      least(coalesce(b.recurrence_until, p_bis), date_trunc('month', p_bis)::date),
      interval '1 month'
    ) as m(month)
   where b.deleted_at is null
     and (p_company is null or b.company_id = p_company)
     and b.is_recurring;
$$;

CREATE OR REPLACE FUNCTION public.mark_datev_batch_bounced(p_batch_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_status text;
  v_reset  int;
begin
  select status into v_status
    from public.handover_batches
   where id = p_batch_id
   for update;

  if v_status is null then
    raise exception 'mark_datev_batch_bounced: no batch %', p_batch_id;
  end if;

  -- Idempotent: a mailbox read that sees the same report twice must not undo an acknowledgement.
  if v_status = 'bounced' then
    return;
  end if;

  update public.handover_batches
     set status        = 'bounced',
         bounced_at    = now(),
         bounce_reason = nullif(btrim(coalesce(p_reason, '')), '')
   where id = p_batch_id;

  -- Not handed over after all, so it goes back on the ready list. handover_batch_id stays, so the
  -- failed attempt is still traceable from the receipt.
  update public.documents
     set handed_over_at = null
   where handover_batch_id = p_batch_id
     and handed_over_at is not null;
  get diagnostics v_reset = row_count;

  raise notice 'batch % marked bounced, % invoice(s) returned to the ready list', p_batch_id, v_reset;
end;
$$;

CREATE OR REPLACE FUNCTION public.mark_notifications_seen() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email text := coalesce(nullif(auth.jwt() ->> 'email', ''), '');
begin
  if v_email = '' then
    return;
  end if;

  update public.app_users
     set notifications_seen_at = now(),
         updated_at = now()
   where lower(email) = lower(v_email);
end;
$$;

CREATE OR REPLACE FUNCTION public.match_opos_whitelist(p_reference text, p_counterparty text, p_iban text, p_booking_text text) RETURNS TABLE(rule_id uuid, category text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.id, r.category
    from public.open_item_whitelist_rules r
   where r.is_active
     and r.deleted_at is null
     and public.opos_norm(r.term) <> ''
     and position(
           public.opos_norm(r.term) in
           case r.scope
             when 'reference'    then public.opos_norm(p_reference)
             when 'counterparty' then public.opos_norm(p_counterparty)
             when 'iban'         then public.opos_norm(p_iban)
             when 'booking_text' then public.opos_norm(p_booking_text)
             else public.opos_norm(concat_ws(' ', p_reference, p_counterparty, p_iban, p_booking_text))
           end
         ) > 0
   order by r.created_at, r.term
   limit 1;
$$;

CREATE OR REPLACE FUNCTION public.merge_suppliers(p_keep_id uuid, p_merge_id uuid, p_merged_by text, p_reason text DEFAULT NULL::text) RETURNS public.suppliers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_keep    public.suppliers;
  v_merge   public.suppliers;
  v_fk      record;
  v_result  public.suppliers;
begin
  if p_keep_id = p_merge_id then
    raise exception 'merge_suppliers: p_keep_id and p_merge_id must differ';
  end if;

  select * into v_keep from public.suppliers where id = p_keep_id;
  if not found then
    raise exception 'merge_suppliers: keep supplier % not found', p_keep_id;
  end if;
  if v_keep.deleted_at is not null then
    raise exception 'merge_suppliers: keep supplier % is already deleted', p_keep_id;
  end if;

  select * into v_merge from public.suppliers where id = p_merge_id;
  if not found then
    raise exception 'merge_suppliers: merge-away supplier % not found', p_merge_id;
  end if;
  if v_merge.deleted_at is not null then
    raise exception 'merge_suppliers: merge-away supplier % is already deleted', p_merge_id;
  end if;
  if v_keep.is_demo is distinct from v_merge.is_demo then
    raise exception 'merge_suppliers: a practice supplier cannot be merged with a real supplier';
  end if;

  -- Reassign every FK column pointing at suppliers(id), across every table in `public`. Discovered
  -- dynamically rather than hardcoded: suppliers/documents predate this repo's tracked migration
  -- history (renamed from German outside any versioned migration), so a hardcoded table list could
  -- silently miss a real FK. This also future-proofs the function against tables added later.
  for v_fk in
    select kcu.table_name, kcu.column_name
      from information_schema.table_constraints tc
      join information_schema.key_column_usage kcu
        on tc.constraint_name = kcu.constraint_name and tc.table_schema = kcu.table_schema
      join information_schema.constraint_column_usage ccu
        on tc.constraint_name = ccu.constraint_name and tc.table_schema = ccu.table_schema
     where tc.constraint_type = 'FOREIGN KEY'
       and tc.table_schema = 'public'
       and ccu.table_name = 'suppliers'
       and ccu.column_name = 'id'
       and kcu.table_name not in ('supplier_iban_history', 'supplier_bank_accounts') -- reassigned explicitly below instead
  loop
    execute format(
      'update public.%I set %I = $1 where %I = $2',
      v_fk.table_name, v_fk.column_name, v_fk.column_name
    ) using p_keep_id, p_merge_id;
  end loop;

  -- Preserve the merged-away supplier's bank details if they differ from the survivor's, so
  -- nothing is silently lost even though only one IBAN can be "current" going forward.
  if v_merge.iban is not null and v_merge.iban is distinct from v_keep.iban then
    insert into public.supplier_iban_history (supplier_id, old_iban, new_iban, changed_by, note)
    values (p_keep_id, v_merge.iban, v_keep.iban, p_merged_by, 'supplier_merged');
  end if;

  -- Also carry the merged-away supplier's own history rows forward, so "IBAN-Verlauf" on the
  -- survivor stays complete.
  update public.supplier_iban_history set supplier_id = p_keep_id where supplier_id = p_merge_id;

  -- Move every account the merged-away supplier held onto the survivor. Where both already hold
  -- the same IBAN the survivor's own row wins and the duplicate is simply dropped afterwards, never
  -- overwritten, since a name or verification somebody already checked must not be replaced blind.
  insert into public.supplier_bank_accounts (supplier_id, iban, bic, bank_name, source, is_active, created_by)
  select p_keep_id, iban, bic, bank_name, source, is_active, created_by
    from public.supplier_bank_accounts
   where supplier_id = p_merge_id
  on conflict (supplier_id, iban) do nothing;

  delete from public.supplier_bank_accounts where supplier_id = p_merge_id;

  -- Carry the merged-away supplier's aliases across. A move changes entity_code and nothing else,
  -- and entity_aliases_one_owner_uniq is keyed on (entity_type, folded(alias)), so it is indifferent
  -- to the move: the only index a move can violate is entity_aliases_uniq, and the guard below is
  -- exactly its columns. It deliberately does not test is_active -- that index is partial on three
  -- of the Hubs and plain on the rest, and ignoring is_active is the correct guard under both.
  update public.entity_aliases a
     set entity_code = p_keep_id::text,
         updated_at = now()
   where a.entity_type = 'supplier'
     and a.entity_code = p_merge_id::text
     and a.is_active
     and not exists (
       select 1 from public.entity_aliases k
        where k.entity_type = 'supplier'
          and k.entity_code = p_keep_id::text
          and k.alias = a.alias);

  -- Whatever could not move is a spelling the survivor already has. Deactivated rather than deleted,
  -- so the record survives (GoBD) and the one-owner slot the dead row would keep is released.
  update public.entity_aliases
     set is_active = false,
         updated_at = now(),
         note = coalesce(note || ' | ', '') || 'deactivated by merge into ' || p_keep_id::text
   where entity_type = 'supplier'
     and entity_code = p_merge_id::text
     and is_active;

  -- Remember the merged-away name as a known spelling of the survivor.
  --
  -- ON CONFLICT carries no target on purpose. A target has to repeat the predicate of the index it
  -- names, and entity_aliases_uniq is partial here but plain elsewhere -- and naming either one
  -- leaves a clash on entity_aliases_one_owner_uniq unswallowed, which would roll back the entire
  -- merge to avoid losing a single alias. Untargeted, it takes DO NOTHING on any unique index.
  --
  -- The blank test is separate because ON CONFLICT does not swallow a CHECK violation, and
  -- entity_aliases_alias_not_blank refuses an empty alias.
  if btrim(coalesce(v_merge.name, '')) <> '' then
    insert into public.entity_aliases (entity_type, entity_code, alias, note)
    values ('supplier', p_keep_id::text, v_merge.name, 'merged from ' || p_merge_id::text)
    on conflict do nothing;
  end if;

  update public.suppliers
     set deleted_at = now(),
         deleted_by = p_merged_by,
         delete_reason = coalesce(p_reason, 'merged into ' || p_keep_id::text)
   where id = p_merge_id;

  select * into v_result from public.suppliers where id = p_keep_id;
  return v_result;
end;
$_$;

CREATE OR REPLACE FUNCTION public.my_profile() RETURNS TABLE(id uuid, name text, email text, picture_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email text := coalesce(nullif(auth.jwt() ->> 'email', ''), '');
begin
  if v_email = '' then
    raise exception 'my_profile: no authenticated email' using errcode = 'insufficient_privilege';
  end if;

  return query
    select u.id, u.name, u.email, u.picture_url
      from public.app_users u
     where lower(u.email) = lower(v_email);
end;
$$;

CREATE OR REPLACE FUNCTION public.notify_dispatch_now() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key text;
  v_url text;
begin
  -- Missing key or host means the POST would be rejected at the gateway anyway, so skip quietly:
  -- the scheduled job still delivers this event on its next tick.
  v_key := public.deployment_secret('service_role_key');
  v_url := public.deployment_secret('project_url');
  if v_key is null or v_url is null then
    return null;
  end if;

  -- The id goes in the body so the dispatcher delivers THIS event rather than draining the whole
  -- undelivered batch. Two notifications written a second apart would otherwise start two runs
  -- that both read the same batch and both post it.
  --
  -- The host comes from the vault, never from a literal: a literal is how a clone ends up posting
  -- one client's notifications to another client's project.
  perform net.http_post(
    url := rtrim(v_url, '/') || '/functions/v1/notify-dispatch',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object('mode', 'event', 'id', new.id),
    timeout_milliseconds := 30000
  );
  return null;
end $$;

CREATE OR REPLACE FUNCTION public.notify_event_from_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_name           text;
  v_recipient      uuid;
  v_actor_user     uuid;
  v_type           text;
  v_invoice_number text;
begin
  if new.type not in ('query', 'ablehnung', 'zuweisung') then
    return null;
  end if;
  if exists (select 1 from public.documents d where d.id = new.document_id and d.is_demo) then
    return null;
  end if;

  v_type := case new.type
              when 'query' then 'query'
              when 'ablehnung'  then 'rejected'
              else 'zuweisung'
            end;

  -- The name, for the payload and for the legacy fallback below. 'returned_to' for the two return
  -- types, 'assigned_to' for an assignment.
  v_name := nullif(btrim(coalesce(
              new.data ->> 'returned_to',
              new.data ->> 'assigned_to',
              '')), '');

  -- The id the app writes. Guarded rather than cast bare: a malformed value must degrade to the
  -- name fallback, not raise.
  begin
    v_recipient := nullif(btrim(coalesce(new.data ->> 'recipient_user_id', '')), '')::uuid;
  exception when others then
    v_recipient := null;
  end;

  -- Rows written before this migration carry only a name. Matched against app_users directly:
  -- the approvers table this used to go through is frozen and gains no new people.
  if v_recipient is null and v_name is not null then
    select u.id into v_recipient
      from public.app_users u
     where u.name is not null and lower(u.name) = lower(v_name)
     limit 1;
  end if;

  -- An un-assignment ("Zuweisung entfernt") has nobody to tell.
  if v_type = 'zuweisung' and v_recipient is null then
    return null;
  end if;

  -- Do not ring your own bell.
  if v_recipient is not null and new.actor is not null then
    select u.id into v_actor_user
      from public.app_users u
     where lower(u.email) = lower(new.actor)
        or (u.name is not null and lower(u.name) = lower(new.actor))
     limit 1;
    if v_actor_user = v_recipient then
      return null;
    end if;
  end if;

  select i.invoice_number into v_invoice_number
    from public.documents i where i.id = new.document_id;

  insert into public.notification_events (type, payload, recipient_user_id)
  values (
    v_type,
    jsonb_strip_nulls(jsonb_build_object(
      'document_id', new.document_id,
      'invoice_number', v_invoice_number,
      -- Kept under its original key for the two return types so existing consumers and stored
      -- payloads keep their vocabulary; an assignment says assigned_to.
      'returned_to', case when v_type <> 'zuweisung' then v_name end,
      'assigned_to', case when v_type =  'zuweisung' then v_name end,
      'note', nullif(btrim(coalesce(new.text, '')), ''),
      'actor', new.actor
    )),
    v_recipient
  );
  return null;
exception when others then
  -- A notification must never block the workflow write it observes.
  return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.opos_clear_no_receipt(p_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.bank_transactions
     set matching_status   = 'open',
         no_receipt_reason = null,
         whitelist_rule_id = null,
         no_receipt_set_by = null,
         no_receipt_set_at = null
   where id = p_transaction_id
     and matching_status = 'ignored';
end;
$$;

CREATE OR REPLACE FUNCTION public.opos_norm(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select btrim(regexp_replace(lower(coalesce(p_text, '')), '\s+', ' ', 'g'));
$$;

CREATE OR REPLACE FUNCTION public.opos_reapply_whitelist(p_rule_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_changed integer := 0;
begin
  -- Same gate as the policies above: this rewrites matching_status across every company.
  if not coalesce(
       public.current_role_name() = any (array['admin', 'super_admin', 'supervisor']), false) then
    raise exception 'not authorised' using errcode = '42501';
  end if;

  with kandidaten as (
    select t.id, t.payment_reference, t.counterparty_holder, t.counterparty_iban, t.booking_text,
           t.no_receipt_set_by, t.no_receipt_set_at, t.whitelist_rule_id
      from public.bank_transactions t
     where t.matching_status = 'ignored'
       -- A non-null whitelist_rule_id is exactly what separates "a rule hid this" from "a person
       -- did" -- opos_set_no_receipt leaves the column null. A human decision must never be undone
       -- here, which is the same guard apply_opos_whitelist() applies for the same reason.
       -- 'matched' rows are excluded by the status filter, so a reconciled payment is untouched.
       and t.whitelist_rule_id is not null
       and (p_rule_id is null or t.whitelist_rule_id = p_rule_id)
  ),
  neu as (
    select k.*, m.rule_id as neue_regel, m.category as neue_kategorie
      from kandidaten k
      left join lateral public.match_opos_whitelist(
        k.payment_reference, k.counterparty_holder, k.counterparty_iban, k.booking_text) m on true
  )
  update public.bank_transactions t
     set matching_status   = case when n.neue_regel is null then 'open' else 'ignored' end,
         no_receipt_reason = n.neue_kategorie,
         whitelist_rule_id = n.neue_regel,
         no_receipt_set_by = case when n.neue_regel is null
                                  then null else coalesce(n.no_receipt_set_by, 'system') end,
         no_receipt_set_at = case when n.neue_regel is null
                                  then null else coalesce(n.no_receipt_set_at, now()) end
    from neu n
   where t.id = n.id
     and n.neue_regel is distinct from n.whitelist_rule_id;

  get diagnostics v_changed = row_count;
  return v_changed;
end;
$$;

CREATE OR REPLACE FUNCTION public.opos_set_category(p_transaction_id uuid, p_category_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.bank_transactions
     set category_id     = p_category_id,
         category_source = case when p_category_id is null then null else 'human' end
   where id = p_transaction_id;
end;
$$;

CREATE OR REPLACE FUNCTION public.opos_set_no_receipt(p_transaction_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_reason is null or p_reason not in ('salary', 'tax_prepayment', 'private_withdrawal',
        'rebooking', 'loan_installment', 'fee_interest', 'atm_withdrawal', 'other') then
    raise exception 'opos_set_no_receipt: invalid reason %', p_reason;
  end if;

  update public.bank_transactions
     set matching_status   = 'ignored',
         no_receipt_reason = p_reason,
         whitelist_rule_id = null,           -- NULL = a human decided this
         no_receipt_set_by = coalesce(nullif(auth.jwt() ->> 'email', ''), 'hub'),
         no_receipt_set_at = now()
   where id = p_transaction_id
     and matching_status <> 'matched';    -- never un-reconcile a matched payment
end;
$$;

CREATE OR REPLACE FUNCTION public.outgoing_invoice_matched_sum(p_outgoing_invoice uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(amount_matched), 0)
    from public.outgoing_invoice_transaction_matches
   where outgoing_invoice_id = p_outgoing_invoice and status = 'confirmed';
$$;

CREATE OR REPLACE FUNCTION public.outgoing_transaction_allocated_sum(p_transaction uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(amount_matched), 0)
    from public.outgoing_invoice_transaction_matches
   where transaction_id = p_transaction and status = 'confirmed';
$$;

CREATE OR REPLACE FUNCTION public.payment_tolerance(p_gross numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  -- How far BELOW the gross a payment may land and still close the invoice. German Skonto is
  -- typically 2% and occasionally 3%, so 3% covers the real cases. The absolute cap stops the
  -- percentage from silently writing off a large sum: 3% of a 50.000 invoice would be 1.500,
  -- which no one should auto-close. The 0.01 floor keeps plain rounding working on tiny documents.
  select least(greatest(abs(coalesce(p_gross, 0)) * 0.03, 0.01), 150.00);
$$;

CREATE OR REPLACE FUNCTION public.pending_receipt_count() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select count(*)
    from public.bank_transactions b
    cross join lateral jsonb_array_elements(b.raw_data->'receipts') as r
   where b.source = 'pleo'
     and jsonb_typeof(b.raw_data->'receipts') = 'array'
     and r->>'id' is not null
     and not exists (
       select 1 from public.document_files f
        where f.transaction_id = b.id
          and f.external_id = r->>'id'
          and f.deleted_at is null
     );
$$;

CREATE OR REPLACE FUNCTION public.pending_receipt_downloads(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, external_id text, booking_date date, missing_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select b.id,
         b.external_id,
         b.booking_date,
         count(*)::int as missing_count
    from public.bank_transactions b
    cross join lateral jsonb_array_elements(b.raw_data->'receipts') as r
   where b.source = 'pleo'
     and jsonb_typeof(b.raw_data->'receipts') = 'array'
     and r->>'id' is not null
     -- the anti-join: this receipt has no stored file
     and not exists (
       select 1 from public.document_files f
        where f.transaction_id = b.id
          and f.external_id = r->>'id'
          and f.deleted_at is null
     )
   group by b.id, b.external_id, b.booking_date
   order by b.booking_date nulls last, b.id
   limit greatest(p_limit, 1);
$$;

CREATE OR REPLACE FUNCTION public.promote_first_bank_account_to_default() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
begin
    -- Being demoted right now, so not a candidate. Without this the single-default trigger's own
    -- cascade is undone row by row and the statement fails on the unique index.
    if tg_op = 'UPDATE' and old.is_default and not new.is_default then
        return new;
    end if;

    -- Already the default, or not a live account: nothing to promote.
    if new.is_default or new.deleted_at is not null or not coalesce(new.is_active, true) then
        return new;
    end if;

    -- A masked IBAN cannot be the default: supplier_bank_accounts_default_is_payable forbids it,
    -- and money cannot be sent to it. Tested against the value rather than the generated
    -- is_payable column, which a BEFORE trigger cannot yet see.
    if new.iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$' then
        return new;
    end if;

    if exists (select 1
                 from public.supplier_bank_accounts
                where supplier_id = new.supplier_id
                  and id <> new.id
                  and is_default
                  and deleted_at is null) then
        return new;
    end if;

    new.is_default := true;
    return new;
end;
$_$;

CREATE OR REPLACE FUNCTION public.propagate_account_company() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.company_id is distinct from old.company_id then
    update public.bank_transactions
       set company_id = new.company_id
     where account_id = new.id
       and company_id is distinct from new.company_id;
  end if;
  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.purge_record(p_table text, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_actor    text := coalesce(nullif(auth.jwt() ->> 'email', ''), 'hub');
  v_snapshot jsonb;
begin
  if not (public.is_admin() or public.has_permission('page.papierkorb')) then
    raise exception 'purge_record: not permitted' using errcode = 'insufficient_privilege';
  end if;
  if p_table is null or p_id is null then
    raise exception 'purge_record: table and id are required';
  end if;
  if p_table = 'documents' then
    raise exception
      'purge_record: documents cannot be purged -- GoBD requires receipts to be deactivated and '
      'kept, never hard-deleted. Restore it or leave it in the trash.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_table = 'approvers' then
    raise exception
      'purge_record: approvers cannot be purged -- approval_rules and approvers.deputy_name '
      'reference approvers(name), and purging a deputy would silently blank that reference. '
      'Restore it or leave it in the trash.'
      using errcode = 'insufficient_privilege';
  end if;
  if not (p_table = any(public.trash_purge_eligible_tables())) then
    raise exception 'purge_record: table % is not trash-eligible', p_table;
  end if;

  execute format('select to_jsonb(t) from public.%I t where id = $1 and deleted_at is not null', p_table)
    into v_snapshot using p_id;
  if v_snapshot is null then
    raise exception 'purge_record: % % is not currently deleted', p_table, p_id;
  end if;

  insert into public.change_history (table_name, record_id, type, text, actor, data, at)
  values (p_table, p_id, 'purged', 'Record permanently deleted', v_actor, v_snapshot, now());

  execute format('delete from public.%I where id = $1', p_table) using p_id;
end;
$_$;

CREATE OR REPLACE FUNCTION public.refuse_deleting_default_bank_account() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if old.is_default then
        raise exception 'cannot delete the default bank account of supplier %; set another account '
            'as the default first', old.supplier_id
            using errcode = 'restrict_violation';
    end if;
    return old;
end;
$$;

CREATE OR REPLACE FUNCTION public.request_approval_ping(p_recipient uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_transaction_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_transaction_id is not null then
    perform public.send_notification(
      p_recipient, p_note, 'transaction', p_transaction_id::text,
      '/banktransaktionen/' || p_transaction_id::text
    );
  elsif p_invoice_id is not null then
    perform public.send_notification(
      p_recipient, p_note, 'invoice', p_invoice_id::text,
      '/eingangsrechnungen/' || p_invoice_id::text
    );
  else
    perform public.send_notification(p_recipient, p_note, null, null, null);
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.resolve_approval_rule(p_invoice_id uuid) RETURNS public.approval_rules
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_rule public.approval_rules;
  v_area text;
  v_area_user uuid;
begin
  select r.* into v_rule
    from public.approval_rules r
    join public.documents i on i.id = p_invoice_id
   where r.is_active
     and r.deleted_at is null
     and r.min_amount <= coalesce(i.amount_gross, 0)
     and (r.supplier_id is null or r.supplier_id = i.supplier_id)
     and (r.property_id is null or r.property_id = i.property_id)
     and (r.company_id  is null or r.company_id  = i.company_id)
   order by r.specificity desc, r.min_amount desc, r.created_at desc
   limit 1;

  if v_rule.id is null then
    return null;
  end if;

  if v_rule.step_2_user_id is null and not v_rule.skip_step_2 then
    select c.area into v_area
      from public.documents i
      join public.companies c on c.id = i.company_id
     where i.id = p_invoice_id;

    select ru.id into v_area_user from public.resolve_area_user(v_area) ru;

    v_rule.step_2_user_id := v_area_user;
  end if;

  return v_rule;
end;
$$;

CREATE OR REPLACE FUNCTION public.resolve_area_user(p_area text) RETURNS SETOF public.app_users
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select u.*
    from public.app_users u
   where p_area is not null
     and u.is_active
     and (
       u.area = p_area
       or (
         u.covers_all_areas
         and not exists (
           select 1 from public.app_users x
            where x.is_active and x.area = p_area
         )
       )
     )
   order by (u.area = p_area) desc, u.created_at asc
   limit 1;
$$;

CREATE OR REPLACE FUNCTION public.resolve_assignment_rule(p_invoice uuid, p_target text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select r.id
    from public.assignment_rules r
    join public.documents i on i.id = p_invoice
   where r.is_active
     and r.deleted_at is null
     and r.target = p_target
     and (r.supplier_id      is null or r.supplier_id      = i.supplier_id)
     and (r.property_id      is null or r.property_id      = i.property_id)
     and (r.company_id       is null or r.company_id       = i.company_id)
     and (
       r.reference_pattern is null
       or coalesce(i.payment_reference, '') ilike '%' || public.escape_ilike_pattern(r.reference_pattern) || '%'
     )
   order by r.specificity desc, r.created_at desc
   limit 1;
$$;

CREATE OR REPLACE FUNCTION public.resolve_assignment_rule_candidates(p_invoice uuid, p_target text) RETURNS TABLE(rule_id uuid, specificity integer, is_winner boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select r.id, r.specificity,
         row_number() over (order by r.specificity desc, r.created_at desc) = 1
    from public.assignment_rules r
    join public.documents i on i.id = p_invoice
   where r.is_active
     and r.deleted_at is null
     and r.target = p_target
     and (r.supplier_id      is null or r.supplier_id      = i.supplier_id)
     and (r.property_id      is null or r.property_id      = i.property_id)
     and (r.company_id       is null or r.company_id       = i.company_id)
     and (
       r.reference_pattern is null
       or coalesce(i.payment_reference, '') ilike '%' || public.escape_ilike_pattern(r.reference_pattern) || '%'
     )
   order by r.specificity desc, r.created_at desc;
$$;

CREATE OR REPLACE FUNCTION public.resolve_default_vat_deductible_pct(p_property uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case p.vat_status
           when 'taxable' then 100
           when 'exempt'      then 0
           else null -- 'gemischt', or an unresolved property: genuinely ambiguous, needs a decision
         end
    from public.properties p
   where p.id = p_property;
$$;

CREATE OR REPLACE FUNCTION public.resolve_transaction_category(p_transaction uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select r.category_id
    from public.bank_transactions t
    join public.suppliers s
      on s.iban is not null
     and s.iban = t.counterparty_iban
     and s.deleted_at is null
    join public.assignment_rules r
      on r.target = 'cost_category'
     and r.is_active
     and r.deleted_at is null
     and r.supplier_id = s.id
     and r.category_id is not null
     and (
       r.reference_pattern is null
       or coalesce(t.payment_reference, '') ilike '%' || public.escape_ilike_pattern(r.reference_pattern) || '%'
     )
   where t.id = p_transaction
   order by r.specificity desc, r.created_at desc
   limit 1;
$$;

CREATE OR REPLACE FUNCTION public.restore_record(p_table text, p_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_actor  text := coalesce(nullif(auth.jwt() ->> 'email', ''), 'hub');
  v_rows   int;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if not (public.is_admin() or public.has_permission('page.papierkorb')) then
    raise exception 'restore_record: not permitted' using errcode = 'insufficient_privilege';
  end if;
  if p_table is null or p_id is null then
    raise exception 'restore_record: table and id are required';
  end if;
  if not (p_table = any(public.trash_eligible_tables())) then
    raise exception 'restore_record: table % is not trash-eligible', p_table;
  end if;

  -- GET DIAGNOSTICS, not FOUND: unreliable after a dynamic EXECUTE ... USING UPDATE on this
  -- project, per migration 0046's own note.
  execute format(
    'update public.%I set deleted_at = null, deleted_by = null, delete_reason = null '
    'where id = $1 and deleted_at is not null',
    p_table
  ) using p_id;
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    raise exception 'restore_record: % % is not currently deleted', p_table, p_id;
  end if;

  insert into public.change_history (table_name, record_id, type, text, actor, at)
  values (
    p_table,
    p_id,
    'restored',
    case
      when v_reason is null then 'Record restored from the trash'
      else 'Record restored from the trash: ' || v_reason
    end,
    v_actor,
    now()
  );
end;
$_$;

CREATE OR REPLACE FUNCTION public.run_bank_sync(p_mode text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_url  text;
  v_key  text;
  v_body jsonb;
  v_req  bigint;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'bank_sync_url';
  select decrypted_secret into v_key from vault.decrypted_secrets where name = 'bank_sync_service_key';

  if v_url is null or v_key is null then
    raise exception 'run_bank_sync: Vault secrets bank_sync_url / bank_sync_service_key are missing. '
                    'Load them with: .venv/bin/python pipeline/set_bank_sync_secrets.py --apply';
  end if;

  v_body := case when p_mode is null then '{}'::jsonb else jsonb_build_object('mode', p_mode) end;

  select net.http_post(
           url                  := rtrim(v_url, '/') || '/functions/v1/bank-sync',
           body                 := v_body,
           headers              := jsonb_build_object(
                                     'Content-Type', 'application/json',
                                     'Authorization', 'Bearer ' || v_key,
                                     'apikey', v_key),
           timeout_milliseconds := 60000
         )
    into v_req;

  return v_req;
end;
$$;

CREATE OR REPLACE FUNCTION public.run_now_enabled() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    select coalesce((select (config -> 'run' ->> 'run_now_enabled')::boolean
                       from public.tenant_settings where single_row), false)
$$;

CREATE OR REPLACE FUNCTION public.tenant_locale_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    select coalesce(
        (select config -> 'locale' from public.tenant_settings where single_row),
        '{"dateFormat": "dd.MM.yyyy", "decimalSeparator": ",", "currency": "EUR"}'::jsonb
    )
$$;

CREATE OR REPLACE FUNCTION public.tenant_tax_regime() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    select coalesce(
        (select config -> 'tax' from public.tenant_settings where single_row),
        '{"country": "DE", "defaultVatRate": 19, "taxModel": "flat"}'::jsonb
    )
$$;

CREATE OR REPLACE FUNCTION public.tenant_banking_provider() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    select coalesce(
        (select config -> 'banking' ->> 'provider' from public.tenant_settings where single_row),
        'banksapi'
    )
$$;

CREATE OR REPLACE FUNCTION public.tenant_card_provider() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    select coalesce(
        (select config -> 'cards' ->> 'provider' from public.tenant_settings where single_row),
        'pleo'
    )
$$;

CREATE OR REPLACE FUNCTION public.set_practice_mode(p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := public.current_app_user_id();
begin
  if v_user_id is null then
    raise exception 'set_practice_mode: no signed-in app user';
  end if;

  update public.app_users
     set practice_mode_until = case when p_active then now() + interval '30 minutes' else null end
   where id = v_user_id;
end $$;

CREATE OR REPLACE FUNCTION public.reset_onboarding_demo_data() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := public.current_app_user_id();
begin
  if v_user_id is null then
    raise exception 'reset_onboarding_demo_data: no signed-in app user';
  end if;

  update public.documents set deleted_at = now()
   where is_demo and demo_owner_user_id = v_user_id and deleted_at is null;
  update public.bank_transactions set deleted_at = now()
   where is_demo and demo_owner_user_id = v_user_id and deleted_at is null;
  update public.suppliers set deleted_at = now()
   where is_demo and demo_owner_user_id = v_user_id and deleted_at is null;
  update public.companies set deleted_at = now()
   where is_demo and demo_owner_user_id = v_user_id and deleted_at is null;
  update public.properties set deleted_at = now()
   where is_demo and demo_owner_user_id = v_user_id and deleted_at is null;
end $$;

-- The one scenario the "process an invoice" practice task walks through: a company and a property
-- to assign the uploaded sample invoice to, a supplier matching its issuer, and two bank
-- transactions (one correct, one a close decoy) for the bank-matching step to offer as candidates.
-- Codes are derived from the caller's id the same way the front end derives them
-- (demoCompanyAndPropertyCodes), so re-running this is idempotent per person.
CREATE OR REPLACE FUNCTION public.seed_onboarding_demo_data() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := public.current_app_user_id();
  v_tag text;
  v_company_id uuid;
  v_property_id uuid;
  v_supplier_id uuid;
begin
  if v_user_id is null then
    raise exception 'seed_onboarding_demo_data: no signed-in app user';
  end if;

  v_tag := substr(replace(v_user_id::text, '-', ''), 1, 8);

  select id into v_company_id from public.companies
   where is_demo and demo_owner_user_id = v_user_id and code = 'DEMO-' || v_tag;
  if v_company_id is not null then
    update public.companies set deleted_at = null where id = v_company_id and deleted_at is not null;
  else
    insert into public.companies (code, name, is_demo, demo_owner_user_id)
    values ('DEMO-' || v_tag, 'Demo Immobilien GmbH', true, v_user_id)
    returning id into v_company_id;
  end if;

  select id into v_property_id from public.properties
   where is_demo and demo_owner_user_id = v_user_id and code = 'DEMO-' || v_tag || '-P1';
  if v_property_id is not null then
    update public.properties set deleted_at = null where id = v_property_id and deleted_at is not null;
  else
    insert into public.properties (code, name, address, is_demo, demo_owner_user_id)
    values ('DEMO-' || v_tag || '-P1', 'Musterstrasse 12',
            'Musterstrasse 12, 20535 Hamburg', true, v_user_id)
    returning id into v_property_id;
  end if;

  insert into public.property_companies (property_id, company_id)
  select v_property_id, v_company_id
   where not exists (
     select 1 from public.property_companies pc
      where pc.property_id = v_property_id and pc.company_id = v_company_id and pc.deleted_at is null
   );

  select id into v_supplier_id from public.suppliers
   where is_demo and demo_owner_user_id = v_user_id;
  if v_supplier_id is not null then
    update public.suppliers set deleted_at = null where id = v_supplier_id and deleted_at is not null;
  else
    insert into public.suppliers (name, is_demo, demo_owner_user_id)
    values ('Gartenbau Möller', true, v_user_id)
    returning id into v_supplier_id;
  end if;

  -- Bank matching only ever offers candidates from the invoice's own company (scopedToCompany in
  -- matching.functions.ts), so a transaction seeded with no company_id can never be suggested. The
  -- existence check also has to look past a soft-deleted row: reset_onboarding_demo_data() deletes
  -- these on restart, and "not exists" alone would see the deleted row and skip reseeding it,
  -- leaving no candidate behind for the rest of the session.
  if exists (
    select 1 from public.bank_transactions
     where is_demo and demo_owner_user_id = v_user_id
       and payment_reference = 'MOELLER GARTENBAU RE 2026-1043 487,90'
  ) then
    update public.bank_transactions
       set deleted_at = null, company_id = v_company_id
     where is_demo and demo_owner_user_id = v_user_id
       and payment_reference = 'MOELLER GARTENBAU RE 2026-1043 487,90';
  else
    insert into public.bank_transactions (
      amount, currency, booking_date, value_date, payment_reference, booking_text,
      counterparty_holder, source, company_id, is_demo, demo_owner_user_id
    )
    values (
      -487.90, 'EUR', current_date, current_date,
      'MOELLER GARTENBAU RE 2026-1043 487,90', 'MOELLER GARTENBAU RE 2026-1043 487,90',
      'Gartenbau Möller', 'manual', v_company_id, true, v_user_id
    );
  end if;

  if exists (
    select 1 from public.bank_transactions
     where is_demo and demo_owner_user_id = v_user_id
       and payment_reference = 'MOELLER GARTENBAU RE 2026-0987 478,90'
  ) then
    update public.bank_transactions
       set deleted_at = null, company_id = v_company_id
     where is_demo and demo_owner_user_id = v_user_id
       and payment_reference = 'MOELLER GARTENBAU RE 2026-0987 478,90';
  else
    insert into public.bank_transactions (
      amount, currency, booking_date, value_date, payment_reference, booking_text,
      counterparty_holder, source, company_id, is_demo, demo_owner_user_id
    )
    values (
      -478.90, 'EUR', current_date - 28, current_date - 28,
      'MOELLER GARTENBAU RE 2026-0987 478,90', 'MOELLER GARTENBAU RE 2026-0987 478,90',
      'Gartenbau Möller', 'manual', v_company_id, true, v_user_id
    );
  end if;
end $$;

-- The "when does the system stop" practice task walks through three documents, each a different
-- reason the system refuses to go further on its own: a bank account the supplier has never
-- billed from before, a net amount the AI read wrong, and a document that is not an invoice at
-- all. One supplier carries the first case: a confirmed account (the one on file) plus a second,
-- unconfirmed one that the practice invoice names, which is exactly what useInvoiceBankAccounts
-- and accountChips read as "new" (src/data/suppliers/bank-accounts.ts,
-- InvoiceDetailPage.tsx:881). p_reset is always true from the one caller this has
-- (seedStopCasesPracticeData), because a fresh start or an explicit restart is meant to undo
-- whatever the practice run before it confirmed, corrected or set aside.
CREATE OR REPLACE FUNCTION public.seed_stop_cases_practice_data(p_reset boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := public.current_app_user_id();
  v_supplier_id uuid;
  v_new_account_id uuid;
  v_iban_doc_id uuid;
  v_ai_doc_id uuid;
  v_flyer_doc_id uuid;
begin
  if v_user_id is null then
    raise exception 'seed_stop_cases_practice_data: no signed-in app user';
  end if;

  select id into v_supplier_id from public.suppliers
   where is_demo and demo_owner_user_id = v_user_id and name = 'Stadtwerke Nord GmbH';
  if v_supplier_id is not null then
    update public.suppliers set deleted_at = null where id = v_supplier_id and deleted_at is not null;
  else
    insert into public.suppliers (name, is_demo, demo_owner_user_id)
    values ('Stadtwerke Nord GmbH', true, v_user_id)
    returning id into v_supplier_id;
  end if;

  -- The account already on file. trg_supplier_default_account_sync copies this onto
  -- suppliers.iban/bic/bank_name, so nothing writes that column directly.
  insert into public.supplier_bank_accounts (
    supplier_id, iban, bic, bank_name, source, is_active, is_default, is_payable,
    confirmed_at, confirmed_by
  )
  values (
    v_supplier_id, 'DE89370400440532013000', 'COBADEFFXXX', 'Commerzbank',
    'human', true, true, true, now(), 'system'
  )
  on conflict (supplier_id, iban) do update
     set is_active = true, is_default = true, is_payable = true,
         confirmed_at = coalesce(public.supplier_bank_accounts.confirmed_at, now()),
         deleted_at = null, deleted_by = null, delete_reason = null;

  -- The account this one practice invoice names. Left unconfirmed on every (re)start: a previous
  -- run may have confirmed it, and the practice is meant to offer the same choice again.
  insert into public.supplier_bank_accounts (
    supplier_id, iban, bic, bank_name, source, is_active, is_default, is_payable,
    confirmed_at, confirmed_by, first_seen_at
  )
  values (
    v_supplier_id, 'DE12500105170648489890', 'INGDDEFFXXX', 'ING-DiBa',
    'pipeline', true, false, true, null, null, now()
  )
  on conflict (supplier_id, iban) do update
     set is_active = true, is_payable = true, confirmed_at = null, confirmed_by = null,
         deleted_at = null, deleted_by = null, delete_reason = null
  returning id into v_new_account_id;

  -- 1) The changed-bank-account invoice. document_bank_accounts is what makes
  -- useInvoiceBankAccounts say this account came off the document rather than off the supplier.
  select id into v_iban_doc_id from public.documents
   where is_demo and demo_owner_user_id = v_user_id and invoice_number = 'STOP-IBAN-1';
  if v_iban_doc_id is not null then
    update public.documents set deleted_at = null where id = v_iban_doc_id and deleted_at is not null;
  else
    insert into public.documents (
      document_type, is_invoice, intake_channel, source, status, workflow_status,
      issuer, supplier_id, invoice_number, document_date, due_date,
      amount_net, vat_rate, vat_amount, amount_gross, currency,
      is_demo, demo_owner_user_id
    )
    values (
      'rechnung', true, 'upload', 'manual', 'needs_review', 'received',
      'Stadtwerke Nord GmbH', v_supplier_id, 'STOP-IBAN-1', current_date - 10, current_date + 20,
      150.00, 19, 28.50, 178.50, 'EUR',
      true, v_user_id
    )
    returning id into v_iban_doc_id;
  end if;

  insert into public.document_bank_accounts (document_id, supplier_bank_account_id, position, origin)
  values (v_iban_doc_id, v_new_account_id, 1, 'invoice')
  on conflict (document_id, supplier_bank_account_id) do nothing;
  -- Drop any other link a previous run left (e.g. the confirmed account, once this one has been
  -- confirmed too), so the practice invoice always names exactly the one account under test.
  delete from public.document_bank_accounts
   where document_id = v_iban_doc_id and supplier_bank_account_id <> v_new_account_id;

  -- 2) The AI-misread invoice. vat_amount and amount_gross already agree with the CORRECT net
  -- (STOP_CASES_CORRECT_NET_AMOUNT in practice-stop-cases-task.ts), so correcting amount_net is
  -- the one edit that makes documentUpdatedEventData's amounts_add_up true.
  select id into v_ai_doc_id from public.documents
   where is_demo and demo_owner_user_id = v_user_id and invoice_number = 'STOP-AI-1';
  if v_ai_doc_id is not null then
    update public.documents
       set deleted_at = null, amount_net = 1200.00, amount_gross = 1475.60
     where id = v_ai_doc_id;
  else
    insert into public.documents (
      document_type, is_invoice, intake_channel, source, status, workflow_status,
      issuer, invoice_number, document_date, due_date,
      amount_net, vat_rate, vat_amount, amount_gross, currency,
      is_demo, demo_owner_user_id
    )
    values (
      'rechnung', true, 'upload', 'manual', 'needs_review', 'received',
      'Gebäudereinigung Blitz GmbH', 'STOP-AI-1', current_date - 5, current_date + 25,
      1200.00, 19, 235.60, 1475.60, 'EUR',
      true, v_user_id
    )
    returning id into v_ai_doc_id;
  end if;

  -- 3) The not-an-invoice document. Reset back to relevant on every (re)start so "set aside" can
  -- be practiced again.
  select id into v_flyer_doc_id from public.documents
   where is_demo and demo_owner_user_id = v_user_id and invoice_number = 'STOP-FLYER-1';
  if v_flyer_doc_id is not null then
    update public.documents
       set deleted_at = null, not_relevant_at = null, not_relevant_by = null,
           not_relevant_note = null, workflow_status = 'received'
     where id = v_flyer_doc_id;
  else
    insert into public.documents (
      document_type, is_invoice, intake_channel, source, status, workflow_status,
      issuer, invoice_number, document_date,
      is_demo, demo_owner_user_id
    )
    values (
      'werbung', false, 'upload', 'manual', 'needs_review', 'received',
      'Büromöbel Profi Werbung', 'STOP-FLYER-1', current_date - 2,
      true, v_user_id
    )
    returning id into v_flyer_doc_id;
  end if;

  return jsonb_build_object(
    'supplier_id', v_supplier_id,
    'iban_account_id', v_new_account_id,
    'iban_document_id', v_iban_doc_id,
    'ai_document_id', v_ai_doc_id,
    'flyer_document_id', v_flyer_doc_id
  );
end $$;

-- Saves a deal with its sides, payers and costs in one transaction, as the caller. Any edit withdraws
-- an approval, because what was approved is no longer what is saved.
CREATE OR REPLACE FUNCTION public.save_deal(p_deal_id uuid, p_deal jsonb, p_sides jsonb, p_status text, p_costs jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY INVOKER
    SET search_path TO 'public'
    AS $$
declare
  v_side jsonb;
  v_side_id uuid;
  v_party jsonb;
  v_cost jsonb;
  v_position integer;
  v_current_status text;
begin
  if p_status not in ('incomplete', 'ready') then
    raise exception 'save_deal: a saved deal is incomplete or ready, not %', p_status
      using errcode = 'check_violation';
  end if;

  select status into v_current_status from public.deals where id = p_deal_id;
  if v_current_status not in ('incomplete', 'ready') then
    raise exception 'save_deal: deal % is % and can no longer be edited this way', p_deal_id, v_current_status
      using errcode = 'check_violation';
  end if;

  update public.deals
     set company_id = nullif(p_deal->>'company_id', '')::uuid,
         notarised_on = nullif(p_deal->>'notarised_on', '')::date,
         purchase_price = (p_deal->>'purchase_price')::numeric,
         vat_rate = coalesce((p_deal->>'vat_rate')::numeric, 19),
         note = nullif(p_deal->>'note', ''),
         acquired_by = nullif(p_deal->>'acquired_by', '')::uuid,
         handled_by = nullif(p_deal->>'handled_by', '')::uuid,
         own_lead = coalesce((p_deal->>'own_lead')::boolean, false),
         from_viewing = coalesce((p_deal->>'from_viewing')::boolean, false),
         referrer_customer_id = nullif(p_deal->>'referrer_customer_id', '')::uuid,
         costs_closed_at = case when coalesce((p_deal->>'costs_closed')::boolean, false)
                                then coalesce(costs_closed_at, now()) end,
         ready_for_bookkeeping_at = case when coalesce((p_deal->>'ready_for_bookkeeping')::boolean, false)
                                         then coalesce(ready_for_bookkeeping_at, now()) end,
         status = p_status,
         approved_by = null,
         approved_at = null
   where id = p_deal_id and deleted_at is null;
  if not found then
    raise exception 'save_deal: deal % not found', p_deal_id using errcode = 'no_data_found';
  end if;

  delete from public.deal_sides
   where deal_id = p_deal_id
     and side not in (select value->>'side' from jsonb_array_elements(p_sides));

  for v_side in select value from jsonb_array_elements(p_sides) loop
    insert into public.deal_sides (deal_id, side, fee_kind, fee_net_rate, fee_net_amount)
    values (p_deal_id, v_side->>'side', v_side->>'fee_kind', (v_side->>'fee_net_rate')::numeric,
            (v_side->>'fee_net_amount')::numeric)
    on conflict (deal_id, side) do update
       set fee_kind = excluded.fee_kind,
           fee_net_rate = excluded.fee_net_rate,
           fee_net_amount = excluded.fee_net_amount
    returning id into v_side_id;

    delete from public.deal_parties where deal_side_id = v_side_id;
    v_position := 0;
    for v_party in select value from jsonb_array_elements(coalesce(v_side->'parties', '[]'::jsonb)) loop
      insert into public.deal_parties
          (deal_side_id, customer_id, share_percent, discount_gross, discount_reason, position)
      values (v_side_id, (v_party->>'customer_id')::uuid, (v_party->>'share_percent')::numeric,
              coalesce((v_party->>'discount_gross')::numeric, 0),
              nullif(v_party->>'discount_reason', ''), v_position);
      v_position := v_position + 1;
    end loop;
  end loop;

  delete from public.deal_costs where deal_id = p_deal_id;
  for v_cost in select value from jsonb_array_elements(coalesce(p_costs, '[]'::jsonb)) loop
    insert into public.deal_costs (deal_id, kind, description, amount, incurred_on)
    values (p_deal_id, v_cost->>'kind', nullif(v_cost->>'description', ''),
            (v_cost->>'amount')::numeric, nullif(v_cost->>'incurred_on', '')::date);
  end loop;
end;
$$;

CREATE OR REPLACE FUNCTION public.send_notification(p_recipient uuid, p_note text DEFAULT NULL::text, p_target_kind text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_target_path text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_sender      uuid := public.current_app_user_id();
  v_sender_name text;
  v_kind        public.notification_target_kinds%rowtype;
  v_exists      boolean;
  v_target      jsonb;
  v_id          bigint;
begin
  if v_sender is null then
    raise exception 'send_notification: no active app_users row for this session'
      using errcode = 'insufficient_privilege';
  end if;
  if p_recipient is null then
    raise exception 'send_notification: recipient is required';
  end if;

  -- YOURSELF IS NOT A RECIPIENT. A notification is how you ask somebody else to look at something;
  -- sent to your own account it is a bell entry from you, to you, about what is already on your
  -- screen. The picker filters you out too, so reaching this means a stale page or a direct call.
  if p_recipient = v_sender then
    raise exception 'send_notification: cannot notify yourself'
      using errcode = 'check_violation';
  end if;

  if not exists (select 1 from public.app_users where id = p_recipient and is_active) then
    raise exception 'send_notification: recipient % is not an active user', p_recipient;
  end if;

  if p_target_kind is not null then
    select * into v_kind
      from public.notification_target_kinds
     where kind = p_target_kind and is_active;
    if not found then
      raise exception 'send_notification: unknown target kind %', p_target_kind
        using errcode = 'check_violation';
    end if;

    -- The record has to be there. A notification pointing at something deleted sends the recipient
    -- to a broken page with no way to tell whether they misread it or it is gone.
    --
    -- format %I quotes the identifiers, and both of them come from this table rather than from the
    -- caller, so the dynamic statement cannot be steered from outside.
    if v_kind.source_table is not null and p_target_id is not null then
      execute format(
        'select exists (select 1 from public.%I where %I::text = $1)',
        v_kind.source_table, v_kind.id_column
      ) into v_exists using p_target_id;
      if not v_exists then
        raise exception 'send_notification: no % with id %', p_target_kind, p_target_id
          using errcode = 'check_violation';
      end if;
    end if;
  end if;

  -- A relative path only. An absolute URL here would let a notification carry somebody off to
  -- another host, which is not what "open the record" should be able to mean.
  if p_target_path is not null and p_target_path !~ '^/[^/]' then
    raise exception 'send_notification: target path must be a relative path starting with /'
      using errcode = 'check_violation';
  end if;

  select name into v_sender_name from public.app_users where id = v_sender;

  if p_target_kind is not null or p_target_path is not null then
    v_target := jsonb_strip_nulls(jsonb_build_object(
      'kind', p_target_kind,
      'id',   p_target_id,
      'path', p_target_path
    ));
  end if;

  insert into public.notification_events (type, payload, recipient_user_id, created_by)
  values (
    'ping',
    jsonb_strip_nulls(jsonb_build_object(
      'target',    v_target,
      'note',      nullif(btrim(coalesce(p_note, '')), ''),
      'from_name', v_sender_name,
      -- WRITTEN FOR THE OLD READERS TOO. Rows created before today carry document_id/transaction_id
      -- at the top level and several places still read them. Keeping both shapes on new rows means
      -- the front end and the dispatcher can be migrated after this ships rather than in the same
      -- breath, and nothing has to backfill the history.
      'document_id',     case when p_target_kind = 'invoice' then p_target_id end,
      'transaction_id', case when p_target_kind = 'transaction' then p_target_id end
    )),
    p_recipient,
    v_sender
  )
  returning id into v_id;

  return v_id;
end $_$;

CREATE OR REPLACE FUNCTION public.set_bank_account_connect_route() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.provider_ref is null then
    new.connect_route := coalesce(new.connect_route, 'ebics_or_manual');
  else
    select case when p.is_supported then 'banksapi' else 'ebics_or_manual' end
      into new.connect_route
      from bank_providers p where p.provider_ref = new.provider_ref;
  end if;
  return new;
end $$;

CREATE OR REPLACE FUNCTION public.set_bank_transaction_company() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  select ba.company_id into new.company_id
    from public.bank_accounts ba
   where ba.id = new.account_id;
  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.set_channel_secret(p_channel text, p_secret text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_name text;
  v_id uuid;
  v_old text;
  v_pattern text;
  v_secret text := nullif(regexp_replace(coalesce(p_secret, ''), '\s', '', 'g'), '');
begin
  if not public.is_admin() then
    raise exception 'set_channel_secret: admin only'
      using errcode = 'insufficient_privilege';
  end if;

  select coalesce(config ->> 'secret_pattern', '') into v_pattern
    from public.notification_channels
   where key = p_channel;

  if not found then
    raise exception 'set_channel_secret: unknown channel %', p_channel;
  end if;

  if v_secret is not null and v_pattern <> '' and v_secret !~ v_pattern then
    raise exception 'set_channel_secret: value does not match the format % expects', p_channel;
  end if;

  v_name := public.channel_secret_name(p_channel);
  select id into v_id from vault.secrets where name = v_name limit 1;
  if v_id is not null then
    select decrypted_secret into v_old from vault.decrypted_secrets where id = v_id;
  end if;

  if v_secret is null then
    if v_id is not null then
      delete from vault.secrets where id = v_id;
    end if;
    update public.notification_channels
       set enabled = false, updated_at = now()
     where key = p_channel and enabled;
    return;
  end if;

  if v_id is null then
    begin
      perform vault.create_secret(v_secret, v_name, 'Credential for notification channel ' || p_channel);
    exception when unique_violation then
      select id into v_id from vault.secrets where name = v_name limit 1;
      perform vault.update_secret(v_id, v_secret);
    end;
  elsif v_old is distinct from v_secret then
    perform vault.update_secret(v_id, v_secret);
  end if;
end;
$$;

CREATE OR REPLACE FUNCTION public.set_datev_route(p_company_id uuid, p_direction text, p_address text, p_is_enabled boolean, p_note text, p_updated_by text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Must come BEFORE has_company_access(): that function answers true for an anonymous caller.
  if auth.uid() is null then
    raise exception 'set_datev_route: authentication required' using errcode = 'insufficient_privilege';
  end if;
  if not public.may_write('rules.write') then
    raise exception 'set_datev_route: rules.write required' using errcode = 'insufficient_privilege';
  end if;
  if not public.has_company_access(p_company_id) then
    raise exception 'set_datev_route: no access to this company' using errcode = 'insufficient_privilege';
  end if;

  insert into public.handover_routes (company_id, direction, address, is_enabled, note, updated_by, updated_at)
  values (p_company_id, p_direction, p_address, p_is_enabled, p_note, p_updated_by, now())
  on conflict (company_id, direction) do update set
    address    = excluded.address,
    is_enabled = excluded.is_enabled,
    note       = excluded.note,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at;
end;
$$;

revoke execute on function public.set_datev_route(uuid, text, text, boolean, text, text) from public;
revoke execute on function public.set_datev_route(uuid, text, text, boolean, text, text) from anon;
grant execute on function public.set_datev_route(uuid, text, text, boolean, text, text) to authenticated;

CREATE OR REPLACE FUNCTION public.set_my_name(p_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email text := coalesce(nullif(auth.jwt() ->> 'email', ''), '');
  v_name  text := btrim(coalesce(p_name, ''));
begin
  if v_email = '' then
    raise exception 'set_my_name: no authenticated email' using errcode = 'insufficient_privilege';
  end if;
  if v_name = '' then
    raise exception 'set_my_name: the name must not be empty' using errcode = 'check_violation';
  end if;
  if length(v_name) > 120 then
    raise exception 'set_my_name: the name is longer than 120 characters' using errcode = 'check_violation';
  end if;

  update public.app_users
     set name = v_name,
         updated_at = now()
   where lower(email) = lower(v_email);

  if not found then
    raise exception 'set_my_name: no app_users row for %', v_email;
  end if;
end;
$$;

CREATE OR REPLACE FUNCTION public.set_my_picture_url(p_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_email text := coalesce(nullif(auth.jwt() ->> 'email', ''), '');
  v_url   text := nullif(btrim(coalesce(p_url, '')), '');
begin
  if v_email = '' then
    raise exception 'set_my_picture_url: no authenticated email' using errcode = 'insufficient_privilege';
  end if;
  -- Only a url inside our own bucket. Without this the column would accept any address on the
  -- internet, and every screen showing the picture would fetch it from there.
  if v_url is not null and position('/storage/v1/object/public/profile-pictures/' in v_url) = 0 then
    raise exception 'set_my_picture_url: the url does not point at the profile-pictures bucket'
      using errcode = 'check_violation';
  end if;

  update public.app_users
     set picture_url = v_url,
         updated_at = now()
   where lower(email) = lower(v_email);

  if not found then
    raise exception 'set_my_picture_url: no app_users row for %', v_email;
  end if;
end;
$$;

CREATE OR REPLACE FUNCTION public.set_transaction_fully_used(p_transaction_id uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor text := coalesce(nullif(auth.jwt() ->> 'email', ''), 'hub');
  v_alloc numeric;
begin
  if p_transaction_id is null then
    raise exception 'set_transaction_fully_used: transaction is required';
  end if;

  v_alloc := public.transaction_allocated_sum(p_transaction_id)
           + public.outgoing_transaction_allocated_sum(p_transaction_id);
  if coalesce(v_alloc, 0) <= 0 then
    raise exception
      'set_transaction_fully_used: nothing is allocated to this transaction yet'
      using errcode = 'check_violation';
  end if;

  update public.bank_transactions
     set fully_used_at   = now(),
         fully_used_by   = v_actor,
         fully_used_note = p_note,
         matching_status = case when matching_status = 'ignored' then matching_status
                                else 'matched' end
   where id = p_transaction_id;
end $$;

CREATE OR REPLACE FUNCTION public.set_transaction_spender() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.spender_email := lower(nullif(trim(coalesce(new.spender_email, '')), ''));
  new.spender_name := nullif(trim(coalesce(new.spender_name, '')), '');
  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.set_uploaded_outgoing_invoice_status(p_id uuid, p_status text, p_actor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_source text;
begin
  if p_status not in ('draft', 'open', 'paidoff', 'voided') then
    raise exception 'set_uploaded_outgoing_invoice_status: invalid status %', p_status
      using errcode = 'check_violation';
  end if;

  select source into v_source from public.outgoing_invoices where id = p_id;
  if v_source is null then
    raise exception 'set_uploaded_outgoing_invoice_status: outgoing invoice % not found', p_id;
  end if;
  if v_source <> 'upload' then
    raise exception
      'set_uploaded_outgoing_invoice_status: invoice % is source=%, not upload -- LexOffice is the status authority for it, not this app',
      p_id, v_source using errcode = 'insufficient_privilege';
  end if;

  update public.outgoing_invoices
     set status = p_status, status_source = 'manual', updated_at = now()
   where id = p_id;

  insert into public.change_history (table_name, record_id, type, text, actor, data, at)
  values ('outgoing_invoices', p_id, 'statuswechsel',
          format('Status manuell auf "%s" gesetzt', p_status), p_actor,
          jsonb_build_object('status', p_status), now());
end;
$$;

CREATE OR REPLACE FUNCTION public.set_user_slack_id(p_user uuid, p_slack_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_value text := btrim(coalesce(p_slack_id, ''));
begin
  if not public.is_admin() then
    raise exception 'set_user_slack_id: admin only'
      using errcode = 'insufficient_privilege';
  end if;

  if p_slack_id is not null and v_value <> '' and v_value !~ '^[UW][A-Z0-9]+$' then
    raise exception 'set_user_slack_id: % is not a Slack member id', v_value;
  end if;

  update public.app_users
     set slack_user_id = case when p_slack_id is null then null else v_value end,
         updated_at = now()
   where id = p_user;

  if not found then
    raise exception 'set_user_slack_id: unknown user %', p_user;
  end if;
end;
$_$;

CREATE OR REPLACE FUNCTION public.suggest_assignment_rules() RETURNS TABLE(supplier_id uuid, category_id uuid, cost_category text, receipt_count bigint, total_receipts bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with base as (
    select i.id, i.supplier_id, i.category_id, i.cost_category
      from public.documents i
     where i.deleted_at is null
       and i.archived_at is null
       and i.supplier_id is not null
       and (i.category_id is not null or coalesce(i.cost_category, '') <> '')
       and public.resolve_assignment_rule(i.id, 'cost_category') is null
  ),
  grouped as (
    select supplier_id, category_id, cost_category, count(*) as n
      from base
     group by supplier_id, category_id, cost_category
  ),
  ranked as (
    select *, row_number() over (partition by supplier_id order by n desc) as rnk
      from grouped
  ),
  totals as (
    select supplier_id, count(*) as total from base group by supplier_id
  )
  select r.supplier_id, r.category_id, r.cost_category, r.n, t.total
    from ranked r
    join totals t on t.supplier_id = r.supplier_id
   where r.rnk = 1
   order by t.total desc;
$$;

CREATE OR REPLACE FUNCTION public.supplier_bank_accounts_single_default() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if not new.is_default then
        return new;
    end if;

    -- A row ARRIVING from another supplier (merge_suppliers reassigns supplier_id) must not depose
    -- the keeper's own default. Without this the merge just fails on the unique index below.
    if tg_op = 'UPDATE'
       and new.supplier_id is distinct from old.supplier_id
       and exists (select 1 from public.supplier_bank_accounts
                    where supplier_id = new.supplier_id and id <> new.id and is_default) then
        new.is_default := false;
        return new;
    end if;

    -- Setting a default clears the previous one. No recursion: the inner update writes
    -- is_default = false, and this function returns early for those rows.
    update public.supplier_bank_accounts
       set is_default = false
     where supplier_id = new.supplier_id
       and id <> new.id
       and is_default;

    return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.supplier_default_account_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if not new.is_default then
        return null;
    end if;

    -- The IBAN is written ONLY when it actually differs compacted. Two reasons, and the second is
    -- the one that bites: many suppliers store their IBAN with spaces, so assigning the compacted
    -- form unconditionally would rewrite `suppliers.iban` on an edit that only touched the BIC.
    -- That is not a change of account, but supplier_iban_history would record it as one and the
    -- supplier list would show a bank-details warning for it.
    update public.suppliers s
       set iban = case
                    when upper(regexp_replace(coalesce(s.iban, ''), '[[:space:].-]', '', 'g'))
                         is distinct from new.iban
                    then new.iban
                    else s.iban
                  end,
           bic        = coalesce(new.bic, s.bic),
           bank_name  = coalesce(new.bank_name, s.bank_name),
           updated_at = now()
     where s.id = new.supplier_id
       and (
             upper(regexp_replace(coalesce(s.iban, ''), '[[:space:].-]', '', 'g'))
               is distinct from new.iban
             or (new.bic is not null and s.bic is distinct from new.bic)
             or (new.bank_name is not null and s.bank_name is distinct from new.bank_name)
           );

    return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.supplier_default_iban_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    compact text := upper(regexp_replace(coalesce(new.iban, ''), '[[:space:].-]', '', 'g'));
begin
    if compact = '' then
        update public.supplier_bank_accounts
           set is_default = false
         where supplier_id = new.id and is_default;
        return null;
    end if;

    update public.supplier_bank_accounts
       set is_default = false
     where supplier_id = new.id and is_default and iban <> compact;

    update public.supplier_bank_accounts
       set is_default = true, is_active = true
     where supplier_id = new.id and iban = compact and not is_default;

    return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.sync_invoice_paid_from_matches() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice   uuid := coalesce(new.document_id, old.document_id);
  v_gross     numeric;
  v_matched   numeric;
  v_paydate   date;
  v_paid_at   timestamptz;
  v_source    text;
  v_shortfall numeric;
  -- The person, when a person did it. Empty for the pipeline and for cron.
  v_actor     text := coalesce(nullif(auth.jwt() ->> 'email', ''), 'system');
begin
  select abs(amount_gross), paid_at, paid_source
    into v_gross, v_paid_at, v_source
    from public.documents where id = v_invoice;
  if not found then
    return null;
  end if;

  select coalesce(sum(m.amount_matched), 0), max(t.booking_date)
    into v_matched, v_paydate
    from public.document_transaction_matches m
    join public.bank_transactions t on t.id = m.transaction_id
   where m.document_id = v_invoice and m.status = 'confirmed';

  if v_gross is not null and v_gross > 0
     and v_matched > 0
     and v_matched >= v_gross - public.payment_tolerance(v_gross) then
    if v_paid_at is null then
      update public.documents
         set paid_at     = coalesce(v_paydate::timestamptz, now()),
             paid_source = 'bank_match',
             lexoffice_open_amount = 0,
             updated_at  = now()
       where id = v_invoice;

      v_shortfall := v_gross - v_matched;
      insert into public.document_history (document_id, type, text, actor, data)
      values (
        v_invoice,
        'aenderung',
        -- Unchanged wording. Persisted audit text stays German.
        case when v_shortfall > 0.01
          then format('Marked as paid (confirmed bank match, %s EUR discount)',
                      to_char(v_shortfall, 'FM999G999G990D00'))
          else 'Marked as paid (confirmed bank match)'
        end,
        v_actor,
        jsonb_strip_nulls(jsonb_build_object(
          'event', 'paid_from_match',
          'skonto', case when v_shortfall > 0.01 then v_shortfall end
        ))
      );
    end if;
  else
    if v_paid_at is not null and v_source = 'bank_match' then
      update public.documents
         set paid_at     = null,
             paid_source = null,
             updated_at  = now()
       where id = v_invoice;

      insert into public.document_history (document_id, type, text, actor, data)
      values (
        v_invoice,
        'aenderung',
        format('Payment withdrawn: the bank match now covers only %s of %s EUR',
               to_char(v_matched, 'FM999G999G990D00'),
               to_char(v_gross, 'FM999G999G990D00')),
        v_actor,
        jsonb_build_object(
          'event', 'payment_withdrawn',
          'matched', v_matched,
          'gross', v_gross
        )
      );
    end if;
  end if;

  return null;
end $$;

CREATE OR REPLACE FUNCTION public.check_match_same_world() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_document_demo boolean;
  v_transaction_demo boolean;
begin
  select d.is_demo into v_document_demo from public.documents d where d.id = new.document_id;
  select t.is_demo into v_transaction_demo from public.bank_transactions t where t.id = new.transaction_id;
  if v_document_demo is not null
     and v_transaction_demo is not null
     and v_document_demo <> v_transaction_demo then
    raise exception 'a practice row cannot be matched with a real row' using errcode = 'check_violation';
  end if;
  return new;
end $$;

CREATE OR REPLACE FUNCTION public.sync_transaction_matching_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tx    uuid := coalesce(new.transaction_id, old.transaction_id);
  v_total numeric;
  v_alloc numeric;
begin
  select abs(amount) into v_total from public.bank_transactions where id = v_tx;
  if v_total is null then
    return null;
  end if;

  v_alloc := public.transaction_allocated_sum(v_tx) + public.outgoing_transaction_allocated_sum(v_tx);

  update public.bank_transactions t
     set matching_status = case
           -- A hand-closed transaction stays closed even with a remainder. It still has to carry
           -- at least one confirmed allocation: "fully used" describes what happened to a payment
           -- that paid something, not a way to file an untouched one away.
           when t.fully_used_at is not null and v_alloc > 0 then 'matched'
           when v_alloc > 0 and v_alloc >= v_total - 0.01 then 'matched'
           else 'open'
         end
   where t.id = v_tx
     and t.matching_status <> 'ignored';

  return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.sync_uploaded_outgoing_invoice_status_from_matches() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice_id    uuid := coalesce(new.outgoing_invoice_id, old.outgoing_invoice_id);
  v_source        text;
  v_gross         numeric;
  v_status        text;
  v_status_source text;
  v_matched       numeric;
begin
  select source, amount_gross, status, status_source
    into v_source, v_gross, v_status, v_status_source
    from public.outgoing_invoices where id = v_invoice_id;
  if not found or v_source <> 'upload' then
    return null;
  end if;

  select public.outgoing_invoice_matched_sum(v_invoice_id) into v_matched;

  if v_gross is not null and v_gross > 0
     and v_matched > 0
     and v_matched >= v_gross - public.payment_tolerance(v_gross) then
    -- A manual override (status_source='manual') is never touched in EITHER direction -- e.g.
    -- someone deliberately holding an invoice 'open' despite a covering match must not have it
    -- silently flipped back to 'paidoff' the next time this trigger fires.
    if v_status_source is distinct from 'manual' and v_status not in ('paidoff', 'voided') then
      update public.outgoing_invoices
         set status = 'paidoff', status_source = 'auto', updated_at = now()
       where id = v_invoice_id;

      insert into public.change_history (table_name, record_id, type, text, actor, data, at)
      values ('outgoing_invoices', v_invoice_id, 'statuswechsel',
              'Marked as paid (confirmed bank match)', 'system',
              jsonb_build_object('status', 'paidoff', 'matched', v_matched, 'gross', v_gross),
              now());
    end if;
  else
    -- No longer covered (link removed or amount reduced). Only a status THIS trigger set is
    -- withdrawn -- a manual override is never touched.
    if v_status = 'paidoff' and v_status_source = 'auto' then
      update public.outgoing_invoices
         set status = 'open', status_source = null, updated_at = now()
       where id = v_invoice_id;

      insert into public.change_history (table_name, record_id, type, text, actor, data, at)
      values ('outgoing_invoices', v_invoice_id, 'statuswechsel',
              'Payment withdrawn: the bank match no longer covers the invoice in full',
              'system',
              jsonb_build_object('status', 'open', 'matched', v_matched, 'gross', v_gross),
              now());
    end if;
  end if;

  return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.touch_tour_progress() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    new.updated_at := now();
    new.first_seen_at := old.first_seen_at;
    return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.transaction_allocated_sum(p_transaction uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(amount_matched), 0)
    from public.document_transaction_matches
   where transaction_id = p_transaction and status = 'confirmed';
$$;

CREATE OR REPLACE FUNCTION public.trash_eligible_tables() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select array[
    'documents', 'suppliers', 'customers', 'outgoing_invoices', 'manual_bookings',
    'approval_rules', 'assignment_rules', 'ingest_exclusions', 'open_item_whitelist_rules',
    'categories', 'properties', 'companies', 'business_line', 'approvers',
    'supplier_bank_accounts'
  ];
$$;

CREATE OR REPLACE FUNCTION public.trash_purge_eligible_tables() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select array(
    select t from unnest(public.trash_eligible_tables()) as t
    where t not in ('documents', 'approvers')
  );
$$;

CREATE OR REPLACE FUNCTION public.trash_require_delete_reason() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if btrim(coalesce(new.delete_reason, '')) = '' then
    raise exception
      'A reason is required (%.%): delete_reason cannot be empty when deleting.',
      tg_table_schema, tg_table_name
      using errcode = 'check_violation',
            hint = 'Say why this record is being deleted.';
  end if;
  -- Store the trimmed value, so trailing whitespace cannot make a reason look present when it is
  -- one space long.
  new.delete_reason := btrim(new.delete_reason);
  return new;
end;
$$;

CREATE OR REPLACE FUNCTION public.trg_fn_bank_transactions_categorize() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_category uuid;
begin
  v_category := public.resolve_transaction_category(new.id);
  if v_category is not null then
    update public.bank_transactions
       set category_id = v_category, category_source = 'rule'
     where id = new.id
       and coalesce(category_source, 'rule') <> 'human';
  end if;
  return null; -- ignored on an AFTER trigger
end $$;

CREATE OR REPLACE FUNCTION public.trg_fn_invoices_apply_rules_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.apply_assignment_rules(new.id, 'pipeline-intake');
  return new;
end $$;

CREATE OR REPLACE FUNCTION public.trg_fn_invoices_vat_deductible_default() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(new.vat_deductibility_source, 'ai') = 'ai' then
    new.vat_deductible_pct := public.resolve_default_vat_deductible_pct(new.property_id);
    new.vat_deductibility_source := case when new.vat_deductible_pct is null then null else 'ai' end;
  end if;
  return new;
end $$;

CREATE OR REPLACE FUNCTION public.update_datev_route_status(p_id uuid, p_is_enabled boolean, p_note text, p_updated_by text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_company uuid;
begin
  if auth.uid() is null then
    raise exception 'update_datev_route_status: authentication required' using errcode = 'insufficient_privilege';
  end if;
  if not public.may_write('rules.write') then
    raise exception 'update_datev_route_status: rules.write required' using errcode = 'insufficient_privilege';
  end if;

  select company_id into v_company from public.handover_routes where id = p_id;
  if v_company is null then
    raise exception 'update_datev_route_status: route % not found', p_id;
  end if;
  if not public.has_company_access(v_company) then
    raise exception 'update_datev_route_status: no access to this company' using errcode = 'insufficient_privilege';
  end if;

  update public.handover_routes
     set is_enabled = p_is_enabled, note = p_note, updated_by = p_updated_by, updated_at = now()
   where id = p_id;
end;
$$;

revoke execute on function public.update_datev_route_status(uuid, boolean, text, text) from public;
revoke execute on function public.update_datev_route_status(uuid, boolean, text, text) from anon;
grant execute on function public.update_datev_route_status(uuid, boolean, text, text) to authenticated;

CREATE OR REPLACE FUNCTION public.upsert_external_transactions(p_rows jsonb, p_account_id uuid DEFAULT NULL::uuid) RETURNS TABLE(inserted_count integer, updated_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_inserted int := 0;
  v_updated  int := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'upsert_external_transactions: p_rows must be a JSON array';
  end if;

  with incoming as (
    select
      r->>'source'              as source,
      r->>'external_id'         as external_id,
      (r->>'amount')::numeric   as amount,
      r->>'currency'            as currency,
      nullif(r->>'booking_date','')::date as booking_date,
      nullif(r->>'value_date','')::date   as value_date,
      r->>'booking_text'        as booking_text,
      r->>'payment_reference'   as payment_reference,
      r->>'counterparty_holder' as counterparty_holder,
      r->>'counterparty_iban'   as counterparty_iban,
      r->>'counterparty_bic'    as counterparty_bic,
      nullif(trim(coalesce(r->>'spender_name','')),'')  as spender_name,
      nullif(trim(coalesce(r->>'spender_email','')),'') as spender_email,
      nullif(r->>'pleo_tag_id','')::uuid     as pleo_tag_id,
      nullif(r->>'pleo_account_id','')::uuid as pleo_account_id,
      coalesce((r->>'is_sandbox')::boolean, false) as is_sandbox,
      r->>'transaction_type'    as transaction_type,
      coalesce(r->>'transaction_type_source','auto') as transaction_type_source,
      coalesce(r->'raw_data','{}'::jsonb) as raw_data,
      p_account_id as account_id
    from jsonb_array_elements(p_rows) as r
  ),
  deduped as (
    select distinct on (source, external_id) *
      from incoming
     where external_id is not null and source is not null
     order by source, external_id
  ),
  upserted as (
    insert into public.bank_transactions as bt (
      source, external_id, amount, currency, booking_date, value_date,
      booking_text, payment_reference, counterparty_holder, counterparty_iban, counterparty_bic,
      spender_name, spender_email, pleo_tag_id, pleo_account_id,
      is_sandbox, transaction_type, transaction_type_source, raw_data, account_id
    )
    select source, external_id, amount, currency, booking_date, value_date,
           booking_text, payment_reference, counterparty_holder, counterparty_iban, counterparty_bic,
           spender_name, spender_email, pleo_tag_id, pleo_account_id,
           is_sandbox, transaction_type, transaction_type_source, raw_data, account_id
      from deduped
    on conflict (source, external_id) do update set
      amount              = excluded.amount,
      currency            = excluded.currency,
      booking_date        = excluded.booking_date,
      value_date          = excluded.value_date,
      booking_text        = excluded.booking_text,
      payment_reference   = excluded.payment_reference,
      counterparty_holder = excluded.counterparty_holder,
      counterparty_iban   = excluded.counterparty_iban,
      counterparty_bic    = excluded.counterparty_bic,
      spender_name        = coalesce(excluded.spender_name, bt.spender_name),
      spender_email       = coalesce(excluded.spender_email, bt.spender_email),
      -- coalesce, like spender: a manual import carries neither, and plain assignment would wipe
      -- what the Pleo sync had already established for that same transaction.
      pleo_tag_id         = coalesce(excluded.pleo_tag_id, bt.pleo_tag_id),
      pleo_account_id     = coalesce(excluded.pleo_account_id, bt.pleo_account_id),
      is_sandbox          = excluded.is_sandbox,
      transaction_type    = excluded.transaction_type,
      account_id          = coalesce(excluded.account_id, bt.account_id),
      raw_data            = coalesce(bt.raw_data, '{}'::jsonb) || excluded.raw_data
    returning (xmax = 0) as was_insert
  )
  select count(*) filter (where was_insert), count(*) filter (where not was_insert)
    into v_inserted, v_updated
    from upserted;

  return query select v_inserted, v_updated;
end $$;

CREATE OR REPLACE FUNCTION public.vat_reserve(p_company uuid, p_von date DEFAULT NULL::date, p_bis date DEFAULT NULL::date) RETURNS TABLE(company_id uuid, von date, bis date, input_vat_total numeric, input_vat_deductible numeric, input_vat_nondeductible numeric, input_vat_unresolved_count bigint, input_vat_unresolved_amount numeric, output_vat numeric, reserve numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with input as (
    select
      round(coalesce(sum(i.vat_amount), 0), 2)                                            as vat_total,
      round(coalesce(sum(i.vat_deductible_amount), 0), 2)                                 as vat_deductible,
      round(coalesce(sum(i.vat_nondeductible_amount), 0), 2)                              as vat_nondeductible,
      count(*) filter (where i.vat_amount is not null and i.vat_deductible_pct is null)    as unresolved_count,
      round(coalesce(sum(i.vat_amount) filter (where i.vat_deductible_pct is null), 0), 2) as unresolved_amount
      from public.documents i
     where i.deleted_at is null
       and i.archived_at is null
       and i.company_id = p_company
       and (p_von is null or i.document_date >= p_von)
       and (p_bis is null or i.document_date <= p_bis)
  ),
  output as (
    select
      round(coalesce(sum(o.amount_gross - o.amount_net), 0), 2) as vat_total
      from public.outgoing_invoices o
     where o.deleted_at is null
       and o.company_id = p_company
       and o.status not in ('draft', 'voided')
       and o.amount_gross is not null
       and o.amount_net is not null
       and (p_von is null or o.invoice_date >= p_von)
       and (p_bis is null or o.invoice_date <= p_bis)
  )
  select
    p_company,
    p_von,
    p_bis,
    input.vat_total,
    input.vat_deductible,
    input.vat_nondeductible,
    input.unresolved_count,
    input.unresolved_amount,
    output.vat_total,
    output.vat_total - input.vat_deductible
    from input, output;
$$;

commit;

-- ===================================================================== 0012_views.sql

-- The views the screens read.
--
-- TWO RULES THIS FILE EXISTS TO HOLD.
--
-- 1. `security_invoker = true` on every single view. Without it a view runs as its owner for
--    permission purposes, so it reads straight past row level security and every scoped policy
--    underneath becomes decoration. A view added without this line is a data leak, not a style slip.
--
-- 2. No sentence a person reads is built here. A view returns the parts; the app composes the
--    words from its locale file. A German label inside SQL is a client's language compiled into
--    their database.

begin;

-- What a person sees in a list of documents: the row, who it is filed under for sorting, how badly
-- it needs attention, and whether the bank already agrees with it.
create or replace view public.v_documents_list with (security_invoker = true) as
select d.*,
       coalesce(s.name, d.issuer) as issuer_sort,
       -- Every failed check adds its own weight, and low confidence adds a little more. Both come
       -- from tables, so a client can reorder their own review list without a deploy.
       (
         coalesce((
           select sum(r.weight)
             from public.review_score_rules r
            where r.is_active
              and (r.applies_to_small_amounts or coalesce(d.is_small_amount, false) = false)
              and d.validation ->> r.check_key = 'false'
         ), 0)
         +
         coalesce((
           select case
                    when lowest is null then 0
                    when lowest < b.low_below then b.low_weight
                    when lowest < b.medium_below then b.medium_weight
                    else 0
                  end
             from public.review_confidence_bands b
             cross join lateral (
               select min(e.value::numeric) as lowest
                 from jsonb_each_text(coalesce(d.extracted -> b.confidence_key, '{}'::jsonb)) e
                where e.value ~ '^[0-9.]+$'
             ) c
         ), 0)
       )::integer as review_score,
       exists (
         select 1 from public.document_transaction_matches m
          where m.document_id = d.id and m.status in ('candidate', 'auto')
       ) as has_suggested_bank_match,
       exists (
         select 1 from public.document_transaction_matches m
          where m.document_id = d.id and m.status = 'confirmed'
       ) as has_confirmed_bank_match
  from public.documents d
  left join public.suppliers s on s.id = d.supplier_id
 where d.deleted_at is null
   -- A document that was split into its parts is represented by those parts, not by itself.
   and coalesce(d.status, '') <> 'split';

-- The same list with one lower-cased haystack column, so a plain text box can match what a person
-- typed without the caller assembling the same expression again.
--
-- Amounts are spelled several ways on purpose: somebody searching for 1.234,56 and somebody
-- searching for 1234.56 are looking for the same invoice, and which one they type depends on where
-- they grew up rather than on what the database stores.
create or replace view public.v_documents_search with (security_invoker = true) as
select l.*,
       lower(concat_ws(' ',
           l.issuer,
           l.invoice_number,
           l.service_description,
           l.cost_category,
           to_char(l.amount_gross, 'FM9999999990.00'),
           replace(to_char(l.amount_gross, 'FM9999999990.00'), '.', ','),
           to_char(l.amount_gross, 'FM9,999,999,990.00'),
           translate(to_char(l.amount_gross, 'FM9,999,999,990.00'), ',.', '.,')
       )) as search_text
  from public.v_documents_list l;

-- The same list, narrowed to what is actually waiting for a person.
--
-- Built on the SEARCH view rather than the list, so it carries search_text: the KPI and facet
-- functions count over exactly the rows a search would show, and a figure on the screen can never
-- disagree with the list beneath it.
create or replace view public.v_documents_review with (security_invoker = true) as
select *
  from public.v_documents_search
 where workflow_status in ('received', 'in_review', 'query')
    or review_score > 0
    or traffic_light in ('yellow', 'red');

-- What is still unpaid, and what stands in the way of paying it.
--
-- Covered is not the same as paid: a payment may land a little under the gross and still close the
-- invoice, which is what invoice_is_fully_covered() decides from the client's own tolerance.
create or replace view public.v_open_items with (security_invoker = true) as
select d.*,
       coalesce(m.matched_sum, 0) as matched_sum,
       public.invoice_is_fully_covered(
           public.amount_paid_out(d.amount_gross, d.tip_amount),
           case when d.paid_at is not null then abs(coalesce(public.amount_paid_out(d.amount_gross, d.tip_amount), 0))
                else coalesce(m.matched_sum, 0) end) as is_covered,
       -- One word naming what stops this being chased, for the app to translate. Null means nothing
       -- does, which is the normal case for something genuinely open.
       case
         when public.invoice_is_fully_covered(
                public.amount_paid_out(d.amount_gross, d.tip_amount),
                case when d.paid_at is not null then abs(coalesce(public.amount_paid_out(d.amount_gross, d.tip_amount), 0))
                     else coalesce(m.matched_sum, 0) end) then null
         when public.is_a_reminder(d.id) then 'reminder_letter'
         when coalesce(d.amount_gross, 0) = 0 then 'no_amount'
         when d.amount_gross < 0 then 'credit_note'
         when coalesce(d.already_paid, false) then 'paid_privately'
         else null
       end as open_blocker,
       -- The one flag the open items screen filters on.
       not public.invoice_is_fully_covered(
             public.amount_paid_out(d.amount_gross, d.tip_amount),
             case when d.paid_at is not null then abs(coalesce(public.amount_paid_out(d.amount_gross, d.tip_amount), 0))
                  else coalesce(m.matched_sum, 0) end)
         and coalesce(d.amount_gross, 0) > 0
         and coalesce(d.already_paid, false) = false
         and not public.is_a_reminder(d.id) as is_open
  from public.documents d
  left join (
        select document_id, sum(coalesce(amount_matched, 0)) as matched_sum
          from public.document_transaction_matches
         where status = 'confirmed'
         group by document_id
  ) m on m.document_id = d.id
 where d.deleted_at is null
   and d.archived_at is null
   and d.not_relevant_at is null
   and coalesce(d.status, '') <> 'split'
   and public.document_is_countable(d.status, d.private_hold);

-- Bank lines with the account and company they belong to, and whether a document claims them.
create or replace view public.v_bank_transactions_list with (security_invoker = true) as
select t.*,
       a.account_name,
       a.iban as account_iban,
       a.bank_name as account_bank_name,
       exists (
         select 1 from public.document_transaction_matches m
          where m.transaction_id = t.id and m.status in ('candidate', 'auto')
       ) as has_suggested_match,
       exists (
         select 1 from public.document_transaction_matches m
          where m.transaction_id = t.id and m.status = 'confirmed'
       ) as has_confirmed_match
  from public.bank_transactions t
  left join public.bank_accounts a on a.id = t.account_id
 where t.deleted_at is null;

-- Suppliers that look like the same company twice, by the two keys that actually identify one.
create or replace view public.v_supplier_duplicates with (security_invoker = true) as
with basis as (
    select id,
           name,
           nullif(btrim(lower(vat_id)), '') as vat_key,
           public.normalized_name(name) as name_key
      from public.suppliers
     where deleted_at is null
)
select 'vat_id' as key_type, vat_key as key_value, count(*) as n,
       array_agg(id order by name) as supplier_ids
  from basis
 where vat_key is not null
 group by vat_key
having count(*) > 1
union all
select 'name', name_key, count(*), array_agg(id order by name)
  from basis
 where name_key is not null
 group by name_key
having count(*) > 1;

-- Everything soft deleted, in one list, with the parts a screen needs to name each row. The wording
-- is the app's, which is why this returns values rather than a sentence.
create or replace view public.v_trash with (security_invoker = true) as
select 'documents' as table_name, d.id,
       jsonb_strip_nulls(jsonb_build_object(
           'issuer', nullif(btrim(d.issuer), ''),
           'reference', nullif(btrim(d.invoice_number), ''),
           'date', d.document_date,
           'amount', d.amount_gross,
           'currency', nullif(d.currency, ''))) as parts,
       d.deleted_at, d.deleted_by, d.delete_reason
  from public.documents d where d.deleted_at is not null
union all
select 'suppliers', s.id,
       jsonb_strip_nulls(jsonb_build_object('name', nullif(btrim(s.name), ''))),
       s.deleted_at, s.deleted_by, s.delete_reason
  from public.suppliers s where s.deleted_at is not null
union all
select 'companies', c.id,
       jsonb_strip_nulls(jsonb_build_object('name', nullif(btrim(c.name), ''), 'code', c.code)),
       c.deleted_at, c.deleted_by, c.delete_reason
  from public.companies c where c.deleted_at is not null
union all
select 'properties', p.id,
       jsonb_strip_nulls(jsonb_build_object('name', nullif(btrim(p.name), ''), 'code', p.code)),
       p.deleted_at, p.deleted_by, p.delete_reason
  from public.properties p where p.deleted_at is not null
union all
select 'customers', cu.id,
       jsonb_strip_nulls(jsonb_build_object('name', nullif(btrim(cu.name), ''))),
       cu.deleted_at, cu.deleted_by, cu.delete_reason
  from public.customers cu where cu.deleted_at is not null;

-- Totals, counted the same way everywhere so two screens can never disagree.
create or replace view public.v_company_document_totals with (security_invoker = true) as
select company_id, count(*) as document_count, coalesce(sum(amount_gross), 0) as document_total
  from public.documents
 where company_id is not null and deleted_at is null and archived_at is null
   and not_relevant_at is null and coalesce(status, '') <> 'split'
 group by company_id;

create or replace view public.v_property_document_totals with (security_invoker = true) as
select property_id, count(*) as document_count, coalesce(sum(amount_gross), 0) as document_total
  from public.documents
 where property_id is not null and deleted_at is null and archived_at is null
   and not_relevant_at is null and coalesce(status, '') <> 'split'
 group by property_id;

create or replace view public.v_supplier_document_totals with (security_invoker = true) as
select supplier_id, count(*) as document_count, coalesce(sum(amount_gross), 0) as document_total,
       max(document_date) as last_document_date,
       -- How often this supplier invoices, in days. Null until there are two dated documents to
       -- measure between.
       case
         when count(*) filter (where document_date is not null) >= 2
           then round((max(document_date) - min(document_date))::numeric
                      / (count(*) filter (where document_date is not null) - 1))::integer
         else null
       end as avg_days_between
  from public.documents
 where supplier_id is not null and deleted_at is null and archived_at is null
   and not_relevant_at is null and coalesce(status, '') <> 'split'
 group by supplier_id;

create or replace view public.v_customer_invoice_totals with (security_invoker = true) as
select customer_id,
       count(*) as invoice_count,
       coalesce(sum(amount_gross), 0) as invoice_total,
       count(*) filter (where status = 'overdue') as overdue_count
  from public.outgoing_invoices
 where customer_id is not null and deleted_at is null
 group by customer_id;


commit;

-- ===================================================================== 0013_scheduled_jobs.sql

-- What runs on a timer, per client.
--
-- WHY THIS IS A TABLE. Every Hub schedules a different set: one runs three jobs, another eight,
-- two run none at all. Writing them into the schema would make the schema client-specific, which is
-- the fork this template exists to prevent. So the jobs are rows: a client turns one on, changes
-- when it runs, and nothing is deployed.
--
-- NO HOST IS EVER WRITTEN DOWN. A job posts to this project's own Edge Functions, and the project's
-- URL and service key come from the vault at run time. A literal host is how a clone ends up calling
-- another client's project, which is exactly what happened in the Hub this template came from.
--
-- Everything ships OFF. A clone that is not finished being set up must not start calling out.

begin;

-- pg_cron may only be installed in the database called postgres, which is what a real Supabase
-- project is. A scratch database used for testing the schema is not, so this must not abort there:
-- the table and the functions still install, and scheduling simply has nothing to talk to.
do $$
begin
  create extension if not exists pg_cron;
exception when others then
  raise notice 'pg_cron is unavailable here, so nothing will be scheduled: %', sqlerrm;
end
$$;

create extension if not exists pg_net;

create table if not exists public.scheduled_jobs (
    key text primary key,
    -- Which Edge Function to post to. Never a URL: the host is resolved at run time.
    edge_function text not null,
    -- Standard five-field cron. Checked when it is applied, not here, because Postgres has no
    -- opinion about cron syntax and a wrong line should fail loudly at the moment somebody sets it.
    schedule text not null,
    enabled boolean not null default false,
    description text,
    -- What happened last time, so a client can see a job failing without reading a server log.
    last_run_at timestamptz,
    last_status text,
    last_message text,
    updated_at timestamptz not null default now(),
    updated_by text
);

comment on table public.scheduled_jobs is
    'What this client runs on a timer. Rows, not migrations, because every client differs.';

alter table public.scheduled_jobs enable row level security;

drop policy if exists scheduled_jobs_read on public.scheduled_jobs;
create policy scheduled_jobs_read on public.scheduled_jobs for select to authenticated
    using (public.may_read('settings.manage'));

drop policy if exists scheduled_jobs_write on public.scheduled_jobs;
create policy scheduled_jobs_write on public.scheduled_jobs for all to authenticated
    using (public.may_write('settings.manage')) with check (public.may_write('settings.manage'));

-- This project's own address and key, from the vault. Null when the deployment has not been given
-- them yet, which is a normal state for a clone nobody has finished setting up.
create or replace function public.deployment_secret(p_name text) returns text
language plpgsql stable security definer set search_path to 'public'
as $$
declare
  v_value text;
begin
  begin
    select decrypted_secret into v_value from vault.decrypted_secrets where name = p_name;
  exception when others then
    -- The vault extension may not be enabled at all. A missing secret is not an error here: the
    -- caller decides what to do without one, and every caller here decides to skip.
    v_value := null;
  end;
  return nullif(v_value, '');
end;
$$;

-- The body every scheduled job runs: post to one of this project's own Edge Functions, and write
-- down what happened. One function, so a new job is a row rather than another copy of this.
create or replace function public.run_scheduled_job(p_key text) returns void
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_job public.scheduled_jobs;
  v_url text := public.deployment_secret('project_url');
  v_key text := public.deployment_secret('service_role_key');
begin
  select * into v_job from public.scheduled_jobs where key = p_key and enabled;
  if not found then
    return;
  end if;

  if v_url is null or v_key is null then
    update public.scheduled_jobs
       set last_run_at = now(), last_status = 'skipped',
           last_message = 'project_url or service_role_key is missing from the vault'
     where key = p_key;
    return;
  end if;

  perform net.http_post(
    url := rtrim(v_url, '/') || '/functions/v1/' || v_job.edge_function,
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'Authorization', 'Bearer ' || v_key),
    body := '{}'::jsonb,
    timeout_milliseconds := 60000);

  update public.scheduled_jobs
     set last_run_at = now(), last_status = 'sent', last_message = null
   where key = p_key;
end;
$$;

-- Makes pg_cron agree with the table: every enabled row is scheduled with its own line, every
-- disabled or deleted row is unscheduled. Run after any change; the trigger below does it for you.
create or replace function public.apply_scheduled_jobs() returns void
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_job public.scheduled_jobs;
  v_existing text;
begin
  -- Without pg_cron there is nothing to keep in agreement. Saying so once is better than failing
  -- every write to the table.
  if to_regclass('cron.job') is null then
    raise notice 'pg_cron is not installed, so no job was scheduled';
    return;
  end if;

  for v_existing in
    select jobname from cron.job where jobname like 'hub:%'
  loop
    if not exists (
      select 1 from public.scheduled_jobs j
       where j.enabled and 'hub:' || j.key = v_existing
    ) then
      perform cron.unschedule(v_existing);
    end if;
  end loop;

  for v_job in select * from public.scheduled_jobs where enabled loop
    if exists (select 1 from cron.job where jobname = 'hub:' || v_job.key) then
      perform cron.unschedule('hub:' || v_job.key);
    end if;
    perform cron.schedule('hub:' || v_job.key, v_job.schedule,
                          format('select public.run_scheduled_job(%L)', v_job.key));
  end loop;
end;
$$;

create or replace function public.scheduled_jobs_apply() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  perform public.apply_scheduled_jobs();
  return null;
end;
$$;

drop trigger if exists scheduled_jobs_apply on public.scheduled_jobs;
create trigger scheduled_jobs_apply after insert or update or delete on public.scheduled_jobs
    for each statement execute function public.scheduled_jobs_apply();

revoke execute on function public.deployment_secret(text) from public, anon, authenticated;
revoke execute on function public.run_scheduled_job(text) from public, anon, authenticated;
revoke execute on function public.apply_scheduled_jobs() from public, anon;
grant execute on function public.apply_scheduled_jobs() to authenticated;

commit;

-- ===================================================================== 0014_triggers.sql

-- What the database does by itself.
--
-- Ported from the Hub this template came from: every trigger that was live there, in its last
-- definition, because several were dropped and recreated over time and only the last one is true.
--
-- These are behaviour, not decoration. Without them a Hub looks right and quietly stops advancing
-- a workflow when a payment lands, stops recording that a supplier's IBAN changed, and stops
-- refusing a write somebody is not allowed to make.
--
-- They come after the functions they execute and after the tables they sit on.

