-- ===================================================================== 0015_server_permissions.sql

-- Whether a named person may do a named thing, for callers that have no session.
--
-- The server routes run on the service-role key, which bypasses row level security entirely, so
-- has_permission() cannot help them: it resolves the caller from auth.jwt(), and there is no JWT.
--
-- Rewriting that rule in TypeScript is how the two drift. This asks the same question with the
-- person named explicitly, and resolves it through live_features() like everything else, so a
-- feature the client has switched off is refused on the server too.

begin;

create or replace function public.person_may(p_email text, p_capability text) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  with person as (
    select u.id, u.role_id, r.protected, r.administers
      from public.app_users u
      left join public.roles r on r.id = u.role_id
     where lower(u.email) = lower(coalesce(p_email, ''))
       and u.is_active
     limit 1
  ),
  live as (select key from public.live_features())
  select coalesce((
    select case
      -- The break-glass account keeps everything the client uses. It still cannot use a feature
      -- that is switched off, because that is not a rights question.
      when p.protected then p_capability in (select key from live)
      when p.administers and p_capability in (select key from live) then true
      else coalesce(
        (select up.granted
           from public.user_permissions up
          where up.user_id = p.id and up.permission_key = p_capability),
        exists (
          select 1 from public.role_permissions rp
           where rp.role_id = p.role_id and rp.permission_key = p_capability
        )
      ) and p_capability in (select key from live)
    end
    from person p
  ), false);
$$;

revoke execute on function public.person_may(text, text) from public, anon;
grant execute on function public.person_may(text, text) to authenticated, service_role;

commit;

-- ===================================================================== 0016_pipeline_ledger.sql

-- What the ingestion pipeline's provisioning would have recorded, had it built this database.
--
-- The pipeline keeps a ledger of the setup steps it has applied, and the admin panel reads it to
-- decide whether a client's database is ready. A database built from this schema has every table
-- and column those steps create, but no ledger saying so, and the panel then treats a finished
-- database as an unfinished one: it refuses to read the stored credentials, and every source
-- reports that it still needs something.
--
-- So the steps are recorded here, by the ids the pipeline uses. The claim is only honest because
-- scripts/db/check-pipeline-columns.mjs holds this schema to the pipeline's own column list; if that
-- check ever fails, this file is asserting something untrue and the failure is the warning.

begin;

create table if not exists public.schema_migrations (
    id text primary key check (length(btrim(id)) > 0),
    applied_at timestamptz not null default now()
);

alter table public.schema_migrations enable row level security;

insert into public.schema_migrations (id) values
  ('0001_tenant_settings'),
  ('0002_channels'),
  ('0003_master_data'),
  ('0004_documents'),
  ('0005_credentials')
on conflict (id) do nothing;

commit;

-- ===================================================================== 0017_broker_commissions.sql

-- A broker enters their own commissions, and an administrator reviews and approves them.
--
-- Everything here is inert until a role holds `deals.submit`, which no role does by default: the
-- permission is off in the catalogue, and a policy that asks for it denies everyone who lacks it.
-- Re-runnable, so the same file builds a new database and upgrades one that already exists.
--
-- A person holding `deals.submit` may create a deal on a property the CRM says is theirs, and edit it
-- while it is incomplete or ready. They may not approve it, change what it is about to somebody
-- else's property, or touch it once it is approved: approving is `documents.write`, as before.

begin;

-- Who created a customer, so a person can read back the customers they entered and nobody else's.
alter table public.customers
    add column if not exists created_by uuid references public.app_users(id)
        default public.current_app_user_id();

create or replace function public.is_own_property(p_property_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select exists (
    select 1 from public.properties p
     where p.id = p_property_id
       and p.deleted_at is null
       and p.broker_external_id is not null
       and p.broker_external_id = public.current_crm_external_id()
  );
$$;

create or replace function public.may_edit_own_deal(p_deal_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select public.has_permission('deals.submit')
     and exists (
       select 1 from public.deals d
        where d.id = p_deal_id
          and d.deleted_at is null
          and d.status in ('incomplete', 'ready')
          and public.owns_deal(d.id)
     );
$$;

create or replace function public.may_edit_own_deal_side(p_side_id uuid) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select exists (select 1 from public.deal_sides s
                  where s.id = p_side_id and public.may_edit_own_deal(s.deal_id));
$$;

revoke execute on function public.is_own_property(uuid) from public, anon;
revoke execute on function public.may_edit_own_deal(uuid) from public, anon;
revoke execute on function public.may_edit_own_deal_side(uuid) from public, anon;
grant execute on function public.is_own_property(uuid) to authenticated;
grant execute on function public.may_edit_own_deal(uuid) to authenticated;
grant execute on function public.may_edit_own_deal_side(uuid) to authenticated;

drop policy if exists deals_submit_insert on public.deals;
create policy deals_submit_insert on public.deals for insert to authenticated
    with check (public.has_permission('deals.submit')
                and public.is_own_property(property_id)
                and status = 'incomplete'
                and approved_by is null and approved_at is null
                and deleted_at is null);

-- Read from the row's own property, not through a function that looks the deal up again: a row being
-- inserted cannot be seen by a second query in the same statement, so the insert would be refused
-- when it tries to hand the new row back.
drop policy if exists deals_submit_read on public.deals;
create policy deals_submit_read on public.deals for select to authenticated
    using (public.has_permission('deals.submit') and public.is_own_property(property_id));

drop policy if exists deals_submit_update on public.deals;
create policy deals_submit_update on public.deals for update to authenticated
    using (public.may_edit_own_deal(id))
    with check (public.has_permission('deals.submit')
                and public.is_own_property(property_id)
                and status in ('incomplete', 'ready')
                and approved_by is null and approved_at is null
                and deleted_at is null);

drop policy if exists deal_sides_submit on public.deal_sides;
create policy deal_sides_submit on public.deal_sides for all to authenticated
    using (public.may_edit_own_deal(deal_id))
    with check (public.may_edit_own_deal(deal_id));

-- A payer must be a customer the person can themselves see, so somebody else's customer cannot be
-- attached by knowing its id.
drop policy if exists deal_parties_submit on public.deal_parties;
create policy deal_parties_submit on public.deal_parties for all to authenticated
    using (public.may_edit_own_deal_side(deal_side_id))
    with check (public.may_edit_own_deal_side(deal_side_id)
                and exists (select 1 from public.customers c where c.id = customer_id));

drop policy if exists customers_submit_insert on public.customers;
create policy customers_submit_insert on public.customers for insert to authenticated
    with check (public.has_permission('deals.submit')
                and source = 'app'
                and created_by = public.current_app_user_id());

drop policy if exists customers_submit_read on public.customers;
create policy customers_submit_read on public.customers for select to authenticated
    using (public.has_permission('deals.submit')
           and created_by = public.current_app_user_id());

commit;

-- ===================================================================== 0018_broker_bonuses.sql

-- A broker's bonus claims, entered by the broker and approved by an administrator.
--
-- Inert until a role holds `bonuses.submit` or `bonuses.review`, which no role does by default.
-- Re-runnable, so the same file builds a new database and upgrades one that already exists.

begin;

create table if not exists public.broker_bonuses (
    id uuid primary key default gen_random_uuid(),
    broker_user_id uuid not null references public.app_users(id) default public.current_app_user_id(),
    bonus_type text not null,
    earned_on date not null,
    amount numeric(12, 2) not null,
    property_id uuid references public.properties(id),
    note text,
    status text not null default 'submitted',
    reviewed_by uuid references public.app_users(id),
    reviewed_at timestamptz,
    review_note text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint broker_bonuses_type_known check (bonus_type in (
        'notary', 'google_review', 'viewing_new_job', 'company_lead_share',
        'own_job_share', 'financing_referral', 'other')),
    constraint broker_bonuses_status_known check (status in ('submitted', 'approved', 'rejected', 'paid')),
    constraint broker_bonuses_amount_positive check (amount > 0),
    constraint broker_bonuses_review_complete check ((reviewed_by is null) = (reviewed_at is null))
);

update public.broker_bonuses set note = left(note, 500) where char_length(note) > 500;
update public.broker_bonuses set review_note = left(review_note, 500) where char_length(review_note) > 500;

alter table public.broker_bonuses drop constraint if exists broker_bonuses_notes_short;
alter table public.broker_bonuses add constraint broker_bonuses_notes_short
    check (char_length(note) <= 500 and char_length(review_note) <= 500);

create index if not exists broker_bonuses_broker on public.broker_bonuses (broker_user_id, earned_on desc);
create index if not exists broker_bonuses_status on public.broker_bonuses (status);

drop trigger if exists broker_bonuses_touch on public.broker_bonuses;
create trigger broker_bonuses_touch before update on public.broker_bonuses
    for each row execute function public.set_updated_at();

create or replace function public.stamp_bonus_review() returns trigger
language plpgsql set search_path to 'public'
as $$
begin
  if new.status <> old.status and new.status <> 'submitted' then
    new.reviewed_by := public.current_app_user_id();
    new.reviewed_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists broker_bonuses_stamp_review on public.broker_bonuses;
create trigger broker_bonuses_stamp_review before update on public.broker_bonuses
    for each row execute function public.stamp_bonus_review();

alter table public.broker_bonuses enable row level security;

drop policy if exists broker_bonuses_review on public.broker_bonuses;
create policy broker_bonuses_review on public.broker_bonuses for all to authenticated
    using (public.has_permission('bonuses.review'))
    with check (public.has_permission('bonuses.review'));

drop policy if exists broker_bonuses_approved_read on public.broker_bonuses;
create policy broker_bonuses_approved_read on public.broker_bonuses for select to authenticated
    using (public.has_permission('bonuses.read') and status in ('approved', 'paid'));

drop policy if exists broker_bonuses_own_read on public.broker_bonuses;
create policy broker_bonuses_own_read on public.broker_bonuses for select to authenticated
    using (public.has_permission('bonuses.submit') and broker_user_id = public.current_app_user_id());

drop policy if exists broker_bonuses_own_insert on public.broker_bonuses;
create policy broker_bonuses_own_insert on public.broker_bonuses for insert to authenticated
    with check (public.has_permission('bonuses.submit')
                and broker_user_id = public.current_app_user_id()
                and status = 'submitted'
                and reviewed_by is null and reviewed_at is null);

drop policy if exists broker_bonuses_own_update on public.broker_bonuses;
create policy broker_bonuses_own_update on public.broker_bonuses for update to authenticated
    using (public.has_permission('bonuses.submit')
           and broker_user_id = public.current_app_user_id() and status = 'submitted')
    with check (public.has_permission('bonuses.submit')
                and broker_user_id = public.current_app_user_id() and status = 'submitted'
                and reviewed_by is null and reviewed_at is null);

drop policy if exists broker_bonuses_own_delete on public.broker_bonuses;
create policy broker_bonuses_own_delete on public.broker_bonuses for delete to authenticated
    using (public.has_permission('bonuses.submit')
           and broker_user_id = public.current_app_user_id() and status = 'submitted');

grant select, insert, update, delete on public.broker_bonuses to authenticated;

create or replace function public.notify_bonus_submitted() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  perform public.notify_administrators(
    'Neuer Bonus zur Prüfung: ' || public.bonus_type_label(new.bonus_type) || ', '
      || replace(to_char(new.amount, 'FM999999990.00'), '.', ',') || ' €',
    '/broker-bonuses', 'bonus', new.broker_user_id,
    coalesce((select coalesce(name, email) from public.app_users where id = new.broker_user_id), 'Hub'));
  return new;
end;
$$;

drop trigger if exists broker_bonuses_notify_submitted on public.broker_bonuses;
create trigger broker_bonuses_notify_submitted after insert on public.broker_bonuses
    for each row execute function public.notify_bonus_submitted();

commit;

-- ===================================================================== 0019_deals_from_crm.sql

-- A property the CRM marks as sold opens a deal, for the broker to complete and an administrator to approve.
--
-- Runs after each CRM sync. Inert until `deals.from_crm` is switched on. The CRM's own sold date is
-- usually empty, so what counts is the moment the sync saw the status become sold, and only a change seen
-- after the switch opens a deal: the CRM's history never becomes a pile of deals. Re-runnable.

begin;

alter table public.properties add column if not exists became_sold_at timestamptz;

create or replace function public.stamp_became_sold() returns trigger
language plpgsql set search_path to 'public'
as $$
begin
  if new.crm_status = 'Verkauft' and old.crm_status is distinct from 'Verkauft' then
    new.became_sold_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists properties_stamp_became_sold on public.properties;
create trigger properties_stamp_became_sold before update of crm_status on public.properties
    for each row execute function public.stamp_became_sold();

create or replace function public.crm_rate(p_text text) returns numeric
language sql immutable
as $$ select case when p_text ~ '^[0-9]+(\.[0-9]+)?$' then p_text::numeric end $$;

create or replace function public.crm_net_rate(p_rate numeric, p_vat_rate numeric) returns numeric
language sql immutable
as $$
  select case
    when p_rate is null or p_rate <= 0 then null
    when abs(p_rate / (1 + p_vat_rate / 100) * 2 - round(p_rate / (1 + p_vat_rate / 100) * 2)) < 0.002
      then round(p_rate / (1 + p_vat_rate / 100) * 2) / 2
    else p_rate
  end
$$;

create or replace function public.create_deals_for_sold_properties(p_sold_status text default 'Verkauft')
returns integer
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_switched_on timestamptz;
  v_created integer := 0;
  v_deal record;
begin
  if not exists (select 1 from public.live_features() f where f.key = 'deals.from_crm') then
    return 0;
  end if;

  select updated_at into v_switched_on
    from public.feature_settings where feature_key = 'deals.from_crm' and enabled;
  if v_switched_on is null then
    return 0;
  end if;

  for v_deal in
    with opened as (
      insert into public.deals (
          company_id, property_id, property_label, source, external_id, status,
          notarised_on, purchase_price, acquired_by, handled_by, created_by)
      select (select c.id from public.companies c where c.deleted_at is null order by c.created_at limit 1),
             p.id,
             concat_ws(', ', coalesce(p.name, p.code), p.address),
             p.source, p.external_id, 'incomplete',
             p.sold_on, nullif(p.sold_price, 0),
             b.id, b.id, 'crm'
        from public.properties p
        left join public.app_users b
               on b.crm_external_id = p.broker_external_id and b.is_active
       where p.deleted_at is null
         and p.crm_status = p_sold_status
         and p.became_sold_at >= v_switched_on
         and p.external_id is not null
      on conflict (source, external_id) where external_id is not null do nothing
      returning id, property_id, property_label, acquired_by
    )
    select * from opened
  loop
    v_created := v_created + 1;

    insert into public.deal_sides (deal_id, side, fee_kind, fee_net_rate)
    select v_deal.id, side.name, 'percent',
           public.crm_net_rate(side.gross_rate, d.vat_rate)
      from public.deals d
      join public.properties p on p.id = v_deal.property_id
      cross join lateral (values
        ('buyer',  public.crm_rate(p.crm_data ->> 'external_commission_percentage')),
        ('seller', public.crm_rate(p.crm_data ->> 'internal_commission_percentage'))
      ) as side(name, gross_rate)
     where d.id = v_deal.id;

    update public.deals
       set note = 'Provisionssätze aus dem CRM übernommen (Bruttosätze auf netto umgerechnet). Bitte prüfen.'
     where id = v_deal.id;

    perform public.notify_administrators(
      'Verkauft im CRM: ' || coalesce(v_deal.property_label, 'Objekt')
        || '. Die Provision wartet auf Vervollständigung.',
      '/commission-deals/' || v_deal.id, 'crm', v_deal.acquired_by);
    if v_deal.acquired_by is not null then
      perform public.send_system_ping(
        v_deal.acquired_by, 'Hub',
        'Verkauft im CRM: ' || coalesce(v_deal.property_label, 'Objekt')
          || '. Die Provision wartet auf Vervollständigung.',
        '/commission-deals/' || v_deal.id, 'crm');
    end if;
  end loop;

  return v_created;
end;
$$;

revoke execute on function public.create_deals_for_sold_properties(text) from public, anon, authenticated;
grant execute on function public.create_deals_for_sold_properties(text) to service_role;

commit;

-- ===================================================================== 0020_system_notifications.sql

-- The Hub tells people when something needs them: a deal waiting for approval, a decision on a deal
-- or a bonus, a sync that stopped working. Each is a bell entry (a `ping` event), written here and
-- nowhere in the screens. Re-runnable.

begin;

create or replace function public.administrator_ids() returns setof uuid
language sql stable security definer set search_path to 'public'
as $$
  select u.id
    from public.app_users u
    join public.roles r on r.id = u.role_id
   where u.is_active and r.administers;
$$;

create or replace function public.send_system_ping(
    p_recipient uuid, p_from text, p_note text, p_path text, p_source text)
returns void
language sql security definer set search_path to 'public'
as $$
  insert into public.notification_events (type, payload, recipient_user_id, created_by)
  values ('ping',
          jsonb_build_object(
            'from_name', p_from,
            'note', p_note,
            'target', jsonb_build_object('kind', 'page', 'path', p_path)),
          p_recipient, p_source);
$$;

create or replace function public.notify_administrators(
    p_note text, p_path text, p_source text, p_except uuid default null, p_from text default 'Hub')
returns integer
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_recipient uuid;
  v_sent integer := 0;
begin
  for v_recipient in select public.administrator_ids() loop
    if v_recipient is distinct from p_except then
      perform public.send_system_ping(v_recipient, p_from, p_note, p_path, p_source);
      v_sent := v_sent + 1;
    end if;
  end loop;
  return v_sent;
end;
$$;

revoke execute on function public.administrator_ids() from public, anon, authenticated;
revoke execute on function public.send_system_ping(uuid, text, text, text, text) from public, anon, authenticated;
revoke execute on function public.notify_administrators(text, text, text, uuid, text) from public, anon, authenticated;
grant execute on function public.notify_administrators(text, text, text, uuid, text) to service_role;

create or replace function public.notify_deal_status_changed() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_actor_name text;
  v_label text := coalesce(new.property_label, 'Verkauf');
  v_owner uuid := coalesce(new.acquired_by, new.handled_by);
begin
  select coalesce(name, email) into v_actor_name from public.app_users where id = v_actor;
  v_actor_name := coalesce(v_actor_name, 'Hub');

  if new.status = 'ready' then
    perform public.notify_administrators(
      'Provision zur Freigabe: ' || v_label, '/commission-deals/' || new.id, 'deal', v_actor, v_actor_name);
  elsif new.status = 'approved' and v_owner is not null and v_owner is distinct from v_actor then
    perform public.send_system_ping(
      v_owner, v_actor_name, 'Provision freigegeben: ' || v_label, '/commission-deals/' || new.id, 'deal');
  end if;
  return null;
end;
$$;

drop trigger if exists deals_notify_status_changed on public.deals;
create trigger deals_notify_status_changed after update of status on public.deals
    for each row when (old.status is distinct from new.status)
    execute function public.notify_deal_status_changed();

create or replace function public.bonus_type_label(p_type text) returns text
language sql immutable
as $$
  select case p_type
    when 'notary' then 'Notarbonus'
    when 'google_review' then 'Google-Bewertung'
    when 'viewing_new_job' then 'Neuer Auftrag aus Besichtigung'
    when 'company_lead_share' then '10 % Anteil (Firmenlead)'
    when 'own_job_share' then '50 % Anteil (eigener Auftrag)'
    when 'financing_referral' then 'Empfehlung Finanzierung'
    else 'Sonstiges' end
$$;

create or replace function public.notify_bonus_decided() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_actor_name text;
  v_what text;
begin
  if new.broker_user_id is not distinct from v_actor then
    return null;
  end if;
  select coalesce(name, email) into v_actor_name from public.app_users where id = v_actor;

  v_what := public.bonus_type_label(new.bonus_type) || ', '
            || replace(to_char(new.amount, 'FM999999990.00'), '.', ',') || ' €';
  perform public.send_system_ping(
    new.broker_user_id,
    coalesce(v_actor_name, 'Hub'),
    case new.status
      when 'approved' then 'Bonus freigegeben: ' || v_what
      when 'rejected' then 'Bonus abgelehnt: ' || v_what
                           || coalesce(' (' || nullif(btrim(new.review_note), '') || ')', '')
      else 'Bonus ausgezahlt: ' || v_what end,
    '/broker-bonuses', 'bonus');
  return null;
end;
$$;

drop trigger if exists broker_bonuses_notify_decided on public.broker_bonuses;
create trigger broker_bonuses_notify_decided after update of status on public.broker_bonuses
    for each row when (old.status is distinct from new.status and new.status in ('approved', 'rejected', 'paid'))
    execute function public.notify_bonus_decided();

commit;

-- ===================================================================== 0021_deal_costs.sql

-- What the agency paid out of its own pocket for one sale: city fees, photos, the energy certificate,
-- a voucher. A broker's bonus is worked out on the fee less these. Re-runnable.

begin;

create table if not exists public.deal_costs (
    id uuid primary key default gen_random_uuid(),
    deal_id uuid not null references public.deals(id) on delete cascade,
    kind text not null,
    description text,
    amount numeric(14, 2) not null,
    incurred_on date,
    created_at timestamptz not null default now(),
    constraint deal_costs_kind_known
        check (kind in ('city_fee', 'photos', 'energy_certificate', 'voucher', 'other')),
    constraint deal_costs_amount_positive check (amount > 0)
);

create index if not exists deal_costs_deal on public.deal_costs (deal_id);

alter table public.deal_costs enable row level security;

drop policy if exists deal_costs_read on public.deal_costs;
create policy deal_costs_read on public.deal_costs for select to authenticated
    using (public.may_read('documents.read'));

drop policy if exists deal_costs_write on public.deal_costs;
create policy deal_costs_write on public.deal_costs for all to authenticated
    using (public.may_write('documents.write'))
    with check (public.may_write('documents.write'));

drop policy if exists deal_costs_own_read on public.deal_costs;
create policy deal_costs_own_read on public.deal_costs for select to authenticated
    using (public.owns_deal(deal_id));

drop policy if exists deal_costs_submit on public.deal_costs;
create policy deal_costs_submit on public.deal_costs for all to authenticated
    using (public.may_edit_own_deal(deal_id))
    with check (public.may_edit_own_deal(deal_id));

commit;

-- ===================================================================== 0022_bonus_suggestions.sql

-- Bonuses worked out from a sale. An administrator creates the suggestion from the deal, the broker
-- confirms it, and the usual review follows. Inert until a role holds `bonuses.suggest`, which no
-- role does by default. Re-runnable.

begin;

alter table public.broker_bonuses add column if not exists deal_id uuid references public.deals(id);

alter table public.broker_bonuses drop constraint if exists broker_bonuses_status_known;
alter table public.broker_bonuses add constraint broker_bonuses_status_known
    check (status in ('suggested', 'submitted', 'approved', 'rejected', 'paid'));

create unique index if not exists broker_bonuses_one_per_deal_and_type
    on public.broker_bonuses (deal_id, bonus_type)
    where deal_id is not null and status <> 'rejected';

create table if not exists public.bonus_settings (
    single_row boolean primary key default true check (single_row),
    notary_amount numeric(12, 2) not null default 500 check (notary_amount > 0),
    follow_up_amount numeric(12, 2) not null default 500 check (follow_up_amount > 0),
    own_lead_share_percent numeric(5, 2) not null default 50 check (own_lead_share_percent > 0 and own_lead_share_percent <= 100),
    company_lead_share_percent numeric(5, 2) not null default 10 check (company_lead_share_percent > 0 and company_lead_share_percent <= 100),
    personnel_flat_amount numeric(12, 2) not null default 1500 check (personnel_flat_amount >= 0),
    company_lead_deducts_costs boolean not null default true,
    updated_at timestamptz not null default now()
);

insert into public.bonus_settings (single_row) values (true) on conflict do nothing;

drop trigger if exists bonus_settings_touch on public.bonus_settings;
create trigger bonus_settings_touch before update on public.bonus_settings
    for each row execute function public.set_updated_at();

alter table public.bonus_settings enable row level security;

drop policy if exists bonus_settings_read on public.bonus_settings;
create policy bonus_settings_read on public.bonus_settings for select to authenticated
    using (public.has_permission('bonuses.review') or public.has_permission('bonuses.submit'));

drop policy if exists bonus_settings_write on public.bonus_settings;
create policy bonus_settings_write on public.bonus_settings for update to authenticated
    using (public.has_permission('bonuses.review'))
    with check (public.has_permission('bonuses.review'));

grant select, update on public.bonus_settings to authenticated;

drop policy if exists broker_bonuses_own_confirm on public.broker_bonuses;
create policy broker_bonuses_own_confirm on public.broker_bonuses for update to authenticated
    using (public.has_permission('bonuses.submit')
           and broker_user_id = public.current_app_user_id() and status = 'suggested')
    with check (public.has_permission('bonuses.submit')
                and broker_user_id = public.current_app_user_id() and status = 'submitted'
                and reviewed_by is null and reviewed_at is null);

drop policy if exists broker_bonuses_own_decline on public.broker_bonuses;
create policy broker_bonuses_own_decline on public.broker_bonuses for delete to authenticated
    using (public.has_permission('bonuses.submit')
           and broker_user_id = public.current_app_user_id() and status = 'suggested');

create or replace function public.notify_bonus_submitted() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  perform public.notify_administrators(
    'Neuer Bonus zur Prüfung: ' || public.bonus_type_label(new.bonus_type) || ', '
      || replace(to_char(new.amount, 'FM999999990.00'), '.', ',') || ' €',
    '/broker-bonuses', 'bonus', new.broker_user_id,
    coalesce((select coalesce(name, email) from public.app_users where id = new.broker_user_id), 'Hub'));
  return null;
end;
$$;

drop trigger if exists broker_bonuses_notify_submitted on public.broker_bonuses;
create trigger broker_bonuses_notify_submitted after insert on public.broker_bonuses
    for each row when (new.status = 'submitted')
    execute function public.notify_bonus_submitted();

drop trigger if exists broker_bonuses_notify_confirmed on public.broker_bonuses;
create trigger broker_bonuses_notify_confirmed after update of status on public.broker_bonuses
    for each row when (old.status = 'suggested' and new.status = 'submitted')
    execute function public.notify_bonus_submitted();

create or replace function public.notify_bonus_suggested() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  if new.broker_user_id is distinct from public.current_app_user_id() then
    perform public.send_system_ping(
      new.broker_user_id, 'Hub',
      'Bonus zur Bestätigung: ' || public.bonus_type_label(new.bonus_type) || ', '
        || replace(to_char(new.amount, 'FM999999990.00'), '.', ',') || ' €',
      '/broker-bonuses', 'bonus');
  end if;
  return null;
end;
$$;

drop trigger if exists broker_bonuses_notify_suggested on public.broker_bonuses;
create trigger broker_bonuses_notify_suggested after insert on public.broker_bonuses
    for each row when (new.status = 'suggested')
    execute function public.notify_bonus_suggested();

commit;

-- ===================================================================== 0023_expected_payment.sql

-- A seller pays once the purchase price has reached them, so their commission invoice has no due
-- date: the money is expected eight weeks after the notary date. Administrators hear about it when
-- that date passes and the invoice is still open. Re-runnable.

begin;

alter table public.outgoing_invoices add column if not exists overdue_notified_at timestamptz;

create or replace function public.seller_payment_wait_days() returns integer
language sql immutable as $$ select 56 $$;

create or replace function public.expected_payment_for_party(p_deal_party_id uuid) returns date
language sql stable security definer set search_path to 'public'
as $$
  select d.notarised_on + public.seller_payment_wait_days()
    from public.deal_parties dp
    join public.deal_sides s on s.id = dp.deal_side_id
    join public.deals d on d.id = s.deal_id
   where dp.id = p_deal_party_id and s.side = 'seller';
$$;

create or replace function public.set_expected_payment_on() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  if new.expected_payment_on is null and new.due_date is null
     and new.deal_party_id is not null and new.kind is distinct from 'referral_credit' then
    new.expected_payment_on := public.expected_payment_for_party(new.deal_party_id);
  end if;
  return new;
end;
$$;

drop trigger if exists outgoing_invoices_set_expected_payment on public.outgoing_invoices;
create trigger outgoing_invoices_set_expected_payment
    before insert or update of deal_party_id, due_date on public.outgoing_invoices
    for each row execute function public.set_expected_payment_on();

create or replace function public.notify_overdue_payments() returns integer
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_ids uuid[];
  v_count integer;
begin
  select array_agg(id) into v_ids
    from public.outgoing_invoices
   where deleted_at is null
     and status in ('sent', 'overdue')
     and due_date is null
     and expected_payment_on < current_date
     and overdue_notified_at is null;
  v_count := coalesce(cardinality(v_ids), 0);
  if v_count = 0 then
    return 0;
  end if;

  perform public.notify_administrators(
    case when v_count = 1 then 'Eine Provisionsrechnung ist überfällig'
         else v_count || ' Provisionsrechnungen sind überfällig' end,
    '/outgoing-invoices', 'payment');
  update public.outgoing_invoices set overdue_notified_at = now() where id = any (v_ids);
  return v_count;
end;
$$;

revoke execute on function public.notify_overdue_payments() from public, anon, authenticated;
grant execute on function public.notify_overdue_payments() to service_role;
revoke execute on function public.expected_payment_for_party(uuid) from public, anon, authenticated;
revoke execute on function public.set_expected_payment_on() from public, anon, authenticated;

commit;

-- ===================================================================== 0024_payment_files.sql

-- The manual SEPA payment file: which account a company pays from, the files built from approved
-- documents, and what went into each one.
--
-- Separate from payment_orders (0006_bank.sql), which is a different mechanism: an order sent
-- straight to a bank provider through its API. This is the opposite shape, a file a person
-- downloads and uploads to their own bank, so it has no provider_* column anywhere.
--
-- Created after 0010_access.sql and 0014_triggers.sql, so its own row level security and its own
-- triggers are written here rather than folded into those files: a fresh apply runs this file last,
-- and a loop over a table name that does not exist yet fails.

begin;

-- A company may pay from more than one account, so this is company_id -> many rows rather than
-- company_id -> one. The one marked is_default is where a new payment file starts out pointed, and
-- the trigger below keeps that column honest: at most one default row per company, and never zero
-- while the company has an active account at all.
create table if not exists public.payment_settings (
    id uuid primary key default gen_random_uuid(),
    company_id uuid not null references public.companies(id),

    label text not null default 'Main account',
    payer_name text not null,
    payer_iban text not null,
    payer_bic text,

    pain_version text not null default 'pain.001.001.09',
    execution_date_rule text not null default 'as_soon_as_possible',
    batch_booking boolean not null default false,
    max_transfers_per_file integer,
    extra_closing_days date[] not null default '{}',

    is_default boolean not null default true,

    updated_at timestamptz not null default now(),
    updated_by text,
    deleted_at timestamptz,

    constraint payment_settings_pain_version_known
        check (pain_version in ('pain.001.001.02', 'pain.001.001.03', 'pain.001.001.08', 'pain.001.001.09')),
    constraint payment_settings_execution_date_rule_known
        check (execution_date_rule in ('as_soon_as_possible', 'on_due_date'))
);

create index if not exists payment_settings_company on public.payment_settings (company_id);

-- Only one row per company may be the default, and only among the ones still active. A deleted
-- account keeps whatever it last held so the unique index below does not block its replacement.
create unique index if not exists payment_settings_one_default_per_company
    on public.payment_settings (company_id) where is_default and deleted_at is null;

-- A file this Hub built from a set of approved documents, paid from one account. Kept once
-- downloaded even if every item in it later gets discarded some other way, because a client needs
-- to see that it was built and what it said at the time.
create table if not exists public.payment_files (
    id uuid primary key default gen_random_uuid(),
    company_id uuid not null references public.companies(id),
    payment_settings_id uuid references public.payment_settings(id) on delete set null,

    created_by text,
    created_at timestamptz not null default now(),

    downloaded_at timestamptz,
    download_count integer not null default 0,

    filename text,
    pain_version text,
    total numeric(14, 2) not null default 0,
    item_count integer not null default 0,

    status text not null default 'draft',
    note text,

    constraint payment_files_status_known
        check (status in ('draft', 'generated', 'downloaded', 'discarded'))
);

create index if not exists payment_files_company on public.payment_files (company_id);
create index if not exists payment_files_status on public.payment_files (status) where status != 'discarded';

-- One document queued into one payment file. A document can only sit in one open (non-discarded)
-- file at a time, enforced below, so the same invoice can never end up in two files waiting to be
-- downloaded.
create table if not exists public.payment_file_items (
    id uuid primary key default gen_random_uuid(),
    payment_file_id uuid not null references public.payment_files(id) on delete cascade,
    company_id uuid not null references public.companies(id),
    document_id uuid not null references public.documents(id),

    recipient_name text not null,
    iban text not null,
    bic text,
    amount numeric(14, 2) not null,
    payment_reference text,
    discount_applied boolean not null default false,

    -- Set when this item could not be turned into a transfer: no confirmed account, an invalid
    -- IBAN, a direct debit that must not be transferred again, and so on. One of the sepa engine's
    -- own rejection reasons, kept as plain text so a new reason needs no migration here.
    skipped_reason text,

    created_at timestamptz not null default now(),

    constraint payment_file_items_amount_positive check (amount > 0),
    unique (payment_file_id, document_id)
);

create index if not exists payment_file_items_file on public.payment_file_items (payment_file_id);
create index if not exists payment_file_items_document on public.payment_file_items (document_id);
create index if not exists payment_file_items_company on public.payment_file_items (company_id);

-- The pain.001 XML the engine actually produced for one payment file. A file can split into more
-- than one document when the account settings cap how many transfers go in one message, which is
-- why this is its own table rather than a column on payment_files.
create table if not exists public.payment_file_documents (
    id uuid primary key default gen_random_uuid(),
    payment_file_id uuid not null references public.payment_files(id) on delete cascade,
    company_id uuid not null references public.companies(id),

    file_name text not null,
    message_id text not null,
    content text not null,
    transfer_count integer not null,
    total numeric(14, 2) not null,

    created_at timestamptz not null default now(),

    unique (message_id)
);

create index if not exists payment_file_documents_file on public.payment_file_documents (payment_file_id);
create index if not exists payment_file_documents_company on public.payment_file_documents (company_id);

-- A company's first account becomes its default without anyone ticking a box, and a company left
-- with no default while it still has an active account is a state the deferred check below refuses
-- to let a transaction commit in.
create or replace function public.payment_settings_ensure_default()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if not exists (
        select 1 from public.payment_settings
         where company_id = new.company_id
           and is_default
           and deleted_at is null
           and id != new.id
    ) then
        new.is_default := true;
    end if;
    return new;
end;
$$;

drop trigger if exists trg_payment_settings_ensure_default on public.payment_settings;
create trigger trg_payment_settings_ensure_default
    before insert on public.payment_settings
    for each row execute function public.payment_settings_ensure_default();

-- Promoting the next account runs AFTER the soft delete, not before: a BEFORE trigger racing the
-- partial unique index above would try to set the new default default while the old one still held
-- it, and the index would refuse the row that was supposed to replace it.
create or replace function public.payment_settings_promote_next_default()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_next uuid;
begin
    if new.deleted_at is not null and old.deleted_at is null and old.is_default then
        update public.payment_settings set is_default = false where id = new.id;

        select id into v_next
          from public.payment_settings
         where company_id = new.company_id
           and deleted_at is null
           and id != new.id
         order by updated_at desc
         limit 1;

        if v_next is not null then
            update public.payment_settings set is_default = true where id = v_next;
        end if;
    end if;
    return null;
end;
$$;

drop trigger if exists trg_payment_settings_promote_next_default on public.payment_settings;
create trigger trg_payment_settings_promote_next_default
    after update on public.payment_settings
    for each row execute function public.payment_settings_promote_next_default();

-- The one way to switch a company's default account deliberately, checked the same way every other
-- write to this table is: company access plus the payments capability.
create or replace function public.set_default_payment_account(p_account_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_company_id uuid;
begin
    select company_id into v_company_id
      from public.payment_settings
     where id = p_account_id and deleted_at is null;

    if v_company_id is null then
        raise exception 'payment account % not found', p_account_id;
    end if;
    if not public.has_company_access(v_company_id) or not public.may_write('payments.write') then
        raise exception 'insufficient permission';
    end if;

    update public.payment_settings set is_default = false
     where company_id = v_company_id and id != p_account_id and is_default;
    update public.payment_settings set is_default = true
     where id = p_account_id;
end;
$$;

revoke execute on function public.set_default_payment_account(uuid) from public, anon;
grant execute on function public.set_default_payment_account(uuid) to authenticated;

-- The invariant the two triggers above exist to keep: at the end of any transaction that touched
-- this table, a company has exactly one default account among its active ones, or none at all if it
-- has no active account left. Deferred to commit time because a switch is two updates (clear the
-- old one, set the new one) and the row count is briefly wrong between them.
create or replace function public.payment_settings_check_exactly_one_default()
returns trigger
language plpgsql
as $$
declare
    v_company_id uuid := coalesce(new.company_id, old.company_id);
    v_default_count integer;
    v_active_count integer;
begin
    select count(*) into v_default_count
      from public.payment_settings
     where company_id = v_company_id and is_default and deleted_at is null;

    select count(*) into v_active_count
      from public.payment_settings
     where company_id = v_company_id and deleted_at is null;

    if v_default_count > 1 then
        raise exception 'company % ended the transaction with % default payment accounts', v_company_id, v_default_count;
    end if;
    if v_default_count = 0 and v_active_count > 0 then
        raise exception 'company % has % active payment account(s) but none marked default', v_company_id, v_active_count;
    end if;
    return null;
end;
$$;

drop trigger if exists trg_payment_settings_check_exactly_one_default on public.payment_settings;
create constraint trigger trg_payment_settings_check_exactly_one_default
    after insert or update or delete on public.payment_settings
    deferrable initially deferred
    for each row execute function public.payment_settings_check_exactly_one_default();

-- A payment_file_items row never states its own company: it inherits the one its payment file was
-- raised for, so a caller cannot slip a document into another company's file by naming a different
-- company_id at insert time.
create or replace function public.payment_file_item_set_company()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    select company_id into strict new.company_id
      from public.payment_files where id = new.payment_file_id;
    return new;
end;
$$;

drop trigger if exists trg_payment_file_item_set_company on public.payment_file_items;
create trigger trg_payment_file_item_set_company
    before insert on public.payment_file_items
    for each row execute function public.payment_file_item_set_company();

-- The same document must never sit in two files that are both still open, so a person cannot build
-- two payment files from one invoice and pay it twice.
create or replace function public.payment_file_item_prevent_double_queue()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if exists (
        select 1
          from public.payment_file_items pfi
          join public.payment_files pf on pf.id = pfi.payment_file_id
         where pfi.document_id = new.document_id
           and pfi.payment_file_id != new.payment_file_id
           and pf.status != 'discarded'
    ) then
        raise exception 'document % is already queued in an open payment file', new.document_id
            using errcode = 'unique_violation';
    end if;
    return new;
end;
$$;

drop trigger if exists trg_payment_file_item_prevent_double_queue on public.payment_file_items;
create trigger trg_payment_file_item_prevent_double_queue
    before insert on public.payment_file_items
    for each row execute function public.payment_file_item_prevent_double_queue();

create or replace function public.payment_file_document_set_company()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    select company_id into strict new.company_id
      from public.payment_files where id = new.payment_file_id;
    return new;
end;
$$;

drop trigger if exists trg_payment_file_document_set_company on public.payment_file_documents;
create trigger trg_payment_file_document_set_company
    before insert on public.payment_file_documents
    for each row execute function public.payment_file_document_set_company();

-- Row level security, written out directly rather than through the generic loop in 0010_access.sql:
-- that file runs before this one, so a loop there over a table this file creates would fail on a
-- fresh apply. Same contract as every other table in that loop: the payments.write capability for
-- read and write, has_company_access as an additional restrictive filter.
alter table public.payment_settings enable row level security;
alter table public.payment_files enable row level security;
alter table public.payment_file_items enable row level security;
alter table public.payment_file_documents enable row level security;

do $$
declare
    t text;
begin
    foreach t in array array[
        'payment_settings', 'payment_files', 'payment_file_items', 'payment_file_documents'
    ] loop
        execute format('drop policy if exists %I on public.%I', t || '_read', t);
        execute format(
            'create policy %I on public.%I for select to authenticated using (public.may_read(%L))',
            t || '_read', t, 'payments.write');

        execute format('drop policy if exists %I on public.%I', t || '_write', t);
        execute format(
            'create policy %I on public.%I for all to authenticated using (public.may_write(%L)) with check (public.may_write(%L))',
            t || '_write', t, 'payments.write', 'payments.write');

        execute format('drop policy if exists %I on public.%I', t || '_company_scope', t);
        execute format(
            'create policy %I on public.%I as restrictive for all to authenticated using (public.has_company_access(company_id)) with check (public.has_company_access(company_id))',
            t || '_company_scope', t);
    end loop;
end
$$;

-- None of these four tables carries its own is_demo column, so company_demo_visible()
-- (0010_access.sql) asks the company instead. has_company_access() above has no demo awareness, so
-- without this a practice tour's payment data would stay reachable outside practice mode.
do $$
declare
    t text;
begin
    foreach t in array array[
        'payment_settings', 'payment_files', 'payment_file_items', 'payment_file_documents'
    ] loop
        execute format('drop policy if exists %I on public.%I', t || '_demo_owner', t);
        execute format(
            'create policy %I on public.%I as restrictive for all to authenticated '
            || 'using (public.company_demo_visible(company_id)) '
            || 'with check (public.company_demo_visible(company_id))',
            t || '_demo_owner', t);
    end loop;
end
$$;

commit;

-- ===================================================================== 0025_client_error_log.sql

begin;

create table if not exists public.client_error_log (
  id          uuid primary key default gen_random_uuid(),
  occurred_at timestamptz not null default now(),
  message     text not null,
  stack       text,
  route       text,
  boundary    text,
  user_id     uuid references auth.users(id) on delete set null
);

create index if not exists client_error_log_occurred_at_idx
  on public.client_error_log (occurred_at desc);

alter table public.client_error_log enable row level security;

drop policy if exists "client_error_log_insert" on public.client_error_log;
create policy "client_error_log_insert" on public.client_error_log
  for insert to authenticated with check (true);

drop policy if exists "client_error_log_select" on public.client_error_log;
create policy "client_error_log_select" on public.client_error_log
  for select to authenticated using (public.is_admin());

commit;

do $$
declare
  v_missing text[] := '{}';
begin
  if to_regclass('public.client_error_log') is null then
    v_missing := v_missing || 'client_error_log table';
  end if;
  if not exists (
    select 1 from pg_policies
     where schemaname = 'public' and tablename = 'client_error_log'
       and policyname = 'client_error_log_insert'
  ) then
    v_missing := v_missing || 'client_error_log_insert policy';
  end if;
  if not exists (
    select 1 from pg_policies
     where schemaname = 'public' and tablename = 'client_error_log'
       and policyname = 'client_error_log_select'
  ) then
    v_missing := v_missing || 'client_error_log_select policy';
  end if;
  if array_length(v_missing, 1) is not null then
    raise exception '0025_client_error_log self-check failed, missing: %', array_to_string(v_missing, ', ');
  end if;
end $$;

-- ===================================================================== 0026_confidence_settings.sql

begin;

create table if not exists public.confidence_settings (
    id boolean primary key default true check (id),
    ampel_green_min numeric not null default 0.95
        check (ampel_green_min > 0 and ampel_green_min <= 1),
    ampel_yellow_min numeric not null default 0.80
        check (ampel_yellow_min > 0 and ampel_yellow_min <= 1),
    relevance_min_konfidenz numeric not null default 0.5
        check (relevance_min_konfidenz > 0 and relevance_min_konfidenz <= 1),
    relevance_noninvoice_max_konfidenz numeric not null default 0.3
        check (relevance_noninvoice_max_konfidenz > 0 and relevance_noninvoice_max_konfidenz <= 1),
    updated_at timestamptz not null default now(),
    updated_by text,
    constraint confidence_settings_bands_ordered
        check (ampel_green_min >= ampel_yellow_min and ampel_yellow_min >= relevance_min_konfidenz)
);

insert into public.confidence_settings (id) values (true) on conflict (id) do nothing;

alter table public.confidence_settings enable row level security;

drop policy if exists confidence_settings_read on public.confidence_settings;
create policy confidence_settings_read on public.confidence_settings
    for select to authenticated using (public.may_read('documents.read'));

drop policy if exists confidence_settings_write on public.confidence_settings;
create policy confidence_settings_write on public.confidence_settings
    for all to authenticated
    using (public.may_write('settings.manage'))
    with check (public.may_write('settings.manage'));

commit;

-- ===================================================================== 0027_document_intake_log.sql

begin;

drop view if exists public.v_document_intake_log;

create view public.v_document_intake_log with (security_invoker = true) as
select
    d.id,
    d.invoice_number,
    d.created_at,
    d.issuer,
    d.service_description,
    d.document_type,
    d.company_code,
    d.intake_channel,
    d.fts,
    case
        when exists (
            select 1 from public.document_files f
             where f.document_id = d.id
               and f.source = 'sharepoint'
               and f.deleted_at is null
        ) then 'filed'
        when d.handed_over_at is not null or d.workflow_status = 'uebergeben_datev' then 'handed_over'
        when d.not_relevant_at is not null then 'not_relevant'
        when d.archived_at is not null then 'archived'
        when d.workflow_status in (
            'approved_first', 'approved_final', 'paid', 'closed',
            'freigegeben_assistenz', 'freigegeben_vorgesetzter', 'bezahlt', 'abgeschlossen'
        ) then 'approved'
        when d.workflow_status in ('in_review', 'query', 'in_pruefung', 'rueckfrage') then 'in_review'
        when d.status in ('recognised', 'erkannt') then 'recognised'
        else 'open'
    end as outcome
from public.documents d
where d.deleted_at is null;

comment on view public.v_document_intake_log is
    'Everything that arrived, with what became of it. Feeds the intake log screen, which answers '
    '"what came in" rather than "what is there to work on", so archived, not relevant and already '
    'filed documents stay visible instead of being hidden the way the document list hides them.';

grant select on public.v_document_intake_log to authenticated;

commit;

do $$
begin
    if to_regclass('public.v_document_intake_log') is null then
        raise exception 'v_document_intake_log self-check FAILED: the view is missing';
    end if;
    if not exists (
        select 1 from pg_class c
         where c.oid = 'public.v_document_intake_log'::regclass
           and c.reloptions @> array['security_invoker=true']
    ) then
        raise exception 'v_document_intake_log self-check FAILED: security_invoker is not set, a private document would leak';
    end if;
    raise notice 'v_document_intake_log ok: view in place, security_invoker set';
end $$;

-- ===================================================================== 0028_document_types.sql

begin;

create table if not exists public.document_types (
    id uuid primary key default gen_random_uuid(),
    code text not null,
    label text not null,
    description text,
    maps_from text[] not null default '{}',
    is_fallback boolean not null default false,
    is_active boolean not null default true,
    is_seeded boolean not null default false,
    sort_order integer not null default 0,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create unique index if not exists document_types_one_active_fallback
    on public.document_types ((true))
    where is_fallback and is_active;

create unique index if not exists document_types_code_active_uniq
    on public.document_types (lower(code))
    where is_active;

create or replace function public.document_type_canonical(p_value text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
           when btrim(coalesce(p_value, '')) = '' then null
           else regexp_replace(lower(btrim(p_value)), '\s+', '_', 'g')
         end;
$$;

comment on function public.document_type_canonical(text) is
  'Trimmed, lowercased spelling of a document type with whitespace folded to underscores.';

revoke all on function public.document_type_canonical(text) from public;
grant execute on function public.document_type_canonical(text) to authenticated;

commit;

-- ===================================================================== 0029_deal_donations.sql

-- A donation tied to a sale above a configured threshold, for an administrator to record when the
-- organisation and its details are known, and mark paid once the transfer is made. Inert until a
-- role holds `donations.manage`, which no role does by default. Re-runnable.

begin;

create table if not exists public.deal_donations (
    id uuid primary key default gen_random_uuid(),
    deal_id uuid not null references public.deals(id),
    organisation text not null,
    iban text,
    contact_person text,
    contact_reachability text,
    handover_date date,
    amount numeric(12, 2) not null check (amount > 0),
    status text not null default 'suggested' check (status in ('suggested', 'paid', 'cancelled')),
    cancel_reason text,
    created_by uuid references public.app_users(id),
    created_at timestamptz not null default now(),
    paid_by uuid references public.app_users(id),
    paid_at timestamptz,
    updated_at timestamptz not null default now()
);

-- A cancelled donation does not block a fresh suggestion for the same deal; a suggested or paid one
-- does, since a deal gives one organisation its donation, not several.
create unique index if not exists deal_donations_one_active_per_deal
    on public.deal_donations (deal_id)
    where status <> 'cancelled';

create table if not exists public.donation_settings (
    single_row boolean primary key default true check (single_row),
    threshold_amount numeric(12, 2) not null default 500000 check (threshold_amount > 0),
    donation_amount numeric(12, 2) not null default 1000 check (donation_amount > 0),
    updated_at timestamptz not null default now()
);

insert into public.donation_settings (single_row) values (true) on conflict do nothing;

drop trigger if exists donation_settings_touch on public.donation_settings;
create trigger donation_settings_touch before update on public.donation_settings
    for each row execute function public.set_updated_at();

drop trigger if exists deal_donations_touch on public.deal_donations;
create trigger deal_donations_touch before update on public.deal_donations
    for each row execute function public.set_updated_at();

create or replace function public.stamp_deal_donation() returns trigger
language plpgsql set search_path to 'public'
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := public.current_app_user_id();
  elsif new.status = 'paid' and old.status <> 'paid' then
    new.paid_by := public.current_app_user_id();
    new.paid_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists deal_donations_stamp_insert on public.deal_donations;
create trigger deal_donations_stamp_insert before insert on public.deal_donations
    for each row execute function public.stamp_deal_donation();

drop trigger if exists deal_donations_stamp_paid on public.deal_donations;
create trigger deal_donations_stamp_paid before update on public.deal_donations
    for each row execute function public.stamp_deal_donation();

alter table public.donation_settings enable row level security;
alter table public.deal_donations enable row level security;

drop policy if exists donation_settings_read on public.donation_settings;
create policy donation_settings_read on public.donation_settings for select to authenticated
    using (public.has_permission('donations.manage'));

drop policy if exists donation_settings_write on public.donation_settings;
create policy donation_settings_write on public.donation_settings for update to authenticated
    using (public.has_permission('donations.manage'))
    with check (public.has_permission('donations.manage'));

drop policy if exists deal_donations_rw on public.deal_donations;
create policy deal_donations_rw on public.deal_donations for all to authenticated
    using (public.has_permission('donations.manage'))
    with check (public.has_permission('donations.manage'));

grant select, update on public.donation_settings to authenticated;
grant select, insert, update, delete on public.deal_donations to authenticated;

create or replace function public.notify_donation_suggested() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
begin
  perform public.notify_administrators(
    'Spende vorgeschlagen: ' || new.organisation || ', '
      || replace(to_char(new.amount, 'FM999999990.00'), '.', ',') || ' €',
    '/commission-deals/' || new.deal_id, 'donation', new.created_by,
    coalesce((select coalesce(name, email) from public.app_users where id = new.created_by), 'Hub'));
  return null;
end;
$$;

drop trigger if exists deal_donations_notify_suggested on public.deal_donations;
create trigger deal_donations_notify_suggested after insert on public.deal_donations
    for each row when (new.status = 'suggested')
    execute function public.notify_donation_suggested();

commit;

-- ===================================================================== 0030_change_history_log_function.sql

-- `change_history` is readable by whoever may read the thing it is about, and written by nobody
-- directly (see 0010_access.sql) -- a raw client insert is rejected by RLS, on purpose: the audit
-- trail stays authoritative only if nothing can fabricate an entry attributing arbitrary text to
-- arbitrary data. `insertChangeHistory()` in src/data/client.ts was written assuming a direct
-- insert would work and has been failing silently on every call since the table existed: the
-- underlying write (e.g. a role permission grant) succeeds, the change_history insert after it is
-- rejected, the whole mutation throws, and the screen never learns the real write went through.
--
-- log_change_history() is the trusted path that policy was always meant to require: it derives the
-- actor itself from the caller's own session, the same way every other security definer writer in
-- this schema does, rather than trusting a client-supplied value.

begin;

create or replace function public.log_change_history(
    p_table_name text,
    p_record_id uuid,
    p_type text,
    p_text text,
    p_data jsonb default null
) returns void
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_actor text := coalesce(nullif(auth.jwt() ->> 'email', ''), 'hub');
begin
  insert into public.change_history (table_name, record_id, type, text, data, actor, at)
  values (p_table_name, p_record_id, p_type, p_text, p_data, v_actor, now());
end;
$$;

revoke all on function public.log_change_history(text, uuid, text, text, jsonb) from public, anon;
grant execute on function public.log_change_history(text, uuid, text, text, jsonb) to authenticated;

commit;

-- ===================================================================== 0031_crm_webhook_events.sql

-- Every CRM webhook delivery, successful or not, so a dropped or failing webhook is visible without
-- reading Edge Function logs. Pure event logging, not system-of-record tracking: the property row
-- itself is the source of truth, this is only the audit trail of what a webhook did about it.
--
-- One table across every CRM a client might connect, not one table per provider: a second CRM
-- integration reuses this rather than inventing its own. Started with Propstack because that is the
-- only provider a Hub has spoken to so far.

begin;

create table if not exists public.crm_webhook_events (
    id uuid primary key default gen_random_uuid(),
    crm_provider text not null,
    crm_record_id text,
    status text not null default 'processing',
    payload jsonb not null default '{}'::jsonb,
    error text,
    received_at timestamptz not null default now(),
    processed_at timestamptz,
    constraint crm_webhook_events_provider_known check (crm_provider in ('propstack')),
    constraint crm_webhook_events_status_known check (status in (
        'processing', 'done', 'skipped', 'failed'))
);

create index if not exists crm_webhook_events_received on public.crm_webhook_events (received_at desc);
create index if not exists crm_webhook_events_record on public.crm_webhook_events (crm_provider, crm_record_id);

alter table public.crm_webhook_events enable row level security;

drop policy if exists crm_webhook_events_read on public.crm_webhook_events;
create policy crm_webhook_events_read on public.crm_webhook_events
    for select to authenticated using (public.may_read('master_data.read'));

drop policy if exists crm_webhook_events_write on public.crm_webhook_events;
create policy crm_webhook_events_write on public.crm_webhook_events
    for all to authenticated
    using (public.may_write('master_data.write'))
    with check (public.may_write('master_data.write'));

commit;

-- ===================================================================== 0032_referrer_bonuses.sql

-- Fixed-amount referrer ("Tippgeber") bonuses, by how many of that referrer's deals have already
-- succeeded this calendar year. Fixed amounts replaced a percentage model the client used until
-- 27 October; see docs/REFERRER_BONUSES.md. A referrer is a customer, never an app_user, so this
-- is its own table rather than a row in broker_bonuses, the same reasoning docs/DEAL_DONATIONS.md
-- already gives for deal_donations. Inert until a role holds `bonuses.review`, same gate as broker
-- bonuses. Re-runnable.

begin;

alter table public.bonus_settings
    add column if not exists referrer_tier1_amount numeric(12, 2) not null default 1000
        check (referrer_tier1_amount > 0),
    add column if not exists referrer_tier2_amount numeric(12, 2) not null default 1500
        check (referrer_tier2_amount > 0),
    add column if not exists referrer_tier3_amount numeric(12, 2) not null default 2000
        check (referrer_tier3_amount > 0),
    add column if not exists referrer_tier4plus_amount numeric(12, 2) not null default 2000
        check (referrer_tier4plus_amount > 0);

create table if not exists public.deal_referrer_bonuses (
    id uuid primary key default gen_random_uuid(),
    deal_id uuid not null references public.deals(id),
    referrer_customer_id uuid not null references public.customers(id),
    tier integer not null check (tier > 0),
    amount numeric(12, 2) not null check (amount > 0),
    earned_on date not null,
    status text not null default 'suggested' check (status in ('suggested', 'paid', 'cancelled')),
    cancel_reason text,
    created_by uuid references public.app_users(id),
    created_at timestamptz not null default now(),
    paid_by uuid references public.app_users(id),
    paid_at timestamptz,
    updated_at timestamptz not null default now()
);

-- A cancelled bonus does not block a fresh suggestion for the same deal; a suggested or paid one
-- does, since a deal earns its referrer one bonus, not several.
create unique index if not exists deal_referrer_bonuses_one_active_per_deal
    on public.deal_referrer_bonuses (deal_id)
    where status <> 'cancelled';

create index if not exists deal_referrer_bonuses_referrer_year
    on public.deal_referrer_bonuses (referrer_customer_id, earned_on)
    where status <> 'cancelled';

-- Which referral number this would be for that referrer this calendar year, counting only
-- non-cancelled bonuses already recorded -- the client reads this to default the amount field,
-- same as the donation card defaults to donation_settings.donation_amount.
create or replace function public.referrer_bonus_tier(p_referrer_customer_id uuid, p_earned_on date)
returns integer
language sql stable security definer set search_path to 'public'
as $$
  select count(*)::integer + 1
    from public.deal_referrer_bonuses
   where referrer_customer_id = p_referrer_customer_id
     and status <> 'cancelled'
     and extract(year from earned_on) = extract(year from p_earned_on);
$$;

revoke execute on function public.referrer_bonus_tier(uuid, date) from public, anon;
grant execute on function public.referrer_bonus_tier(uuid, date) to authenticated;

drop trigger if exists deal_referrer_bonuses_touch on public.deal_referrer_bonuses;
create trigger deal_referrer_bonuses_touch before update on public.deal_referrer_bonuses
    for each row execute function public.set_updated_at();

create or replace function public.stamp_deal_referrer_bonus() returns trigger
language plpgsql set search_path to 'public'
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := public.current_app_user_id();
  elsif new.status = 'paid' and old.status <> 'paid' then
    new.paid_by := public.current_app_user_id();
    new.paid_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists deal_referrer_bonuses_stamp_insert on public.deal_referrer_bonuses;
create trigger deal_referrer_bonuses_stamp_insert before insert on public.deal_referrer_bonuses
    for each row execute function public.stamp_deal_referrer_bonus();

drop trigger if exists deal_referrer_bonuses_stamp_paid on public.deal_referrer_bonuses;
create trigger deal_referrer_bonuses_stamp_paid before update on public.deal_referrer_bonuses
    for each row execute function public.stamp_deal_referrer_bonus();

alter table public.deal_referrer_bonuses enable row level security;

drop policy if exists deal_referrer_bonuses_rw on public.deal_referrer_bonuses;
create policy deal_referrer_bonuses_rw on public.deal_referrer_bonuses for all to authenticated
    using (public.has_permission('bonuses.review'))
    with check (public.has_permission('bonuses.review'));

grant select, insert, update, delete on public.deal_referrer_bonuses to authenticated;

create or replace function public.notify_referrer_bonus_suggested() returns trigger
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_referrer_name text;
begin
  select name into v_referrer_name from public.customers where id = new.referrer_customer_id;
  perform public.notify_administrators(
    'Tippgeber-Bonus vorgeschlagen: ' || coalesce(v_referrer_name, 'Tippgeber') || ', '
      || replace(to_char(new.amount, 'FM999999990.00'), '.', ',') || ' €',
    '/commission-deals/' || new.deal_id, 'referrer_bonus', new.created_by,
    coalesce((select coalesce(name, email) from public.app_users where id = new.created_by), 'Hub'));
  return null;
end;
$$;

drop trigger if exists deal_referrer_bonuses_notify_suggested on public.deal_referrer_bonuses;
create trigger deal_referrer_bonuses_notify_suggested after insert on public.deal_referrer_bonuses
    for each row when (new.status = 'suggested')
    execute function public.notify_referrer_bonus_suggested();

commit;

-- ===================================================================== 0033_referrer_credit_notes.sql

-- Turns a paid referrer bonus (deal_referrer_bonuses, migration 0032) into the accounting record of
-- that payout: an outgoing_invoices row with kind = 'referral_credit', the kind the table already
-- anticipated (0008_workspace.sql) for exactly this — "paid out to whoever recommended the
-- customer, so it names the deal that earned it rather than another invoice". No VAT split: the
-- client's figures are flat euro amounts with no VAT ever mentioned, so net and gross are the same.
-- Re-runnable.

begin;

create or replace function public.create_referrer_credit_note(p_bonus_id uuid)
    returns public.outgoing_invoices
    language plpgsql security invoker
    set search_path to 'public'
    as $$
declare
  v_bonus public.deal_referrer_bonuses;
  v_deal public.deals;
  v_invoice public.outgoing_invoices;
begin
  select * into v_bonus from public.deal_referrer_bonuses where id = p_bonus_id;
  if not found then
    raise exception 'create_referrer_credit_note: bonus % not found', p_bonus_id;
  end if;
  if v_bonus.status <> 'paid' then
    raise exception 'create_referrer_credit_note: bonus % is not paid', p_bonus_id
      using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.outgoing_invoices
     where deal_id = v_bonus.deal_id and kind = 'referral_credit' and deleted_at is null
  ) then
    raise exception 'create_referrer_credit_note: a credit note already exists for deal %',
      v_bonus.deal_id using errcode = 'unique_violation';
  end if;

  select * into v_deal from public.deals where id = v_bonus.deal_id and deleted_at is null;
  if not found then
    raise exception 'create_referrer_credit_note: deal % not found', v_bonus.deal_id;
  end if;

  insert into public.outgoing_invoices (
    company_id, customer_id, kind, deal_id,
    status, invoice_date, amount_net, amount_gross
  ) values (
    v_deal.company_id, v_bonus.referrer_customer_id, 'referral_credit', v_bonus.deal_id,
    'draft', coalesce(v_bonus.paid_at::date, current_date), v_bonus.amount, v_bonus.amount
  )
  returning * into v_invoice;

  return v_invoice;
end;
$$;

revoke execute on function public.create_referrer_credit_note(uuid) from public, anon;
grant execute on function public.create_referrer_credit_note(uuid) to authenticated;

commit;

