-- ===================================================================== 0038_crm_sold_status_abgeschlossen.sql

begin;

create or replace function public.stamp_became_sold() returns trigger
language plpgsql set search_path to 'public'
as $$
begin
  if new.crm_status in ('Verkauft', 'Abgeschlossen')
     and old.crm_status is distinct from new.crm_status then
    new.became_sold_at := now();
  end if;
  return new;
end;
$$;

drop function if exists public.create_deals_for_sold_properties(text);

create or replace function public.create_deals_for_sold_properties(
    p_sold_statuses text[] default array['Verkauft', 'Abgeschlossen']
)
returns integer
language plpgsql security definer set search_path to 'public'
as $$
declare
  v_switched_on timestamptz;
  v_created integer := 0;
  v_deal record;
begin
  if not exists (select 1 from public.live_features() f where f.key = 'deals.from_crm') then
    return 0;
  end if;

  select updated_at into v_switched_on
    from public.feature_settings where feature_key = 'deals.from_crm' and enabled;
  if v_switched_on is null then
    return 0;
  end if;

  for v_deal in
    with opened as (
      insert into public.deals (
          company_id, property_id, property_label, source, external_id, status,
          notarised_on, purchase_price, acquired_by, handled_by, created_by)
      select (select c.id from public.companies c where c.deleted_at is null order by c.created_at limit 1),
             p.id,
             concat_ws(', ', coalesce(p.name, p.code), p.address),
             p.source, p.external_id, 'incomplete',
             p.sold_on, nullif(p.sold_price, 0),
             b.id, b.id, 'crm'
        from public.properties p
        left join public.app_users b
               on b.crm_external_id = p.broker_external_id and b.is_active
       where p.deleted_at is null
         and p.crm_status = any(p_sold_statuses)
         and p.became_sold_at >= v_switched_on
         and p.external_id is not null
      on conflict (source, external_id) where external_id is not null do nothing
      returning id, property_id, property_label, acquired_by
    )
    select * from opened
  loop
    v_created := v_created + 1;

    insert into public.deal_sides (deal_id, side, fee_kind, fee_net_rate)
    select v_deal.id, side.name, 'percent',
           public.crm_net_rate(side.gross_rate, d.vat_rate)
      from public.deals d
      join public.properties p on p.id = v_deal.property_id
      cross join lateral (values
        ('buyer',  public.crm_rate(p.crm_data ->> 'external_commission_percentage')),
        ('seller', public.crm_rate(p.crm_data ->> 'internal_commission_percentage'))
      ) as side(name, gross_rate)
     where d.id = v_deal.id;

    update public.deals
       set note = 'Provisionssätze aus dem CRM übernommen (Bruttosätze auf netto umgerechnet). Bitte prüfen.'
     where id = v_deal.id;

    perform public.notify_administrators(
      'Verkauft im CRM: ' || coalesce(v_deal.property_label, 'Objekt')
        || '. Die Provision wartet auf Vervollständigung.',
      '/commission-deals/' || v_deal.id, 'crm', v_deal.acquired_by);
    if v_deal.acquired_by is not null then
      perform public.send_system_ping(
        v_deal.acquired_by, 'Hub',
        'Verkauft im CRM: ' || coalesce(v_deal.property_label, 'Objekt')
          || '. Die Provision wartet auf Vervollständigung.',
        '/commission-deals/' || v_deal.id, 'crm');
    end if;
  end loop;

  return v_created;
end;
$$;

revoke execute on function public.create_deals_for_sold_properties(text[]) from public, anon, authenticated;
grant execute on function public.create_deals_for_sold_properties(text[]) to service_role;

commit;

-- ===================================================================== 0039_lexoffice_rate_limit.sql

begin;

create table if not exists public.lexware_rate_limit (
    id boolean primary key default true,
    next_allowed_at timestamptz not null default now(),
    constraint lexware_rate_limit_single_row check (id)
);

insert into public.lexware_rate_limit (id) values (true) on conflict (id) do nothing;

-- No policy is added on purpose: only the security-definer function below ever touches this row,
-- so every other caller, including a signed-in admin, is correctly refused by default.
alter table public.lexware_rate_limit enable row level security;

-- Lexware allows 2 requests/second across all endpoints. Every call to the shared Lexware client,
-- from any Edge Function invocation, asks this function first and sleeps for the milliseconds it
-- returns. The row lock below makes the wait correct even when several invocations call this at
-- the same instant, which a module-level counter inside one Edge Function could never guarantee.
create or replace function public.lexware_throttle_wait() returns integer
    language plpgsql security definer set search_path to 'public'
    as $$
declare
  v_now timestamptz := clock_timestamp();
  v_next timestamptz;
  v_wait_ms integer;
begin
  select next_allowed_at into v_next from public.lexware_rate_limit where id for update;
  if v_next < v_now then
    v_next := v_now;
  end if;
  update public.lexware_rate_limit set next_allowed_at = v_next + interval '500 milliseconds' where id;
  v_wait_ms := greatest(0, ceil(extract(epoch from (v_next - v_now)) * 1000))::integer;
  return v_wait_ms;
end;
$$;

revoke execute on function public.lexware_throttle_wait() from public, anon, authenticated;
grant execute on function public.lexware_throttle_wait() to service_role;

commit;

-- ===================================================================== 0040_payment_file_practice_seed.sql

-- Finishes the payment-file practice tour (payment-file-practice-task.ts, migration e85e471): the
-- task steps were written and committed, but nothing ever seeded the one payable invoice, its
-- confirmed bank account, or the payer account the tour walks through — so the tour could never
-- actually be completed.
--
-- seedPracticeData() (seed_onboarding_demo_data) always runs before this one, per
-- OnboardingPracticeStart's own start/resume/restart sequence, so the demo company already exists
-- by the time this runs — this reads it, it does not create its own.
--
-- Returns the seeded document's id, the same shape seedStopCasesPracticeData's caller expects, so
-- restart/resume can validate and clean up through the existing generic
-- findLivePracticeDocumentIds/discardPracticeDocuments (is_demo + demo_owner_user_id is all those
-- need, nothing payment-file-specific). Any payment file a previous run built against that
-- document is reset to 'discarded' on every call, so a restart does not leave a stray draft or
-- generated file sitting in the history/track views.

begin;

create or replace function public.seed_payment_file_practice_data() returns uuid[]
    language plpgsql security definer set search_path to 'public'
    as $$
declare
  v_user_id uuid := public.current_app_user_id();
  v_tag text;
  v_company_id uuid;
  v_supplier_id uuid;
  v_bank_account_id uuid;
  v_document_id uuid;
begin
  if v_user_id is null then
    raise exception 'seed_payment_file_practice_data: no signed-in app user';
  end if;

  v_tag := substr(replace(v_user_id::text, '-', ''), 1, 8);

  select id into v_company_id from public.companies
   where is_demo and demo_owner_user_id = v_user_id and code = 'DEMO-' || v_tag;
  if v_company_id is null then
    raise exception 'seed_payment_file_practice_data: no demo company for user %, seedPracticeData should have run first', v_user_id;
  end if;

  select id into v_supplier_id from public.suppliers
   where is_demo and demo_owner_user_id = v_user_id and name = 'Dachdecker Brandt';
  if v_supplier_id is not null then
    update public.suppliers set deleted_at = null where id = v_supplier_id and deleted_at is not null;
  else
    insert into public.suppliers (name, is_demo, demo_owner_user_id)
    values ('Dachdecker Brandt', true, v_user_id)
    returning id into v_supplier_id;
  end if;

  select id into v_bank_account_id from public.supplier_bank_accounts
   where supplier_id = v_supplier_id and iban = 'DE89370400440532013000';
  if v_bank_account_id is not null then
    update public.supplier_bank_accounts
       set deleted_at = null, is_active = true, is_payable = true,
           confirmed_at = coalesce(confirmed_at, now())
     where id = v_bank_account_id;
  else
    insert into public.supplier_bank_accounts (
      supplier_id, iban, bic, source, is_active, is_payable, confirmed_at
    )
    values (
      v_supplier_id, 'DE89370400440532013000', 'COBADEFFXXX', 'human', true, true, now()
    )
    returning id into v_bank_account_id;
  end if;

  select id into v_document_id from public.documents
   where is_demo and demo_owner_user_id = v_user_id
     and payment_reference = 'BRANDT RE 2026-2201 890,00';
  if v_document_id is not null then
    update public.documents
       set deleted_at = null, company_id = v_company_id, supplier_id = v_supplier_id,
           workflow_status = 'approved_final', paid_at = null,
           due_date = current_date + 4
     where id = v_document_id;
  else
    insert into public.documents (
      issuer, supplier_id, invoice_number, document_date, due_date,
      amount_net, vat_rate, vat_amount, amount_gross, currency,
      payment_reference, payment_method, workflow_status,
      company_id, is_invoice, is_demo, demo_owner_user_id
    )
    values (
      'Dachdecker Brandt', v_supplier_id, 'RE-2026-2201', current_date - 10, current_date + 4,
      747.90, 19, 142.10, 890.00, 'EUR',
      'BRANDT RE 2026-2201 890,00', 'transfer', 'approved_final',
      v_company_id, true, true, v_user_id
    )
    returning id into v_document_id;
  end if;

  insert into public.document_bank_accounts (document_id, supplier_bank_account_id, position)
  select v_document_id, v_bank_account_id, 1
   where not exists (
     select 1 from public.document_bank_accounts
      where document_id = v_document_id and supplier_bank_account_id = v_bank_account_id
   );

  if not exists (select 1 from public.payment_settings where company_id = v_company_id) then
    insert into public.payment_settings (company_id, label, payer_name, payer_iban, is_default)
    values (v_company_id, 'Demo-Geschäftskonto', 'Demo Immobilien GmbH', 'DE02500105174917781216', true);
  end if;

  update public.payment_files f
     set status = 'discarded'
    from public.payment_file_items i
   where i.payment_file_id = f.id
     and i.document_id = v_document_id
     and f.status <> 'discarded';

  return array[v_document_id];
end $$;

revoke execute on function public.seed_payment_file_practice_data() from public, anon;
grant execute on function public.seed_payment_file_practice_data() to authenticated;

commit;

-- ===================================================================== 0041_propstack_payment_due_date.sql

begin;

-- Both columns stay null until the real PropStack sync reads them: the two custom fields this
-- depends on do not exist in PropStack yet, so nothing writes here today except manual test data
-- and, eventually, the sync itself.
alter table public.properties
    add column if not exists payment_due_date date,
    add column if not exists payment_due_date_note text,
    add column if not exists payment_due_date_notified_at timestamptz;

-- Six weeks after the notary date, if a deal still has no payment due date on its property,
-- someone should be asked to chase it or enter the note explaining why there is none. Modelled
-- directly on notify_overdue_payments() (0023_expected_payment.sql): date math, a scan for the
-- still-missing case, one notification, a stamp column so it never fires twice for the same deal.
create or replace function public.notify_missing_payment_dates() returns integer
    language plpgsql security definer set search_path to 'public'
    as $$
declare
  v_ids uuid[];
  v_count integer;
begin
  select array_agg(d.id) into v_ids
    from public.deals d
    join public.properties p on p.id = d.property_id
   where d.deleted_at is null
     and d.notarised_on < current_date - 42
     and p.payment_due_date is null
     and p.payment_due_date_note is null
     and p.payment_due_date_notified_at is null;
  v_count := coalesce(cardinality(v_ids), 0);
  if v_count = 0 then
    return 0;
  end if;

  perform public.notify_administrators(
    case when v_count = 1 then 'Eine Provision wartet seit über sechs Wochen auf ein Zahlungsziel'
         else v_count || ' Provisionen warten seit über sechs Wochen auf ein Zahlungsziel' end,
    '/commission-deals', 'reminder');

  update public.properties
     set payment_due_date_notified_at = now()
   where id in (select d.property_id from public.deals d where d.id = any (v_ids));

  return v_count;
end;
$$;

revoke execute on function public.notify_missing_payment_dates() from public, anon, authenticated;
grant execute on function public.notify_missing_payment_dates() to service_role;

commit;

-- ===================================================================== 0042_admin_panel_feature_audit.sql

begin;

alter table public.permissions
    add column if not exists shown_in_admin_panel boolean not null default true;

do $$
declare
  v_constraint text;
begin
  select tc.constraint_name
    into v_constraint
    from information_schema.table_constraints tc
    join information_schema.key_column_usage kcu
      on tc.constraint_name = kcu.constraint_name
     and tc.table_schema = kcu.table_schema
   where tc.table_schema = 'public'
     and tc.table_name = 'feature_settings'
     and tc.constraint_type = 'FOREIGN KEY'
     and kcu.column_name = 'updated_by';
  if v_constraint is not null then
    execute format('alter table public.feature_settings drop constraint %I', v_constraint);
  end if;
end;
$$;

alter table public.feature_settings
    alter column updated_by type text using updated_by::text;

create table if not exists public.feature_settings_history (
    id bigserial primary key,
    feature_key text not null,
    enabled boolean,
    changed_at timestamptz not null default now(),
    changed_by text,
    operation text
);

create index if not exists feature_settings_history_changed
    on public.feature_settings_history (changed_at desc);

create or replace function public.feature_settings_audit() returns trigger
language plpgsql set search_path to 'public'
as $$
begin
    if tg_op = 'UPDATE' and new.enabled is not distinct from old.enabled then
        return new;
    end if;
    if tg_op = 'DELETE' then
        insert into public.feature_settings_history (feature_key, enabled, changed_by, operation)
        values (old.feature_key, old.enabled, old.updated_by, 'delete');
        return old;
    end if;
    insert into public.feature_settings_history (feature_key, enabled, changed_by, operation)
    values (new.feature_key, new.enabled, new.updated_by, lower(tg_op));
    return new;
end;
$$;

drop trigger if exists feature_settings_audit on public.feature_settings;
create trigger feature_settings_audit before insert or update or delete on public.feature_settings
    for each row execute function public.feature_settings_audit();

drop function if exists public.feature_tree();
create or replace function public.feature_tree()
returns table (
    key text, parent_key text, kind text, category text,
    label_de text, label_en text, sort_order integer,
    locked boolean, default_enabled boolean, chosen boolean,
    effective boolean, requires text[], off_because text,
    shown_in_admin_panel boolean
)
language sql stable set search_path to 'public'
as $$
  with live as (select key from public.live_features())
  select p.key, p.parent_key, p.kind, p.category,
         p.label_de, p.label_en, p.sort_order,
         p.locked, p.default_enabled, f.enabled,
         p.key in (select key from live),
         coalesce((select array_agg(fr.requires_key order by fr.requires_key)
                     from public.feature_requirements fr
                    where fr.feature_key = p.key), '{}'),
         case
           when p.key in (select key from live) then null
           when not coalesce(f.enabled, p.default_enabled) then 'switched off here'
           when p.parent_key is not null and p.parent_key not in (select key from live)
             then p.parent_key
           else (select fr.requires_key
                   from public.feature_requirements fr
                  where fr.feature_key = p.key
                    and fr.requires_key not in (select key from live)
                  order by fr.requires_key
                  limit 1)
         end,
         p.shown_in_admin_panel
    from public.permissions p
    left join public.feature_settings f on f.feature_key = p.key
   order by p.sort_order, p.key;
$$;

revoke execute on function public.feature_tree() from public, anon;
grant execute on function public.feature_tree() to authenticated;

commit;

-- ===================================================================== 0043_referrer_bonus_stage_timing.sql

-- referrer_payout_timing and referrer_tier_counts_status used to be two hard-wired cases each
-- (on_suggestion/after_commission_paid, suggested/paid). Both now pick from the same three stages a
-- deal already passes through: notarised_on is set, the deal is invoiced (create_deal_invoices sets
-- deals.status = 'invoiced' only once every party's invoice in the batch exists), or every commission
-- invoice on the deal is paid. Column names kept: what they hold hasn't changed, only how precisely.

begin;

alter table public.bonus_settings
    drop constraint if exists bonus_settings_referrer_payout_timing_check,
    drop constraint if exists bonus_settings_referrer_tier_counts_status_check;

update public.bonus_settings set referrer_payout_timing = case referrer_payout_timing
    when 'on_suggestion' then 'notarised'
    when 'after_commission_paid' then 'commission_received'
    else referrer_payout_timing
end;

update public.bonus_settings set referrer_tier_counts_status = case referrer_tier_counts_status
    when 'suggested' then 'notarised'
    when 'paid' then 'commission_received'
    else referrer_tier_counts_status
end;

alter table public.bonus_settings
    alter column referrer_payout_timing set default 'invoiced',
    alter column referrer_tier_counts_status set default 'invoiced',
    add constraint bonus_settings_referrer_payout_timing_check
        check (referrer_payout_timing in ('notarised', 'invoiced', 'commission_received')),
    add constraint bonus_settings_referrer_tier_counts_status_check
        check (referrer_tier_counts_status in ('notarised', 'invoiced', 'commission_received'));

create or replace function public.deal_stage_reached(p_deal_id uuid, p_stage text) returns boolean
language sql stable security definer set search_path to 'public'
as $$
  select case p_stage
    when 'notarised' then exists (
        select 1 from public.deals where id = p_deal_id and notarised_on is not null
    )
    when 'invoiced' then exists (
        select 1 from public.deals where id = p_deal_id and status = 'invoiced'
    )
    when 'commission_received' then
        exists (
            select 1 from public.outgoing_invoices
             where deal_id = p_deal_id and kind = 'commission' and deleted_at is null
        )
        and not exists (
            select 1 from public.outgoing_invoices
             where deal_id = p_deal_id and kind = 'commission' and deleted_at is null
               and status <> 'paid'
        )
    else false
  end;
$$;

revoke execute on function public.deal_stage_reached(uuid, text) from public, anon;
grant execute on function public.deal_stage_reached(uuid, text) to authenticated;

create or replace function public.referrer_bonus_tier(p_referrer_customer_id uuid, p_earned_on date)
returns integer
language plpgsql stable security definer set search_path to 'public'
as $$
declare
  v_settings public.bonus_settings;
  v_count integer;
begin
  select * into v_settings from public.bonus_settings;

  select count(*) into v_count
    from public.deal_referrer_bonuses b
   where (
     case v_settings.referrer_tier_scope
       when 'company_wide' then true
       else b.referrer_customer_id = p_referrer_customer_id
     end
   )
     and b.status <> 'cancelled'
     and public.deal_stage_reached(b.deal_id, v_settings.referrer_tier_counts_status)
     and (
       case v_settings.referrer_tier_reset
         when 'never' then true
         else extract(year from b.earned_on) = extract(year from p_earned_on)
       end
     );

  return v_count + 1;
end;
$$;

-- Mark-paid had no stage gate at all before this: any bonus could be marked paid the moment it was
-- suggested, regardless of referrer_payout_timing. An RPC, not a plain update, so the check runs
-- where it cannot be skipped, the same way create_deal_invoices and create_referrer_credit_note
-- validate their own preconditions server-side rather than trusting the caller.
create or replace function public.mark_referrer_bonus_paid(p_bonus_id uuid) returns void
language plpgsql security invoker set search_path to 'public'
as $$
declare
  v_bonus public.deal_referrer_bonuses;
  v_stage text;
begin
  select * into v_bonus from public.deal_referrer_bonuses where id = p_bonus_id;
  if not found then
    raise exception 'mark_referrer_bonus_paid: bonus % not found', p_bonus_id;
  end if;
  if v_bonus.status <> 'suggested' then
    raise exception 'mark_referrer_bonus_paid: bonus % is not suggested', p_bonus_id
      using errcode = 'check_violation';
  end if;

  select referrer_payout_timing into v_stage from public.bonus_settings;
  if not public.deal_stage_reached(v_bonus.deal_id, v_stage) then
    raise exception 'mark_referrer_bonus_paid: deal % has not reached the % stage yet',
      v_bonus.deal_id, v_stage using errcode = 'check_violation';
  end if;

  update public.deal_referrer_bonuses set status = 'paid' where id = p_bonus_id;
end;
$$;

revoke execute on function public.mark_referrer_bonus_paid(uuid) from public, anon;
grant execute on function public.mark_referrer_bonus_paid(uuid) to authenticated;

commit;

-- ===================================================================== 0044_lexoffice_push_missing_config_error.sql

begin;

create or replace function public.lexoffice_document_push_now() returns trigger
    language plpgsql security definer set search_path to 'public'
    as $$
declare
  v_key text;
  v_url text;
begin
  v_key := public.deployment_secret('service_role_key');
  v_url := public.deployment_secret('project_url');
  if v_key is null or v_url is null then
    update public.documents
       set lexoffice_sync_error = 'Lexware handover is not set up on this deployment yet: '
         || 'project_url/service_role_key are missing from the vault.'
     where id = new.id;
    return null;
  end if;

  perform net.http_post(
    url := rtrim(v_url, '/') || '/functions/v1/lexoffice-document-push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object('document_id', new.id),
    timeout_milliseconds := 30000
  );
  return null;
end;
$$;

commit;

-- ===================================================================== 0045_lexoffice_open_amount.sql

-- What Lexware still shows as outstanding on a voucher it has not fully settled. Without it a
-- part payment is indistinguishable from no payment at all: the sync only ever wrote paid_at, and
-- only once the whole amount had arrived.

begin;

alter table public.documents
    add column if not exists lexoffice_open_amount numeric(14, 2);

commit;

-- ===================================================================== 0046_purge_demo_data.sql

-- Onboarding practice seeds real rows marked is_demo, in documents/companies/suppliers/properties/
-- bank_transactions. Finishing or restarting the tutorial discards the ones from that run, but
-- only those two actions ever do, and both are a soft delete (deleted_at), never a real one -- so
-- a session that is simply abandoned (closed tab, navigated away) leaves rows behind forever, and
-- nothing in this app ever removes a soft-deleted row either way. That is correct for a client's
-- own trashed documents (bookkeeping retention law applies), but is_demo data is synthetic and
-- reproducible on demand, so there is no reason to keep it once nobody is coming back to resume.
--
-- A practice run finishes in minutes, so 48 hours is a generous margin before treating one as
-- abandoned, not an attempt to guess an exact session length.

begin;

create or replace function public.purge_stale_demo_data() returns void
    language plpgsql security definer set search_path to 'public'
as $$
declare
  v_cutoff timestamptz := now() - interval '48 hours';
  v_demo_deal_ids uuid[];
  v_demo_customer_ids uuid[];
begin
  -- deals/customers/outgoing_invoices/manual_bookings carry no is_demo column of their own
  -- (0010_access.sql's company_demo_visible() reads the parent's instead), but a practice run
  -- creates them tied to a demo property/company all the same, and they block deleting that
  -- property/company (NO ACTION foreign keys) if left behind. Collected once so every statement
  -- below agrees on the same set.
  select array_agg(d.id) into v_demo_deal_ids
    from public.deals d join public.properties p on p.id = d.property_id
   where p.is_demo and p.created_at < v_cutoff;
  select array_agg(c.id) into v_demo_customer_ids
    from public.customers c join public.companies co on co.id = c.company_id
   where co.is_demo and co.created_at < v_cutoff;

  delete from public.outgoing_invoices
   where deal_id = any (v_demo_deal_ids) or customer_id = any (v_demo_customer_ids);
  delete from public.broker_bonuses where deal_id = any (v_demo_deal_ids);
  delete from public.deal_donations where deal_id = any (v_demo_deal_ids);
  delete from public.deal_referrer_bonuses
   where deal_id = any (v_demo_deal_ids) or referrer_customer_id = any (v_demo_customer_ids);
  delete from public.deal_parties where customer_id = any (v_demo_customer_ids);
  delete from public.deals where id = any (v_demo_deal_ids);
  delete from public.customers where id = any (v_demo_customer_ids);

  delete from public.manual_bookings mb
   where exists (select 1 from public.properties p where p.id = mb.property_id and p.is_demo and p.created_at < v_cutoff)
      or exists (select 1 from public.companies co where co.id = mb.company_id and co.is_demo and co.created_at < v_cutoff);

  alter table public.document_history disable trigger trg_guard_document_history_row;
  delete from public.document_history
   where document_id in (select id from public.documents where is_demo and created_at < v_cutoff);
  alter table public.document_history enable trigger trg_guard_document_history_row;

  delete from public.documents where is_demo and created_at < v_cutoff;
  delete from public.bank_transactions where is_demo and created_at < v_cutoff;

  -- Same reasoning as document_history above: refuse_deleting_default_bank_account protects a
  -- real supplier from losing its default account with no replacement, which does not apply when
  -- the supplier itself is being removed in the same statement.
  alter table public.supplier_bank_accounts disable trigger trg_refuse_deleting_default_bank_account;
  delete from public.suppliers where is_demo and created_at < v_cutoff;
  alter table public.supplier_bank_accounts enable trigger trg_refuse_deleting_default_bank_account;

  delete from public.properties where is_demo and created_at < v_cutoff;
  delete from public.companies where is_demo and created_at < v_cutoff;
exception
  -- A row this can't reach yet fails loudly to an administrator instead of silently every night.
  when others then
    perform public.notify_administrators(
      'The nightly demo-data cleanup failed: ' || sqlerrm,
      '/administration', 'purge_stale_demo_data');
end;
$$;

revoke execute on function public.purge_stale_demo_data() from public, anon, authenticated;

-- Direct pg_cron, not the scheduled_jobs/Edge Function pattern (0013_scheduled_jobs.sql): this is
-- pure database work with no external call to make and no vault credential to resolve, so routing
-- it through an Edge Function would only add a network hop for nothing. Shipped on for every
-- client, unlike that table's own rows -- there is no client who would want abandoned practice
-- data kept forever, so this is not a per-tenant choice.
do $$
begin
  if to_regclass('cron.job') is not null then
    if exists (select 1 from cron.job where jobname = 'purge-stale-demo-data') then
      perform cron.unschedule('purge-stale-demo-data');
    end if;
    perform cron.schedule('purge-stale-demo-data', '0 3 * * *',
                          'select public.purge_stale_demo_data()');
  end if;
end
$$;

commit;

-- ===================================================================== 0047_lexoffice_invoice_file_fetch.sql

begin;

alter table public.outgoing_invoices
    add column if not exists lexoffice_file_fetched_at timestamptz,
    add column if not exists lexoffice_sync_error text;

create unique index if not exists outgoing_invoice_files_one_per_invoice
    on public.outgoing_invoice_files (outgoing_invoice_id);

